/**
 * Brings the groupiron.men group ironman dashboard into the client.
 * <p>
 * <b>What this plugin does:</b> it reads the data your group already publishes to your
 * groupiron.men group (or your own self-hosted instance) and displays it in the client: a
 * read-only group bank, group levels on the Skills tab, member markers on the world map, and
 * a vitals panel. When the official Group Ironmen Tracker plugin is not running it also
 * publishes your own character data in the same format, so the plugin works standalone.
 * <p>
 * <b>What it deliberately does not do:</b> it adds no menu entries of any kind, so nothing
 * it draws can cause an action to be sent to the server. It never creates, modifies, hides,
 * unhides, reparents, moves or resizes any game widget or click zone; every view it provides
 * is its own drawing. It draws nothing on the minimap, and it offers no combat information
 * about anyone outside your own opted-in group.
 * <p>
 * One optional feature, off by default, draws in the game scene: group members on other
 * worlds as translucent figures. They can't be clicked, the server never knows about them,
 * and they're never drawn in the Wilderness or on PvP worlds.
 */
@Slf4j
@PluginDescriptor(
	name = "Group Ironmen Tracker In-Game Companion",
	description = "View your group ironman team's banks, skills, stats and map positions in-game",
	tags = {"group", "ironman", "gim", "bank", "team", "map", "skills"}
)
public class GroupIronmenCompanionPlugin extends Plugin
{
	/** Game ticks between periodic world map marker rebuilds, about six seconds. */
	private static final int MAP_REFRESH_TICKS = 10;

	// Poll rate while logged out. See pollIntervalMillis.
	private static final long IDLE_POLL_MILLIS = 30_000;


	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private KeyManager keyManager;

	@Inject
	private MouseManager mouseManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private GroupIronmenCompanionConfig config;

	@Inject
	private GroupApi api;

	@Inject
	private GroupState groupState;

	@Inject
	private GroupUploader uploader;

	@Inject
	private TrackerDetector trackerDetector;

	@Inject
	private ClientInputState inputState;

	@Inject
	private GroupMapMarkers mapMarkers;

	@Inject
	private GroupMapOverlay mapOverlay;

	@Inject
	private GroupMapInput mapInput;

	@Inject
	private WorldMapPlusBridge worldMapPlus;

	@Inject
	private RouteTracker routeTracker;

	@Inject
	private GroupBankViewer bankViewer;

	@Inject
	private GroupBankOverlay bankOverlay;

	@Inject
	private GroupBankTabOverlay bankTabOverlay;

	@Inject
	private GroupBankInput bankInput;

	@Inject
	private SkillHoverOverlay skillHoverOverlay;

	@Inject
	private GameSprites gameSprites;

	@Inject
	private GroupStatusOverlay statusOverlay;

	@Inject
	private GroupScenePresence scenePresence;

	@Inject
	private GhostLabelOverlay ghostLabelOverlay;

	@Inject
	private ActivityTracker activityTracker;

	/** Swapped on config changes and read from the polling thread, so it must be volatile. */
	private volatile GroupPanel panel;
	private NavigationButton navButton;

	/**
	 * Polling runs on the plugin's own thread rather than RuneLite's shared executor: the
	 * work is blocking network I/O, and a slow server should never delay another plugin's
	 * scheduled tasks.
	 */
	private ScheduledExecutorService pollExecutor;
	private ScheduledFuture<?> pollTask;

	private final Runnable stateListener = this::onGroupStateChanged;
	private volatile String localPlayerName;
	private volatile long lastPollMillis;
	private boolean varsChanged;
	private int ticksSinceMapRefresh;

	private final HotkeyListener bankHotkey = new HotkeyListener(() -> config.bankHotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			if (config.bankViewer())
			{
				if (bankViewer.isOpen())
				{
					bankInput.closeAll();
				}
				else
				{
					bankInput.openBesideBank();
				}
			}
		}
	};

	@Provides
	GroupIronmenCompanionConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GroupIronmenCompanionConfig.class);
	}

	// ------------------------------------------------------------------
	// Lifecycle
	// ------------------------------------------------------------------

	@Override
	protected void startUp()
	{
		applyPalette();
		groupState.setPollSeconds(config.pollSeconds());
		groupState.addListener(stateListener);

		overlayManager.add(bankOverlay);
		overlayManager.add(bankTabOverlay);
		overlayManager.add(skillHoverOverlay);
		overlayManager.add(statusOverlay);
		overlayManager.add(mapOverlay);
		overlayManager.add(ghostLabelOverlay);

		keyManager.registerKeyListener(bankHotkey);
		mouseManager.registerMouseListener(bankInput);
		mouseManager.registerMouseWheelListener(bankInput);
		mouseManager.registerMouseListener(mapInput);

		if (config.showSidePanel())
		{
			addSidePanel();
		}

		lastPollMillis = 0;
		pollExecutor = Executors.newSingleThreadScheduledExecutor(runnable ->
		{
			Thread thread = new Thread(runnable, "group-ironmen-companion-poll");
			thread.setDaemon(true);
			return thread;
		});
		pollTask = pollExecutor.scheduleWithFixedDelay(this::poll, 1, 1, TimeUnit.SECONDS);
	}

	@Override
	protected void shutDown()
	{
		if (pollTask != null)
		{
			pollTask.cancel(false);
			pollTask = null;
		}
		if (pollExecutor != null)
		{
			pollExecutor.shutdownNow();
			pollExecutor = null;
		}

		groupState.removeListener(stateListener);

		overlayManager.remove(bankOverlay);
		overlayManager.remove(bankTabOverlay);
		overlayManager.remove(skillHoverOverlay);
		overlayManager.remove(statusOverlay);
		overlayManager.remove(mapOverlay);
		overlayManager.remove(ghostLabelOverlay);

		keyManager.unregisterKeyListener(bankHotkey);
		mouseManager.unregisterMouseListener(bankInput);
		mouseManager.unregisterMouseWheelListener(bankInput);
		mouseManager.unregisterMouseListener(mapInput);

		removeSidePanel();

		bankViewer.reset();
		clientThread.invoke(uploader::reset);
		clientThread.invoke(routeTracker::stop);
		clientThread.invoke(mapMarkers::clear);
		clientThread.invoke(scenePresence::reset);
		clientThread.invoke(worldMapPlus::reset);
		groupState.reset();
	}

	// ------------------------------------------------------------------
	// Polling
	// ------------------------------------------------------------------

	/** Runs off the client thread once a second, and fetches at the configured interval. */
	/**
	 * Time between requests. While nobody's logged in it drops to every 30 seconds: the side
	 * panel still updates at the login screen, but an idle client isn't hitting the group's
	 * server every few seconds for nothing. Logging in takes effect on the next check.
	 */
	static long pollIntervalMillis(int pollSeconds, boolean loggedIn)
	{
		long configured = Math.max(1, pollSeconds) * 1000L;
		return loggedIn ? configured : Math.max(configured, IDLE_POLL_MILLIS);
	}

	private void poll()
	{
		try
		{
			long now = System.currentTimeMillis();
			if (now - lastPollMillis < pollIntervalMillis(config.pollSeconds(), inputState.isLoggedIn()))
			{
				return;
			}
			lastPollMillis = now;

			if (!api.hasCredentials())
			{
				setStatus("Enter your group name and token in the plugin settings.");
				return;
			}

			try
			{
				// Noted before the cursor, so a reset between the two reads still drops the reply.
				int generation = groupState.getGeneration();
				MemberDto[] response = api.getGroupData(groupState.getFromTime());
				if (response != null)
				{
					groupState.applyUpdate(response, generation);
					setStatus(describeConnection());
				}
			}
			catch (GroupApi.NotAuthorisedException e)
			{
				setStatus("The server rejected your group name or token.");
				groupState.reset();
			}

			uploader.flush(localPlayerName);
		}
		catch (Exception e)
		{
			log.warn("Group Ironmen Tracker In-Game Companion: poll failed", e);
		}
		catch (Error e)
		{
			// Anything escaping a scheduled task cancels every later run, silently, which left
			// the group frozen and everyone drifting to offline. Log it and keep polling.
			log.error("Group Ironmen Tracker In-Game Companion: poll failed", e);
		}
	}

	private String describeConnection()
	{
		StringBuilder status = new StringBuilder();
		status.append("Group ").append(api.getGroupName());

		if (trackerDetector.isTrackerActive())
		{
			status.append(" · reading only (tracker plugin is sharing your data)");
		}
		else if (uploader.shouldUpload())
		{
			status.append(" · ").append(uploader.getStatus().toLowerCase(java.util.Locale.ROOT));
		}
		else
		{
			status.append(" · read only");
		}
		return status.toString();
	}

	private void refreshPanel()
	{
		GroupPanel current = panel;
		if (current != null)
		{
			current.refresh();
		}
	}

	private void setStatus(String status)
	{
		GroupPanel current = panel;
		if (current != null)
		{
			current.setStatus(status);
		}
	}

	private void onGroupStateChanged()
	{
		refreshPanel();
		bankViewer.markDirty();
		clientThread.invoke(mapMarkers::refresh);
	}

	// ------------------------------------------------------------------
	// Game events
	// ------------------------------------------------------------------

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		inputState.setLoggedIn(event.getGameState() == GameState.LOGGED_IN);
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			localPlayerName = null;
			bankInput.closeAll();
			routeTracker.stop();
			// The scene is about to be replaced, so every figure in it is stale.
			clientThread.invoke(scenePresence::clear);
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player local = client.getLocalPlayer();
		String name = local == null ? null : local.getName();
		if (name != null && !name.equals(localPlayerName))
		{
			// Reset before publishing the new name, or a flush in between could post what
			// was staged for the previous character under this one's name.
			uploader.reset();
			localPlayerName = name;
			groupState.setLocalPlayerName(name);
			uploader.snapshot();
		}

		uploader.onVitalsChanged();
		uploader.onPositionChanged();
		uploader.onGameTick();

		if (varsChanged)
		{
			varsChanged = false;
			uploader.onQuestsChanged();
			uploader.onDiaryChanged();
		}

		// Follows the routed member as they move, and ends the route once we reach them.
		if (config.mapPanelRouting())
		{
			routeTracker.update();
		}

		// Markers are rebuilt immediately whenever group data changes. This periodic pass
		// only exists so members ageing into the offline threshold drop off on their own.
		// The side panel's online state and "last seen" times age the same way.
		if (++ticksSinceMapRefresh >= MAP_REFRESH_TICKS)
		{
			ticksSinceMapRefresh = 0;
			mapMarkers.refresh();

			GroupPanel current = panel;
			if (current != null)
			{
				current.refreshMembersIfShown();
			}
		}

		scenePresence.onGameTick();
	}

	/**
	 * Input state first, since the mouse and key handlers read it from AWT threads where they
	 * can't ask the client. Then the scene figures, every frame so they glide.
	 */
	@Subscribe
	public void onClientTick(ClientTick event)
	{
		inputState.setLoggedIn(client.getGameState() == GameState.LOGGED_IN);
		inputState.setMenuOpen(client.isMenuOpen());

		scenePresence.onClientTick();
	}

	/**
	 * Leaves only Cancel in the game's menu while the mouse is over the group bank window or
	 * its Group tab. The game builds its menu from whatever is under the mouse in the scene,
	 * so without this, hovering an item in the window showed "Enter Portal" or "Walk here"
	 * for whatever stood behind it, and a right-click offered those options. Nothing is ever
	 * added, and nothing changes while the menu is open or the mouse is anywhere else.
	 */
	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		if (client.isMenuOpen())
		{
			return;
		}
		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		if (mouse == null || !bankInput.covers(new java.awt.Point(mouse.getX(), mouse.getY())))
		{
			return;
		}

		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		int kept = 0;
		for (MenuEntry entry : entries)
		{
			if (entry.getType() == MenuAction.CANCEL)
			{
				kept++;
			}
		}
		if (kept == entries.length)
		{
			return;
		}

		MenuEntry[] cancelOnly = new MenuEntry[kept];
		int i = 0;
		for (MenuEntry entry : entries)
		{
			if (entry.getType() == MenuAction.CANCEL)
			{
				cancelOnly[i++] = entry;
			}
		}
		menu.setMenuEntries(cancelOnly);
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		uploader.onSkillsChanged();
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		uploader.onItemContainerChanged(event.getContainerId(), event.getItemContainer());
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{
		// Quest and diary progress are both var-driven, but vars change many times a tick and
		// a quest scan walks every quest in the game. Flag it and do the work once per tick.
		varsChanged = true;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && config.bankViewer() && config.bankAutoOpen())
		{
			bankInput.openBesideBank();
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN && config.bankCloseWithBank())
		{
			bankInput.closeAll();
		}
	}

	/**
	 * Each bridge ignores messages that aren't its own. Both keep their state on the client
	 * thread, and any plugin can post from any thread, so they're handled there. When the post
	 * already came from the client thread, invoke runs it straight away.
	 */
	@Subscribe
	public void onPluginMessage(PluginMessage event)
	{
		clientThread.invoke(() ->
		{
			routeTracker.onPluginMessage(event);
			worldMapPlus.onPluginMessage(event);
		});
	}

	@Subscribe
	public void onPluginChanged(PluginChanged event)
	{
		// The tracker may have just started or stopped; don't wait out the detector's cache.
		trackerDetector.invalidate();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (GroupApi.TRACKER_CONFIG_GROUP.equals(event.getGroup()))
		{
			onTrackerConfigChanged(event.getKey());
			return;
		}
		if (!GroupIronmenCompanionConfig.GROUP.equals(event.getGroup()))
		{
			// Turning an interface reskin on, off or to another pack restyles the group bank too.
			gameSprites.onConfigChanged(event.getGroup(), event.getKey());
			return;
		}

		switch (event.getKey())
		{
			case "groupName":
			case "groupToken":
			case "baseUrlOverride":
				resetConnection();
				break;

			case "pollSeconds":
				groupState.setPollSeconds(config.pollSeconds());
				break;

			case "showSidePanel":
				if (config.showSidePanel())
				{
					addSidePanel();
				}
				else
				{
					removeSidePanel();
				}
				break;

			case "bankViewer":
				if (!config.bankViewer())
				{
					bankInput.closeAll();
				}
				break;

			case "natureRuneCost":
				// The All tab's order and the footer total are worked out when rows are built.
				bankViewer.markDirty();
				break;

			case "worldMapMarkers":
			case "worldMapEntrances":
			case "worldMapOffline":
				clientThread.invoke(mapMarkers::refresh);
				break;

			case "scenePresence":
			case "scenePresenceOpponents":
			case "scenePresenceTransparency":
				// Transparency is baked into the built models, so a change has to drop them.
				clientThread.invoke(scenePresence::reset);
				break;

			case "offlineAfterMinutes":
				clientThread.invoke(mapMarkers::refresh);
				refreshPanel();
				break;

			case "panelShowActivity":
			case "panelShowOffline":
			case "panelShowSelf":
				refreshPanel();
				break;

			case "uploadMode":
				clientThread.invoke(uploader::reset);
				break;

			case "mapPanel":
			case "mapPanelRouting":
				if (!config.mapPanel() || !config.mapPanelRouting())
				{
					clientThread.invoke(routeTracker::stop);
				}
				break;

			default:
				if (event.getKey().startsWith("colour"))
				{
					applyPalette();
				}
				break;
		}
	}

	/**
	 * The tracker's settings decide whether it uploads, and they are the credentials used
	 * when this plugin's own are blank, so a change there matters as much as one here.
	 */
	private void onTrackerConfigChanged(String key)
	{
		trackerDetector.invalidate();
		switch (key)
		{
			case "groupName":
			case "groupToken":
			case "baseUrlOverride":
				resetConnection();
				break;
			default:
				break;
		}
	}

	/** Starts over with whichever group the settings now point at, fetching it in full. */
	private void resetConnection()
	{
		groupState.reset();
		// Config changes come in off the client thread, and both of these live on it.
		clientThread.invoke(uploader::reset);
		clientThread.invoke(worldMapPlus::reset);
		lastPollMillis = 0;
	}

	// ------------------------------------------------------------------
	// Side panel
	// ------------------------------------------------------------------

	private void addSidePanel()
	{
		if (panel != null)
		{
			return;
		}

		panel = new GroupPanel(groupState, config, activityTracker, itemManager, clientThread);
		navButton = NavigationButton.builder()
			.tooltip("Group Ironmen Tracker In-Game Companion")
			.icon(buildIcon())
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);

		panel.refresh();
		panel.setStatus(api.hasCredentials()
			? describeConnection()
			: "Enter your group name and token in the plugin settings.");
	}

	private void removeSidePanel()
	{
		if (navButton != null)
		{
			clientToolbar.removeNavigation(navButton);
			navButton = null;
		}
		panel = null;
	}

	private void applyPalette()
	{
		groupState.setPalette(new Color[]{
			config.colour1(), config.colour2(), config.colour3(), config.colour4(), config.colour5()
		});
	}

	/** The sidebar icon, drawn at runtime so the plugin ships no image assets. */
	private static BufferedImage buildIcon()
	{
		BufferedImage image = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

			// Three overlapping heads, reading as a small group.
			g.setColor(new Color(0x4F, 0xC3, 0xF7));
			g.fillOval(0, 4, 8, 8);
			g.setColor(new Color(0xEF, 0x53, 0x50));
			g.fillOval(8, 4, 8, 8);
			g.setColor(new Color(0x66, 0xBB, 0x6A));
			g.fillOval(4, 0, 8, 8);

			g.setColor(new Color(0, 0, 0, 160));
			g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 8));
			g.drawString("G", 6, 9);
		}
		finally
		{
			g.dispose();
		}
		return image;
	}
}

package com.groupironmencompanion;

import com.groupironmencompanion.api.GroupApi;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;

/**
 * Detects whether the official Group Ironmen Tracker plugin is installed, running and set
 * up to upload.
 * <p>
 * When it is, this plugin stays purely a reader: the tracker owns uploading and we would
 * only duplicate its traffic. When it is not, our own uploader takes over so the plugin
 * works standalone.
 * <p>
 * The check compares plugin class names, which is plain {@code Object.getClass()} and not
 * reflection: nothing is loaded, invoked or made accessible.
 * <p>
 * The answer is cached briefly because it is consulted several times per game tick and
 * scanning the whole plugin list that often is wasteful. The window is short enough that
 * enabling or disabling the tracker plugin takes effect almost immediately.
 */
@Singleton
public class TrackerDetector
{
	private static final String TRACKER_CLASS = "men.groupiron.GroupIronmenTrackerPlugin";
	private static final long CACHE_MILLIS = 5000;

	@Inject
	private PluginManager pluginManager;

	@Inject
	private GroupApi api;

	private volatile long checkedAt;
	private volatile boolean active;
	private volatile boolean installed;

	/**
	 * True when the official tracker plugin is running and has a group name and token, which
	 * is when it uploads. Enabled is not enough: a plugin that failed to start, or one with
	 * no credentials, uploads nothing, and then this plugin has to.
	 */
	public boolean isTrackerActive()
	{
		refreshIfStale();
		return active;
	}

	/** True when the tracker plugin is installed, whether or not it is currently enabled. */
	public boolean isTrackerInstalled()
	{
		refreshIfStale();
		return installed;
	}

	/**
	 * Forces the next query to re-scan, used when plugin state is known to have changed.
	 * Synchronized so it can't land mid-scan and be overwritten by that scan's stale result.
	 */
	public synchronized void invalidate()
	{
		checkedAt = 0;
	}

	// Called from both the client and polling threads.
	private synchronized void refreshIfStale()
	{
		long now = System.currentTimeMillis();
		if (now - checkedAt < CACHE_MILLIS)
		{
			return;
		}

		boolean foundInstalled = false;
		boolean foundActive = false;
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (TRACKER_CLASS.equals(plugin.getClass().getName()))
			{
				foundInstalled = true;
				foundActive = pluginManager.isPluginActive(plugin) && api.trackerHasCredentials();
				break;
			}
		}

		installed = foundInstalled;
		active = foundActive;
		checkedAt = now;
	}
}

package com.groupironmencompanion.activity;

import com.groupironmencompanion.data.GroupSkill;
import com.groupironmencompanion.place.Place;
import java.time.Duration;
import java.time.Instant;
import java.util.Objects;
import javax.annotation.Nullable;

/**
 * A best guess at what a member is doing, worked out from the data their tracker shares.
 * <p>
 * Immutable, so the polling thread can publish it and the client and Swing threads read it
 * without locks. The words are kept in parts rather than as one finished string, so each view
 * can leave the place out, and so an idle member's "(3m)" keeps counting between polls.
 */
public final class Activity
{
	public enum Kind
	{
		/** Not updated for longer than the offline threshold. */
		OFFLINE,
		/** Hitpoints reached zero. */
		DIED,
		/** A live interaction with a health bar, or combat XP coming in. Only the first has a target. */
		FIGHTING,
		/** At a fishing spot, or gaining Fishing experience while interacting. */
		FISHING,
		/** Gaining Thieving experience while interacting with someone. */
		PICKPOCKETING,
		/** Interacting with another member of the group. */
		WITH_MEMBER,
		/** Any other live interaction with an NPC. */
		TALKING,
		/** Aboard a boat. */
		SAILING,
		/** Gaining experience; combat skills together count as one. */
		SKILLING,
		/** Recently finished a quest. */
		QUEST_COMPLETED,
		/** Started a quest while we were watching and has not finished it. */
		QUESTING,
		/** Their bank changed a moment ago. */
		BANKING,
		/** Moved further in one update than anyone can walk. */
		TELEPORTED,
		/** Doing something we cannot see. */
		ACTIVE,
		/** Nothing has changed for a while. */
		IDLE
	}

	private final Kind kind;
	private final String lead;
	private final String bare;
	private final String preposition;
	private final Place place;
	private final String suffix;
	private final Instant since;
	private final GroupSkill skill;
	private final String target;

	/**
	 * @param lead the words before the place, e.g. "Fishing"; empty to start with the place
	 * @param bare what to say when the place is unknown or hidden, e.g. "Fishing"
	 * @param preposition joins the lead to the place, e.g. "at"; null when no place is said
	 * @param suffix said last whatever happens, e.g. " (43%)"
	 * @param since when this activity began; for {@link Kind#IDLE}, when they last did anything
	 */
	Activity(Kind kind, String lead, String bare, @Nullable String preposition, @Nullable Place place,
		String suffix, Instant since)
	{
		this(kind, lead, bare, preposition, place, suffix, since, null, null);
	}

	private Activity(Kind kind, String lead, String bare, @Nullable String preposition, @Nullable Place place,
		String suffix, Instant since, @Nullable GroupSkill skill, @Nullable String target)
	{
		this.skill = skill;
		this.target = target;
		this.kind = kind;
		this.lead = lead;
		this.bare = bare;
		this.preposition = preposition;
		this.place = preposition == null ? null : place;
		this.suffix = suffix;
		this.since = since;
	}

	public Kind getKind()
	{
		return kind;
	}

	@Nullable
	public Place getPlace()
	{
		return place;
	}

	public Instant getSince()
	{
		return since;
	}

	/** The skill behind it, where there is one: the text can't say, since all combat reads "Fighting". */
	@Nullable
	public GroupSkill getSkill()
	{
		return skill;
	}

	/** Who they're interacting with, when this guess comes from a live interaction. */
	@Nullable
	public String getTarget()
	{
		return target;
	}

	Activity withSkill(@Nullable GroupSkill skill)
	{
		return new Activity(kind, lead, bare, preposition, place, suffix, since, skill, target);
	}

	Activity withTarget(@Nullable String target)
	{
		return new Activity(kind, lead, bare, preposition, place, suffix, since, skill, target);
	}

	/** The same activity, but starting when an earlier copy of it did. */
	Activity startingAt(Instant start)
	{
		return new Activity(kind, lead, bare, preposition, place, suffix, start, skill, target);
	}

	/** Whether two activities say the same thing, ignoring when they started. */
	boolean sameAs(@Nullable Activity other)
	{
		return other != null && kind == other.kind && lead.equals(other.lead) && bare.equals(other.bare)
			&& Objects.equals(preposition, other.preposition) && Objects.equals(place, other.place)
			&& suffix.equals(other.suffix);
	}

	/**
	 * The activity as a line of text: "Fishing at Catherby", "Fighting Goblin (43%)",
	 * "Idle at Lumbridge (3m)".
	 *
	 * @param now the time to measure an idle spell to
	 * @param withPlace false to leave the place out: "Fishing", "Idle (3m)"
	 */
	public String describe(Instant now, boolean withPlace)
	{
		StringBuilder text = new StringBuilder();
		// A place with no name (a blank label or area name) reads as no place at all.
		boolean named = withPlace && place != null && place.getName() != null && !place.getName().trim().isEmpty();
		String phrase = named ? place.phrase(preposition).trim() : "";
		if (!phrase.isEmpty())
		{
			if (lead.isEmpty())
			{
				text.append(Character.toUpperCase(phrase.charAt(0))).append(phrase, 1, phrase.length());
			}
			else
			{
				text.append(lead).append(' ').append(phrase);
			}
		}
		else
		{
			text.append(bare);
		}
		text.append(suffix);

		if (kind == Kind.IDLE)
		{
			text.append(" (").append(formatDuration(Duration.between(since, now))).append(')');
		}
		return text.toString();
	}

	/** "45s", "3m", "2h": the same coarse units the panel's "last seen" uses. */
	static String formatDuration(Duration duration)
	{
		long seconds = Math.max(0, duration.getSeconds());
		if (seconds < 60)
		{
			return seconds + "s";
		}
		if (seconds < 3600)
		{
			return (seconds / 60) + "m";
		}
		if (seconds < 86_400)
		{
			return (seconds / 3600) + "h";
		}
		return (seconds / 86_400) + "d";
	}

	@Override
	public String toString()
	{
		return kind + ": " + describe(since, true);
	}
}

package com.groupironmencompanion.activity;

import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupSkill;
import com.groupironmencompanion.place.Place;
import java.time.Duration;
import java.time.Instant;
import java.util.Deque;
import java.util.EnumSet;
import java.util.Locale;
import java.util.Set;
import java.util.function.Function;
import java.util.function.Predicate;
import javax.annotation.Nullable;
import net.runelite.api.coords.WorldPoint;

/**
 * Turns what we know about a member into a best guess at what they are doing.
 * <p>
 * The tracker shares no animation or activity field, and the server cannot take a new one,
 * so this works only from what changed: experience, position, the boat flag, quest states,
 * the bank, and the NPC they are interacting with. Rules are tried in order and the first
 * that matches wins, most specific first. Objects (trees, rocks, ranges) never show up as an
 * interaction, which is why most skilling is recognised by its experience instead.
 * <p>
 * A pure function of its inputs, so every rule can be tested without a client.
 */
final class ActivityRules
{
	/** How far back experience counts towards "what are they doing now". */
	static final Duration XP_WINDOW = Duration.ofSeconds(90);

	/**
	 * The least time an interaction stays live after we last saw it refreshed. The real
	 * window also grows with the poll interval, so a slow refresh rate does not make every
	 * interaction stale on arrival.
	 */
	static final Duration MIN_INTERACTION_WINDOW = Duration.ofSeconds(15);

	/**
	 * How far a member's last update may run past their interaction's before the interaction
	 * counts as over. While it lasts, both are refreshed by the same uploads.
	 */
	static final Duration INTERACTION_ENDED_GAP = Duration.ofSeconds(5);

	static final Duration DEATH_SHOWN = Duration.ofSeconds(60);
	static final Duration QUEST_COMPLETED_SHOWN = Duration.ofMinutes(2);

	/**
	 * How long a quest started while we watched is assumed to still be what they are doing.
	 * Steps within a quest are invisible, so nothing ever refreshes this.
	 */
	static final Duration QUEST_SHOWN = Duration.ofMinutes(30);

	static final Duration BANK_SHOWN = Duration.ofSeconds(30);
	static final Duration TELEPORT_SHOWN = Duration.ofSeconds(30);

	/** Skills whose experience means a fight. Magic only counts alongside one of these. */
	private static final Set<GroupSkill> COMBAT = EnumSet.of(GroupSkill.ATTACK, GroupSkill.STRENGTH,
		GroupSkill.DEFENCE, GroupSkill.RANGED, GroupSkill.HITPOINTS, GroupSkill.SLAYER);

	private static final GroupSkill[] COMBAT_ARRAY = COMBAT.toArray(new GroupSkill[0]);

	private ActivityRules()
	{
	}

	/** Everything the rules need besides the member and their history. */
	static final class Context
	{
		final int idleMinutes;
		final int offlineMinutes;
		final int pollSeconds;
		/** Whether a name belongs to someone else in the group. */
		final Predicate<String> isGroupMember;
		final Function<WorldPoint, Place> places;

		Context(int idleMinutes, int offlineMinutes, int pollSeconds, Predicate<String> isGroupMember,
			Function<WorldPoint, Place> places)
		{
			this.idleMinutes = idleMinutes;
			this.offlineMinutes = offlineMinutes;
			this.pollSeconds = pollSeconds;
			this.isGroupMember = isGroupMember;
			this.places = places;
		}

		Duration interactionWindow()
		{
			Duration scaled = Duration.ofSeconds(2L * pollSeconds + 5);
			return scaled.compareTo(MIN_INTERACTION_WINDOW) > 0 ? scaled : MIN_INTERACTION_WINDOW;
		}
	}

	/** The best guess for one member, or null when they have never reported anything useful. */
	@Nullable
	static Activity decide(GroupMember member, MemberHistory history, Context context, Instant now)
	{
		WorldPoint position = history.position != null ? history.position : member.getWorldPoint();
		Instant since = now;

		// 1. Offline. Idle and logged out look the same once nothing changes, so the offline
		// threshold is the only way to tell them apart.
		Instant updated = member.getLastUpdated();
		if (updated == null || Duration.between(updated, now).toMinutes() >= context.offlineMinutes)
		{
			return new Activity(Activity.Kind.OFFLINE, "Last seen", "Offline", "in",
				place(context, position), "", updated != null ? updated : now);
		}

		// 2. Died a moment ago.
		if (within(history.diedAt, DEATH_SHOWN, now) || member.hasStats() && member.getHitpoints() == 0
			&& member.getMaxHitpoints() > 0)
		{
			WorldPoint where = history.diedWhere != null ? history.diedWhere : position;
			return new Activity(Activity.Kind.DIED, "Died", "Died", "at", place(context, where), "",
				history.diedAt != null ? history.diedAt : now);
		}

		// 3. A live interaction, sharpened by whatever experience is coming in with it.
		GroupMember.Interaction interaction = member.getInteraction();
		Duration window = context.interactionWindow();
		if (interaction != null && interaction.getName() != null && isLive(interaction, member, history, window, now))
		{
			Activity live = interacting(interaction, history, context, position, now.minus(window), since);
			if (live != null)
			{
				return live;
			}
		}

		// A quest finished a moment ago beats the reward experience that came with it, but not
		// anything they went on to do afterwards.
		if (within(history.finishedAt, QUEST_COMPLETED_SHOWN, now) && history.finished != null
			&& !history.gainedAfter(history.finishedAt))
		{
			String name = history.finished.getName();
			return new Activity(Activity.Kind.QUEST_COMPLETED, "Completed " + name, "Completed " + name, null,
				null, "", history.finishedAt);
		}

		// 4. Aboard a boat.
		if (member.isOnBoat())
		{
			Place place = place(context, position);
			return new Activity(Activity.Kind.SAILING, "Sailing", place == null ? "At sea" : "Sailing", "near",
				place, "", since);
		}

		// 5. Experience in the last minute or so.
		Activity skilling = skilling(history, context, position, now, since);
		if (skilling != null)
		{
			return skilling;
		}

		boolean idle = history.lastActivity != null
			&& Duration.between(history.lastActivity, now).toMinutes() >= context.idleMinutes;

		// 6. A quest started while we watched, and nothing more specific going on.
		if (!idle && history.started != null && within(history.startedAt, QUEST_SHOWN, now)
			&& history.isStillStarted())
		{
			String name = history.started.getName();
			return new Activity(Activity.Kind.QUESTING, "Doing " + name, "Doing " + name, null, null, "",
				history.startedAt);
		}

		// 7. Their bank changed a moment ago.
		if (within(history.bankChangedAt, BANK_SHOWN, now))
		{
			return new Activity(Activity.Kind.BANKING, "Banking", "Banking", "at", place(context, position), "",
				history.bankChangedAt);
		}

		// 8. A jump no one could walk.
		if (within(history.jumpedAt, TELEPORT_SHOWN, now))
		{
			WorldPoint to = history.jumpedTo != null ? history.jumpedTo : position;
			return new Activity(Activity.Kind.TELEPORTED, "Teleported", "Teleported", "to", place(context, to), "",
				history.jumpedAt);
		}

		// 9. Nothing changing for a while.
		if (idle)
		{
			return new Activity(Activity.Kind.IDLE, "Idle", "Idle", "at", place(context, position), "",
				history.lastActivity);
		}

		return new Activity(Activity.Kind.ACTIVE, "", "Active", "in", place(context, position), "", since);
	}

	/**
	 * An interaction is live when a fresh copy of it arrived recently, and the member has not
	 * gone on to upload anything else since it was last refreshed.
	 */
	private static boolean isLive(GroupMember.Interaction interaction, GroupMember member, MemberHistory history,
		Duration window, Instant now)
	{
		if (!within(history.interactionSeenAt, window, now))
		{
			return false;
		}
		Instant updated = member.getLastUpdated();
		Instant refreshed = interaction.getSeen();
		return updated == null || refreshed == null
			|| Duration.between(refreshed, updated).compareTo(INTERACTION_ENDED_GAP) <= 0;
	}

	@Nullable
	private static Activity interacting(GroupMember.Interaction interaction, MemberHistory history, Context context,
		WorldPoint position, Instant recent, Instant since)
	{
		String target = interaction.getName();
		if (target.isEmpty())
		{
			return null;
		}

		if (context.isGroupMember.test(target))
		{
			return new Activity(Activity.Kind.WITH_MEMBER, "With " + target, "With " + target, null, null, "", since)
				.withTarget(target);
		}

		int health = interaction.getHealthPercent();
		if (health >= 0 || history.gainedSince(recent, COMBAT_ARRAY))
		{
			String suffix = health >= 0 ? " (" + health + "%)" : "";
			return new Activity(Activity.Kind.FIGHTING, "Fighting " + target, "Fighting " + target, null, null,
				suffix, since).withSkill(fightingSkill(history, recent)).withTarget(target);
		}

		if (target.toLowerCase(Locale.ROOT).contains("fishing spot")
			|| history.gainedSince(recent, GroupSkill.FISHING))
		{
			return new Activity(Activity.Kind.FISHING, "Fishing", "Fishing", "at", place(context, position), "",
				since).withSkill(GroupSkill.FISHING).withTarget(target);
		}

		if (history.gainedSince(recent, GroupSkill.THIEVING))
		{
			return new Activity(Activity.Kind.PICKPOCKETING, "Pickpocketing " + target, "Pickpocketing " + target,
				null, null, "", since).withSkill(GroupSkill.THIEVING).withTarget(target);
		}

		return new Activity(Activity.Kind.TALKING, "Talking to " + target, "Talking to " + target, null, null, "",
			since).withTarget(target);
	}

	/**
	 * The combat skill getting the most XP lately, Magic included, or null. Tells a mage from a
	 * ranger without having to recognise their weapon by name.
	 */
	@Nullable
	private static GroupSkill fightingSkill(MemberHistory history, Instant recent)
	{
		GroupSkill best = null;
		int most = 0;
		for (MemberHistory.XpGain gain : history.latestGains(recent))
		{
			if ((COMBAT.contains(gain.skill) || gain.skill == GroupSkill.MAGIC) && gain.amount > most)
			{
				best = gain.skill;
				most = gain.amount;
			}
		}
		return best;
	}

	/**
	 * The skill behind the most recent experience. Combat skills, Hitpoints and Slayer count
	 * together as one fight; Magic only joins them when it comes in alongside one, so alching
	 * on its own still reads as Magic.
	 */
	@Nullable
	private static Activity skilling(MemberHistory history, Context context, WorldPoint position, Instant now,
		Instant since)
	{
		Deque<MemberHistory.XpGain> latest = history.latestGains(now.minus(XP_WINDOW));
		if (latest.isEmpty())
		{
			return null;
		}

		boolean combat = false;
		MemberHistory.XpGain biggest = null;
		for (MemberHistory.XpGain gain : latest)
		{
			combat |= COMBAT.contains(gain.skill);
			if (biggest == null || gain.amount > biggest.amount)
			{
				biggest = gain;
			}
		}

		Place place = place(context, position);
		if (combat)
		{
			String suffix = history.gainedSince(now.minus(XP_WINDOW), GroupSkill.SLAYER) ? " (Slayer task)" : "";
			return new Activity(Activity.Kind.FIGHTING, "Fighting", "Fighting", "at", place, suffix, since)
				.withSkill(biggest.skill);
		}

		String skill = biggest.skill.getDisplayName();
		return new Activity(Activity.Kind.SKILLING, skill, skill, "at", place, "", since).withSkill(biggest.skill);
	}

	@Nullable
	private static Place place(Context context, @Nullable WorldPoint at)
	{
		return at == null ? null : context.places.apply(at);
	}

	private static boolean within(@Nullable Instant event, Duration window, Instant now)
	{
		return event != null && Duration.between(event, now).compareTo(window) <= 0;
	}
}

package com.groupironmencompanion.activity;

import com.groupironmencompanion.GroupIronmenCompanionConfig;
import com.groupironmencompanion.api.MemberDto;
import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupState;
import com.groupironmencompanion.place.Place;
import com.groupironmencompanion.place.Whereabouts;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.function.Function;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;

/**
 * Keeps a short history per member and publishes a best guess at what each is doing.
 * <p>
 * Fed by {@link GroupState#applyUpdate} on the polling thread with every response, including
 * ones in which nothing changed, so time-limited guesses such as "Banking" expire on the next
 * poll. Readers on the client and Swing threads only ever see an immutable map of immutable
 * {@link Activity} objects, swapped in whole, so the render path takes no lock; the lock here
 * only keeps a reset from interleaving with an update.
 */
@Singleton
public class ActivityTracker
{
	/**
	 * A gap between polls longer than this makes the next poll a fresh baseline. Everything
	 * that changed meanwhile happened at some unknown time, so none of it counts as recent.
	 */
	private static final Duration BASELINE_GAP = ActivityRules.XP_WINDOW;

	private static final int IDLE_MINUTES = 2;
	private static final int DEFAULT_OFFLINE_MINUTES = 5;
	private static final int DEFAULT_POLL_SECONDS = 3;

	private final GroupIronmenCompanionConfig config;
	private final Function<WorldPoint, Place> places;

	/** Guarded by {@code this}. */
	private final Map<String, MemberHistory> histories = new HashMap<>();

	/** Guarded by {@code this}. */
	private Instant lastPoll;

	private volatile Map<String, Activity> published = Collections.emptyMap();

	/** Replaced in tests, so time can be stepped without waiting. */
	Clock clock = Clock.systemUTC();

	@Inject
	public ActivityTracker(GroupIronmenCompanionConfig config, Whereabouts whereabouts)
	{
		this(config, whereabouts::of);
	}

	/**
	 * @param config null to use the default thresholds
	 * @param places names a position, or returns null when it cannot
	 */
	public ActivityTracker(@Nullable GroupIronmenCompanionConfig config, Function<WorldPoint, Place> places)
	{
		this.config = config;
		this.places = places;
	}

	/** The latest guess for a member, or null when there is none yet. Safe from any thread. */
	@Nullable
	public Activity get(String memberName)
	{
		return published.get(memberName);
	}

	/**
	 * Takes in one {@code get-group-data} response, after {@link GroupState} has merged it.
	 *
	 * @param response the raw response, whose non-null fields are what changed
	 * @param members every current member by name, already updated from this response
	 */
	public synchronized void update(MemberDto[] response, Map<String, GroupMember> members)
	{
		Instant now = clock.instant();
		boolean baseline = lastPoll != null && Duration.between(lastPoll, now).compareTo(BASELINE_GAP) > 0;
		lastPoll = now;

		for (MemberDto dto : response)
		{
			if (dto == null || dto.name == null || GroupMember.SHARED_NAME.equals(dto.name))
			{
				continue;
			}
			GroupMember member = members.get(dto.name);
			if (member == null)
			{
				continue;
			}
			histories.computeIfAbsent(dto.name, name -> new MemberHistory())
				.observe(dto, member.getLastUpdated(), now, baseline);
		}
		histories.keySet().retainAll(members.keySet());

		ActivityRules.Context context = new ActivityRules.Context(IDLE_MINUTES, offlineMinutes(), pollSeconds(),
			name -> isOtherMember(name, members), places);

		Map<String, Activity> next = new HashMap<>();
		for (Map.Entry<String, MemberHistory> entry : histories.entrySet())
		{
			GroupMember member = members.get(entry.getKey());
			MemberHistory history = entry.getValue();
			Activity activity = ActivityRules.decide(member, history, context, now);
			if (activity == null)
			{
				continue;
			}
			// The same guess as last time keeps its start, so "since" means since it began.
			if (activity.sameAs(history.published) && activity.getKind() != Activity.Kind.IDLE)
			{
				activity = activity.startingAt(history.published.getSince());
			}
			history.published = activity;
			next.put(entry.getKey(), activity);
		}
		published = Collections.unmodifiableMap(next);
	}

	/** Forgets everything, for a new group or a plugin restart. */
	public synchronized void reset()
	{
		histories.clear();
		lastPoll = null;
		published = Collections.emptyMap();
	}

	private static boolean isOtherMember(String name, Map<String, GroupMember> members)
	{
		for (String member : members.keySet())
		{
			if (!GroupMember.SHARED_NAME.equals(member) && GroupState.namesMatch(member, name))
			{
				return true;
			}
		}
		return false;
	}

	private int offlineMinutes()
	{
		return config == null ? DEFAULT_OFFLINE_MINUTES : config.offlineAfterMinutes();
	}

	private int pollSeconds()
	{
		return config == null ? DEFAULT_POLL_SECONDS : config.pollSeconds();
	}
}

package com.groupironmencompanion.activity;

import com.groupironmencompanion.api.MemberDto;
import com.groupironmencompanion.data.GroupSkill;
import com.groupironmencompanion.data.Quests;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.Iterator;
import javax.annotation.Nullable;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.coords.WorldPoint;

/**
 * What has changed for one member recently, which is all activity can be inferred from.
 * <p>
 * The server only says what a field is now, not how it got there, so this remembers the
 * previous value of every field that matters and turns each difference into an event with
 * the time we saw it. Times are this machine's, taken when a poll arrived: the server's
 * timestamps are only compared with each other, so a skewed clock cannot make an event look
 * older or newer than it is.
 * <p>
 * The first poll is only a baseline. It returns everything a member has ever uploaded, and
 * treating that as a change would show every member as having just gained millions of
 * experience. A long gap between polls is treated the same way.
 * <p>
 * Confined to the polling thread, under {@link ActivityTracker}'s lock.
 */
final class MemberHistory
{
	/** How long experience gains are kept, comfortably longer than any rule looks back. */
	static final Duration XP_RING = Duration.ofMinutes(5);

	/**
	 * Tiles a member may cover per second without it counting as a teleport. Running is two
	 * tiles a tick, 3.3 a second; this leaves room for the odd shortcut.
	 */
	private static final double TILES_PER_SECOND = 4;

	/** A jump must also be at least this long, so a short agility shortcut is never a teleport. */
	private static final int MIN_JUMP_TILES = 24;

	/** Caves are laid out this many tiles north of the ground they run beneath. */
	private static final int CAVE_OFFSET = 6400;

	/** How far a ladder or a cave entrance may move a member sideways. */
	private static final int LADDER_REACH = 64;

	/** One experience gain: when we saw it, in which skill, and how much. */
	static final class XpGain
	{
		final Instant time;
		final GroupSkill skill;
		final int amount;

		XpGain(Instant time, GroupSkill skill, int amount)
		{
			this.time = time;
			this.skill = skill;
			this.amount = amount;
		}
	}

	final Deque<XpGain> gains = new ArrayDeque<>();
	private int[] xp;

	@Nullable
	WorldPoint position;
	/** The member's server-side update time when the current position arrived. */
	private Instant positionStamp;
	@Nullable
	Instant jumpedAt;
	@Nullable
	WorldPoint jumpedTo;

	private int[] quests;
	@Nullable
	Quest started;
	@Nullable
	Instant startedAt;
	@Nullable
	Quest finished;
	@Nullable
	Instant finishedAt;

	private int[] bank;
	@Nullable
	Instant bankChangedAt;
	private int[] inventory;
	private int[] equipment;

	private int world = -1;
	private int hitpoints = -1;
	@Nullable
	Instant diedAt;
	@Nullable
	WorldPoint diedWhere;

	/** The interaction's own server timestamp and target, to tell a fresh one from a repeat. */
	private String interactionStamp;
	@Nullable
	Instant interactionSeenAt;

	/** When anything last changed that a member only changes by doing something. */
	@Nullable
	Instant lastActivity;

	/** False until the first poll that included this member has been taken in. */
	private boolean observed;

	/** What was last published, so an unchanged activity keeps its start time. */
	@Nullable
	Activity published;

	/**
	 * Takes in one member's part of a poll.
	 *
	 * @param dto the fields that changed since the last poll; null fields are unchanged
	 * @param lastUpdated the member's own server-side update time, after this poll
	 * @param now when the poll arrived, on this machine's clock
	 * @param baseline true to record values without treating any difference as an event, for a
	 * poll after a long gap
	 */
	void observe(MemberDto dto, @Nullable Instant lastUpdated, Instant now, boolean baseline)
	{
		// Everything in the first poll is old news, including an interaction that may have
		// ended hours ago. After that, a bank, container or interaction we have never seen
		// before is a change; skills, quests and position have nothing to compare against
		// until their second value, so their first is always a baseline.
		boolean first = !observed;
		observed = true;

		if (lastActivity == null)
		{
			// We cannot know what they did before we started watching. Their last upload is the
			// best guess, but never later than now, whatever the two clocks say.
			lastActivity = lastUpdated != null && lastUpdated.isBefore(now) ? lastUpdated : now;
		}

		observeSkills(dto.skills, now, baseline);
		observeStats(dto.stats, now, baseline);
		observePosition(dto.coordinates, lastUpdated, now, baseline);
		observeQuests(dto.quests, now, baseline);
		observeItems(dto, now, baseline || first);
		observeInteraction(dto.interacting, now, baseline || first);

		// Gains are added in time order, so the expired ones are all at the front.
		Instant cutoff = now.minus(XP_RING);
		while (!gains.isEmpty() && gains.peekFirst().time.isBefore(cutoff))
		{
			gains.removeFirst();
		}
	}

	private void observeSkills(@Nullable int[] skills, Instant now, boolean baseline)
	{
		if (skills == null)
		{
			return;
		}
		int[] previous = xp;
		xp = skills.clone();
		if (previous == null || baseline)
		{
			return;
		}

		// Older trackers send 23 skills, newer ones 24. Only compare what both have, so a
		// member whose tracker updates mid-session does not "gain" their whole Sailing total.
		int shared = Math.min(Math.min(previous.length, skills.length), GroupSkill.VALUES.length);
		for (int i = 0; i < shared; i++)
		{
			int gained = skills[i] - previous[i];
			if (gained > 0)
			{
				gains.addLast(new XpGain(now, GroupSkill.VALUES[i], gained));
				lastActivity = now;
			}
		}
	}

	private void observePosition(@Nullable int[] coordinates, @Nullable Instant lastUpdated, Instant now,
		boolean baseline)
	{
		if (coordinates == null || coordinates.length < 3)
		{
			return;
		}
		WorldPoint previous = position;
		Instant previousStamp = positionStamp;
		WorldPoint current = new WorldPoint(coordinates[0], coordinates[1], coordinates[2]);
		boolean onBoat = coordinates.length >= 4 && coordinates[3] != 0;
		position = current;
		positionStamp = lastUpdated;

		if (previous == null || baseline || previous.equals(current))
		{
			return;
		}
		lastActivity = now;

		// A boat outruns anyone on foot, so sailing is never a teleport.
		if (!onBoat && isJump(previous, current, previousStamp, lastUpdated))
		{
			jumpedAt = now;
			jumpedTo = current;
		}
	}

	/**
	 * Whether a move is too far to have been walked in the time between the two updates. The
	 * time comes from the server's own update stamps, so a member whose plugin uploads only
	 * once a minute does not look like they teleport every minute.
	 */
	static boolean isJump(WorldPoint from, WorldPoint to, @Nullable Instant fromStamp, @Nullable Instant toStamp)
	{
		int dx = Math.abs(to.getX() - from.getX());
		int dy = Math.abs(to.getY() - from.getY());

		// Climbing down into a cave moves a member 6400 tiles north and almost nowhere else.
		if (dx <= LADDER_REACH && Math.abs(dy - CAVE_OFFSET) <= LADDER_REACH)
		{
			return false;
		}

		long seconds = fromStamp == null || toStamp == null ? 0
			: Math.max(0, Duration.between(fromStamp, toStamp).getSeconds());
		double reach = MIN_JUMP_TILES + seconds * TILES_PER_SECOND;
		return Math.max(dx, dy) > reach;
	}

	private void observeQuests(@Nullable int[] states, Instant now, boolean baseline)
	{
		if (states == null)
		{
			return;
		}
		int[] previous = quests;
		quests = states.clone();
		if (previous == null || baseline)
		{
			return;
		}

		Quest[] all = Quests.all();
		int shared = Math.min(Math.min(previous.length, states.length), all.length);
		for (int i = 0; i < shared; i++)
		{
			if (previous[i] == states[i])
			{
				continue;
			}
			QuestState before = state(previous[i]);
			QuestState after = state(states[i]);
			lastActivity = now;
			if (after == QuestState.FINISHED && before != QuestState.FINISHED)
			{
				finished = all[i];
				finishedAt = now;
				if (all[i] == started)
				{
					started = null;
					startedAt = null;
				}
			}
			else if (after == QuestState.IN_PROGRESS && before == QuestState.NOT_STARTED)
			{
				started = all[i];
				startedAt = now;
			}
		}
	}

	/**
	 * The server stores each quest as the ordinal of {@link QuestState}, whose order is
	 * IN_PROGRESS, NOT_STARTED, FINISHED: zero means started, not "nothing".
	 */
	@Nullable
	private static QuestState state(int ordinal)
	{
		QuestState[] values = QuestState.values();
		return ordinal >= 0 && ordinal < values.length ? values[ordinal] : null;
	}

	/** Whether the quest started this session is still in progress by the latest data. */
	boolean isStillStarted()
	{
		if (started == null || quests == null)
		{
			return false;
		}
		Quest[] all = Quests.all();
		for (int i = 0; i < all.length && i < quests.length; i++)
		{
			if (all[i] == started)
			{
				return state(quests[i]) == QuestState.IN_PROGRESS;
			}
		}
		return false;
	}

	private void observeStats(@Nullable int[] stats, Instant now, boolean baseline)
	{
		if (stats == null || stats.length < 7)
		{
			return;
		}
		int previousHitpoints = hitpoints;
		int previousWorld = world;
		hitpoints = stats[0];
		world = stats[6];

		// Hitpoints at zero is a death however we came to see it, even on the first poll: a
		// member cannot log out while dead, so it is never an old value. Called before the
		// position is taken in, so a respawn in the same poll does not move where they died.
		if (stats[0] == 0 && stats[1] > 0 && previousHitpoints != 0)
		{
			diedAt = now;
			diedWhere = position;
		}

		if (!baseline && previousWorld >= 0 && previousWorld != world)
		{
			lastActivity = now;
		}
	}

	private void observeItems(MemberDto dto, Instant now, boolean baseline)
	{
		int[] previousBank = bank;
		if (dto.bank != null)
		{
			bank = dto.bank.clone();
			if (!baseline && !Arrays.equals(previousBank, dto.bank))
			{
				bankChangedAt = now;
				lastActivity = now;
			}
		}

		int[] previousInventory = inventory;
		if (dto.inventory != null)
		{
			inventory = dto.inventory.clone();
			if (!baseline && !Arrays.equals(previousInventory, dto.inventory))
			{
				lastActivity = now;
			}
		}

		int[] previousEquipment = equipment;
		if (dto.equipment != null)
		{
			equipment = dto.equipment.clone();
			if (!baseline && !Arrays.equals(previousEquipment, dto.equipment))
			{
				lastActivity = now;
			}
		}
	}

	/**
	 * An interaction is re-uploaded every second while it lasts, each time with a new server
	 * timestamp, and simply stops being re-uploaded when it ends. So a new stamp means it was
	 * still going on when the member last uploaded, and the same stamp again is only the
	 * server repeating itself.
	 */
	private void observeInteraction(@Nullable MemberDto.InteractingDto interacting, Instant now, boolean baseline)
	{
		if (interacting == null)
		{
			return;
		}
		String stamp = interacting.last_updated + '|' + interacting.name;
		String previous = interactionStamp;
		interactionStamp = stamp;
		if (baseline || stamp.equals(previous))
		{
			return;
		}
		interactionSeenAt = now;
		lastActivity = now;
	}

	/** The latest gains, all from the same poll, or none. */
	Deque<XpGain> latestGains(Instant notBefore)
	{
		Deque<XpGain> latest = new ArrayDeque<>();
		XpGain newest = gains.peekLast();
		if (newest == null || newest.time.isBefore(notBefore))
		{
			return latest;
		}
		for (Iterator<XpGain> it = gains.descendingIterator(); it.hasNext(); )
		{
			XpGain gain = it.next();
			if (!gain.time.equals(newest.time))
			{
				break;
			}
			latest.addFirst(gain);
		}
		return latest;
	}

	/** Whether any of the given skills gained experience at or after a time. */
	boolean gainedSince(Instant notBefore, GroupSkill... skills)
	{
		for (Iterator<XpGain> it = gains.descendingIterator(); it.hasNext(); )
		{
			XpGain gain = it.next();
			if (gain.time.isBefore(notBefore))
			{
				return false;
			}
			for (GroupSkill skill : skills)
			{
				if (gain.skill == skill)
				{
					return true;
				}
			}
		}
		return false;
	}

	/** Whether any experience at all came in after a time. */
	boolean gainedAfter(Instant after)
	{
		XpGain newest = gains.peekLast();
		return newest != null && newest.time.isAfter(after);
	}
}

package com.groupironmencompanion.api;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.google.gson.stream.MalformedJsonException;
import com.groupironmencompanion.GroupIronmenCompanionConfig;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.TimeUnit;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLiteProperties;
import net.runelite.client.config.ConfigManager;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Talks to the groupiron.men API, or to a self-hosted instance of it.
 * <p>
 * Every request goes to the base URL the user configured and carries the group token the
 * user supplied. Nothing is sent anywhere else, and no data leaves the client at all unless
 * the fallback uploader is explicitly active.
 * <p>
 * The shared RuneLite HTTP client is reused for its connection pool, but with redirects
 * disabled and a hard call timeout. Redirects matter because the base URL is user-supplied
 * and requests carry a bearer token: a redirect could otherwise hand that token to a host
 * the user never configured. The timeout matters because a hung server would otherwise pin
 * the polling thread indefinitely.
 */
@Slf4j
@Singleton
public class GroupApi
{
	public static final String PUBLIC_BASE_URL = "https://groupiron.men";

	/** What the server says, with a 401, about a character that is not in the group. */
	private static final String NOT_A_MEMBER = "not a member";

	/** Config group of the official tracker plugin, read so credentials need entering once. */
	public static final String TRACKER_CONFIG_GROUP = "GroupIronmenTracker";

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private static final String USER_AGENT =
		"GroupIronmenCompanion/1.0.0 RuneLite/" + RuneLiteProperties.getVersion();

	private static final int CALL_TIMEOUT_SECONDS = 20;

	/** Guards against a hostile or broken server returning an unbounded body. */
	private static final long MAX_RESPONSE_BYTES = 8L * 1024 * 1024;
	private static final long MAX_ERROR_BYTES = 16 * 1024;

	@Inject
	private OkHttpClient sharedClient;

	@Inject
	private Gson gson;

	@Inject
	private GroupIronmenCompanionConfig config;

	@Inject
	private ConfigManager configManager;

	private volatile OkHttpClient client;

	private OkHttpClient client()
	{
		OkHttpClient local = client;
		if (local == null)
		{
			synchronized (this)
			{
				local = client;
				if (local == null)
				{
					client = local = sharedClient.newBuilder()
						.followRedirects(false)
						.followSslRedirects(false)
						.callTimeout(CALL_TIMEOUT_SECONDS, TimeUnit.SECONDS)
						.build();
				}
			}
		}
		return local;
	}

	// ------------------------------------------------------------------
	// Credentials
	// ------------------------------------------------------------------

	public String getBaseUrl()
	{
		String override = config.baseUrlOverride().trim();
		if (override.isEmpty())
		{
			// A group that self-hosts and only configured the official tracker plugin would
			// otherwise be sent to the public server, so inherit its override too.
			override = trackerConfig("baseUrlOverride");
		}
		if (override.isEmpty())
		{
			return PUBLIC_BASE_URL;
		}
		// Strip a trailing slash so URL building stays predictable.
		return override.endsWith("/") ? override.substring(0, override.length() - 1) : override;
	}

	/**
	 * The group name to use, preferring this plugin's own setting and falling back to the
	 * official tracker plugin's configuration so an existing setup works out of the box.
	 */
	public String getGroupName()
	{
		String own = config.groupName().trim();
		return own.isEmpty() ? trackerConfig("groupName") : own;
	}

	public String getGroupToken()
	{
		String own = config.groupToken().trim();
		return own.isEmpty() ? trackerConfig("groupToken") : own;
	}

	/**
	 * True when the official tracker plugin has both a group name and a token. Without them
	 * it uploads nothing, however long it is enabled.
	 */
	public boolean trackerHasCredentials()
	{
		return !trackerConfig("groupName").isEmpty() && !trackerConfig("groupToken").isEmpty();
	}

	private String trackerConfig(String key)
	{
		try
		{
			String value = configManager.getConfiguration(TRACKER_CONFIG_GROUP, key);
			return value == null ? "" : value.trim();
		}
		catch (Exception e)
		{
			log.debug("Could not read tracker plugin config key {}", key, e);
			return "";
		}
	}

	public boolean hasCredentials()
	{
		return !getGroupName().isEmpty() && !getGroupToken().isEmpty();
	}

	// ------------------------------------------------------------------
	// URL building
	// ------------------------------------------------------------------

	/**
	 * Builds a group endpoint URL. The group name goes in as a path segment rather than
	 * being concatenated, so names containing spaces or other reserved characters are
	 * encoded correctly and cannot alter the shape of the path.
	 */
	@Nullable
	private HttpUrl.Builder endpoint(String groupName, String action)
	{
		HttpUrl base = HttpUrl.parse(getBaseUrl());
		if (base == null)
		{
			log.warn("Group Ironmen Companion: the configured server URL is not a valid URL");
			return null;
		}
		return base.newBuilder()
			.addPathSegment("api")
			.addPathSegment("group")
			.addPathSegment(groupName)
			.addPathSegment(action);
	}

	private Request.Builder authorised(HttpUrl url, String token)
	{
		return new Request.Builder()
			.url(url)
			.header("User-Agent", USER_AGENT)
			.header("Accept", "application/json")
			.header("Authorization", token);
	}

	// ------------------------------------------------------------------
	// Requests
	// ------------------------------------------------------------------

	/**
	 * Fetches everything that changed since {@code fromTime}.
	 *
	 * @return the members array, or null when the request failed
	 * @throws NotAuthorisedException when the server rejected the token
	 */
	@Nullable
	public MemberDto[] getGroupData(String fromTime) throws NotAuthorisedException
	{
		String groupName = getGroupName();
		String token = getGroupToken();
		if (groupName.isEmpty() || token.isEmpty())
		{
			return null;
		}

		HttpUrl.Builder builder = endpoint(groupName, "get-group-data");
		if (builder == null)
		{
			return null;
		}
		HttpUrl url = builder.addQueryParameter("from_time", fromTime).build();

		try (Response response = client().newCall(authorised(url, token).get().build()).execute())
		{
			if (response.code() == 401 || response.code() == 403)
			{
				throw new NotAuthorisedException();
			}
			if (!response.isSuccessful())
			{
				log.debug("get-group-data returned {}", response.code());
				return null;
			}

			ResponseBody body = response.body();
			if (body == null)
			{
				return null;
			}
			// A declared length is only present when the server does not use chunked
			// encoding, and most do, so the stream itself has to be bounded rather than
			// trusting contentLength. Reading past the cap fails the parse instead of
			// letting an unbounded body allocate without limit.
			Reader reader = new InputStreamReader(
				new BoundedInputStream(body.byteStream(), MAX_RESPONSE_BYTES), StandardCharsets.UTF_8);
			return gson.fromJson(reader, MemberDto[].class);
		}
		catch (JsonParseException e)
		{
			if (isReadFailure(e))
			{
				log.debug("get-group-data failed while reading: {}", e.getCause().toString());
				return null;
			}
			// Deliberately does not log the body: it is attacker-influenced and large.
			log.warn("Group Ironmen Companion: the server response was not valid JSON");
			return null;
		}
		catch (IOException e)
		{
			log.debug("get-group-data failed: {}", e.toString());
			return null;
		}
	}

	/**
	 * Gson reports a failed read as a parse error, so a timeout or the size cap tripping
	 * partway through the body arrives as one too. Those are network trouble, not bad JSON.
	 */
	private static boolean isReadFailure(JsonParseException e)
	{
		Throwable cause = e.getCause();
		return cause instanceof IOException && !(cause instanceof MalformedJsonException);
	}

	/**
	 * Checks that the given character is a member of the configured group.
	 *
	 * @return true for a member; false when the server says they are not, which it also
	 *         says for a rejected token; null when there is no answer, because the server
	 *         could not be reached or failed
	 */
	@Nullable
	public Boolean isPlayerInGroup(String playerName) throws NotAuthorisedException
	{
		String groupName = getGroupName();
		String token = getGroupToken();
		if (groupName.isEmpty() || token.isEmpty() || playerName == null)
		{
			return false;
		}

		HttpUrl.Builder builder = endpoint(groupName, "am-i-in-group");
		if (builder == null)
		{
			return null;
		}
		HttpUrl url = builder.addQueryParameter("member_name", playerName).build();

		try (Response response = client().newCall(authorised(url, token).get().build()).execute())
		{
			if (response.isSuccessful())
			{
				return true;
			}
			if (response.code() == 401 || response.code() == 403)
			{
				// The server answers 401 both for a character outside the group and, before
				// it gets that far, for a wrong token. Only the first says so in its body.
				// The error message is short; the cap only stops a hostile server sending gigabytes.
				ResponseBody body = response.body();
				String text = body == null ? "" : new String(
					new BoundedInputStream(body.byteStream(), MAX_ERROR_BYTES).readAllBytes(), StandardCharsets.UTF_8);
				if (text.contains(NOT_A_MEMBER))
				{
					return false;
				}
				throw new NotAuthorisedException();
			}
			log.debug("am-i-in-group returned {}", response.code());
			return null;
		}
		catch (IOException e)
		{
			log.debug("am-i-in-group failed: {}", e.toString());
			return null;
		}
	}

	/**
	 * Posts a member update. Only ever called by the fallback uploader, and only when the
	 * official tracker plugin is not running.
	 *
	 * @return true when the server accepted the update
	 * @throws NotAuthorisedException when the server rejected the token
	 */
	public boolean updateGroupMember(Object payload) throws NotAuthorisedException
	{
		String groupName = getGroupName();
		String token = getGroupToken();
		if (groupName.isEmpty() || token.isEmpty())
		{
			return false;
		}

		HttpUrl.Builder builder = endpoint(groupName, "update-group-member");
		if (builder == null)
		{
			return false;
		}

		RequestBody body = RequestBody.create(JSON, gson.toJson(payload));
		try (Response response = client().newCall(authorised(builder.build(), token).post(body).build()).execute())
		{
			if (response.code() == 401 || response.code() == 403)
			{
				throw new NotAuthorisedException();
			}
			return response.isSuccessful();
		}
		catch (IOException e)
		{
			log.debug("update-group-member failed: {}", e.toString());
			return false;
		}
	}

	/** Fails the read once more than {@code limit} bytes have been consumed. */
	private static final class BoundedInputStream extends InputStream
	{
		private final InputStream delegate;
		private final long limit;
		private long read;

		BoundedInputStream(InputStream delegate, long limit)
		{
			this.delegate = delegate;
			this.limit = limit;
		}

		@Override
		public int read() throws IOException
		{
			int value = delegate.read();
			if (value >= 0)
			{
				count(1);
			}
			return value;
		}

		@Override
		public int read(byte[] buffer, int offset, int length) throws IOException
		{
			int got = delegate.read(buffer, offset, length);
			if (got > 0)
			{
				count(got);
			}
			return got;
		}

		private void count(int bytes) throws IOException
		{
			read += bytes;
			if (read > limit)
			{
				throw new IOException("response exceeded " + limit + " bytes");
			}
		}

		@Override
		public void close() throws IOException
		{
			delegate.close();
		}
	}

	/** Raised when the server rejects the configured group token. */
	public static class NotAuthorisedException extends Exception
	{
		public NotAuthorisedException()
		{
			super("The group name or token was rejected by the server");
		}
	}
}

package com.groupironmencompanion.api;

/**
 * One element of the {@code get-group-data} response.
 * <p>
 * Field names deliberately match the server's snake_case JSON keys so Gson binds them
 * without any custom naming policy or type tokens. Any field the server omitted because it
 * has not changed since {@code from_time} arrives as null and must be treated as
 * "no new data", not as "cleared".
 */
public class MemberDto
{
	public String name;

	/** [hitpoints, maxHitpoints, prayer, maxPrayer, runEnergy, maxRunEnergy, world] */
	public int[] stats;

	/** [x, y, plane, onBoat] */
	public int[] coordinates;

	/** Experience per skill, indexed by {@code GroupSkill.ordinal()}. */
	public int[] skills;

	public int[] quests;
	public int[] diary_vars;

	/** Flat [itemId, quantity, itemId, quantity, ...] pairs. */
	public int[] inventory;
	public int[] equipment;
	public int[] bank;
	public int[] shared_bank;
	public int[] rune_pouch;
	public int[] seed_vault;
	public int[] quiver;
	public int[] potion_storage;
	public int[] deposited;

	public InteractingDto interacting;

	/** RFC 3339 timestamp of this member's most recent change. */
	public String last_updated;

	public static class InteractingDto
	{
		public String name;
		public int scale;
		public int ratio;
		public CoordinatesDto location;
		public String last_updated;
	}

	public static class CoordinatesDto
	{
		public int x;
		public int y;
		public int plane;
	}
}

package com.groupironmencompanion.bank;

import java.awt.Color;
import java.text.NumberFormat;
import java.util.Locale;

/** Shared colours and number formatting for the group bank window. */
final class BankStyle
{
	static final Color BACKGROUND = new Color(45, 39, 30, 240);
	static final Color TITLE_BACKGROUND = new Color(30, 26, 20, 250);
	static final Color BORDER = new Color(94, 82, 62);
	static final Color TEXT = new Color(255, 217, 148);
	static final Color TEXT_DIM = new Color(170, 155, 125);
	static final Color TAB_ACTIVE = new Color(78, 68, 52, 255);
	static final Color TAB_IDLE = new Color(38, 33, 26, 255);
	static final Color HOVER = new Color(255, 255, 255, 40);
	static final Color SEARCH_BACKGROUND = new Color(24, 21, 16, 255);

	/** The bank's own separator lines, under its tabs and between its sections. */
	static final Color SEPARATOR = new Color(0x2e2b23);

	static final Color QUANTITY_LOW = new Color(255, 255, 0);
	static final Color QUANTITY_MID = Color.WHITE;
	static final Color QUANTITY_HIGH = new Color(0, 255, 128);

	private static final NumberFormat NUMBERS = NumberFormat.getIntegerInstance(Locale.ENGLISH);

	private BankStyle()
	{
	}

	static String commas(long value)
	{
		return NUMBERS.format(value);
	}

	/** The abbreviated quantity the game itself draws on a stack. */
	static String shortQuantity(long quantity)
	{
		if (quantity >= 10_000_000)
		{
			return (quantity / 1_000_000) + "M";
		}
		if (quantity >= 100_000)
		{
			return (quantity / 1000) + "K";
		}
		return Long.toString(quantity);
	}

	/** The colour the game uses for a stack size, by magnitude. */
	static Color quantityColour(long quantity)
	{
		if (quantity >= 10_000_000)
		{
			return QUANTITY_HIGH;
		}
		if (quantity >= 100_000)
		{
			return QUANTITY_MID;
		}
		return QUANTITY_LOW;
	}

	/** Compact gp, e.g. 4.2m. */
	static String gp(long value)
	{
		if (value < 0)
		{
			return "-" + gp(-value);
		}
		if (value >= 1_000_000_000L)
		{
			return String.format(Locale.ENGLISH, "%.1fb", value / 1_000_000_000.0);
		}
		if (value >= 1_000_000L)
		{
			return String.format(Locale.ENGLISH, "%.1fm", value / 1_000_000.0);
		}
		if (value >= 1000L)
		{
			return String.format(Locale.ENGLISH, "%.1fk", value / 1000.0);
		}
		return Long.toString(value);
	}
}

package com.groupironmencompanion.bank;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.image.BufferedImage;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.IndexDataBase;
import net.runelite.api.SpritePixels;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * The game's own interface sprites, so the group bank can be drawn in the real bank's chrome.
 * <p>
 * Sprites are looked up the way the game looks them up when it draws an interface: the
 * client's sprite overrides first, then the game cache. Overrides are how RuneLite's Interface
 * Styles and the Resource Packs plugin reskin interfaces, so going through them keeps this
 * window matching the bank beside it. The overrides map is only ever read, never written.
 * <p>
 * Themes change while the game runs. Resource Packs applies its sprites late, after an
 * async download and again on login, and gives no event anyone else can hear, so
 * {@link #refresh()} compares the override behind every cached sprite with the one now in
 * place and starts again on any difference. The bank's separator colour is read from the
 * live bank the same way, since a colour pack recolours those lines rather than a sprite.
 * <p>
 * Every sprite keeps the offsets and maximum size it was authored with. The game positions a
 * sprite by its maximum box and draws the trimmed pixels at an offset inside it, and tiles by
 * that box too; the frame edges, for example, are 6px strips sitting 15px into a 36px box.
 * Honouring that is what makes the pieces line up exactly as they do in the bank.
 * <p>
 * Client thread only. The overlays that use it render there.
 */
@Singleton
public class GameSprites
{
	/** How long to wait before asking again for a sprite the cache could not provide. */
	private static final long MISSING_RETRY_MILLIS = 2000;

	/**
	 * How much of a tint colour's saturation a recoloured icon takes on. Below 1 so the
	 * metal of the helmet still reads as metal rather than flat paint.
	 */
	private static final float TINT_SATURATION = 0.85f;

	/** Config groups whose changes can reskin interfaces: Resource Packs and Interface Styles. */
	private static final Set<String> THEME_GROUPS = new HashSet<>(Arrays.asList(
		"resourcepacks", "interfaceStyles"));

	/**
	 * The keys in RuneLite's own config group that turn those plugins on and off. The rest of
	 * that group is written constantly (every overlay moved or resized, the window itself),
	 * and reloading every sprite for each of those writes was wasted work.
	 */
	private static final String RUNELITE_GROUP = "runelite";
	private static final Set<String> THEME_PLUGIN_KEYS = new HashSet<>(Arrays.asList(
		"resourcepacksplugin", "interfacestylesplugin"));

	@Inject
	private Client client;

	private final Map<Integer, Sprite> sprites = new HashMap<>();
	private final Map<Integer, Long> missing = new HashMap<>();

	/** Icons fitted to a size and optionally recoloured, built once each from the sprites above. */
	private final Map<Long, BufferedImage> icons = new HashMap<>();

	/** Bumped whenever cached sprites are thrown away, so composed images can be rebuilt. */
	private int version;

	/** Set from any thread when a theme setting changes; acted on by the next refresh. */
	private volatile boolean invalidated;

	/** The client tick of the last refresh, so it only runs once however many overlays ask. */
	private int refreshedCycle = -1;

	/** The bank's separator colour, as last seen on the bank itself. */
	private int lineRgb = BankStyle.SEPARATOR.getRGB() & 0xFFFFFF;
	private Color lineColour = BankStyle.SEPARATOR;

	/** A loaded sprite: its trimmed pixels plus the box they are placed in. */
	static final class Sprite
	{
		final BufferedImage image;
		final int offsetX;
		final int offsetY;
		final int maxWidth;
		final int maxHeight;

		/** The override it was drawn from, or null if it came from the cache. */
		@Nullable
		final SpritePixels override;

		private Sprite(SpritePixels pixels, @Nullable SpritePixels override)
		{
			this.override = override;
			image = pixels.toBufferedImage();
			offsetX = Math.max(0, pixels.getOffsetX());
			offsetY = Math.max(0, pixels.getOffsetY());
			// Sprites built from plain images can report no maximum size; the trimmed
			// pixels at their offset are then the whole box.
			maxWidth = Math.max(1, Math.max(pixels.getMaxWidth(), offsetX + image.getWidth()));
			maxHeight = Math.max(1, Math.max(pixels.getMaxHeight(), offsetY + image.getHeight()));
		}
	}

	/** The sprite with this id, or null when neither the overrides nor the cache have it. */
	@Nullable
	Sprite get(int id)
	{
		Sprite sprite = sprites.get(id);
		if (sprite != null)
		{
			return sprite;
		}

		Long missedAt = missing.get(id);
		long now = System.currentTimeMillis();
		if (missedAt != null && now - missedAt < MISSING_RETRY_MILLIS)
		{
			return null;
		}

		SpritePixels override = overrideFor(id);
		SpritePixels pixels = override != null ? override : fromCache(id);
		if (pixels == null || pixels.getWidth() <= 0 || pixels.getHeight() <= 0)
		{
			missing.put(id, now);
			return null;
		}

		missing.remove(id);
		sprite = new Sprite(pixels, override);
		sprites.put(id, sprite);
		return sprite;
	}

	/** The override in place for a sprite, if any. Only ever read from the client's map. */
	@Nullable
	private SpritePixels overrideFor(int id)
	{
		Map<Integer, SpritePixels> overrides = client.getSpriteOverrides();
		return overrides == null ? null : overrides.get(id);
	}

	@Nullable
	private SpritePixels fromCache(int id)
	{
		IndexDataBase index = client.getIndexSprites();
		if (index == null)
		{
			return null;
		}
		SpritePixels[] frames = client.getSprites(index, id, 0);
		return frames == null || frames.length == 0 ? null : frames[0];
	}

	/** True when every one of these sprites can be drawn. */
	boolean hasAll(int... ids)
	{
		for (int id : ids)
		{
			if (get(id) == null)
			{
				return false;
			}
		}
		return true;
	}

	/** Changes whenever the cached sprites are replaced. */
	int getVersion()
	{
		return version;
	}

	/** Throws away every cached sprite, so the next draw loads them afresh. */
	void clear()
	{
		sprites.clear();
		missing.clear();
		icons.clear();
		version++;
	}

	// ------------------------------------------------------------------
	// Following the theme
	// ------------------------------------------------------------------

	/**
	 * Brings the cache up to date with the current theme. Call at the start of every render
	 * that uses these sprites; the work is done at most once per client tick.
	 * <p>
	 * The check is an identity comparison per cached sprite, a few dozen map lookups, which
	 * is cheap enough to do continuously and is the only way to notice a pack being applied.
	 */
	void refresh()
	{
		int cycle = client.getGameCycle();
		if (cycle == refreshedCycle)
		{
			return;
		}
		refreshedCycle = cycle;

		if (invalidated || overridesChanged())
		{
			invalidated = false;
			clear();
		}

		readLineColour();
	}

	private boolean overridesChanged()
	{
		Map<Integer, SpritePixels> overrides = client.getSpriteOverrides();
		for (Map.Entry<Integer, Sprite> entry : sprites.entrySet())
		{
			SpritePixels current = overrides == null ? null : overrides.get(entry.getKey());
			if (current != entry.getValue().override)
			{
				return true;
			}
		}
		return false;
	}

	/**
	 * Takes the separator colour from the bank's own line under its tabs while the bank is
	 * open, and keeps the last one seen for while it is not. A colour pack recolours these
	 * lines directly, so this is the only place its colour can be found.
	 */
	private void readLineColour()
	{
		Widget line = client.getWidget(InterfaceID.Bankmain.TABS_LINE0);
		if (line == null || line.isHidden())
		{
			return;
		}
		int rgb = line.getTextColor() & 0xFFFFFF;

		if (rgb != lineRgb)
		{
			lineRgb = rgb;
			lineColour = new Color(rgb);
		}
	}

	/** The colour for separator lines, matching the bank's. */
	Color getLineColour()
	{
		return lineColour;
	}

	/**
	 * Notes a config change that might have reskinned the interface, so the next refresh
	 * reloads everything. Safe to call from any thread.
	 */
	public void onConfigChanged(String group, String key)
	{
		if (THEME_GROUPS.contains(group) || (RUNELITE_GROUP.equals(group) && THEME_PLUGIN_KEYS.contains(key)))
		{
			invalidated = true;
		}
	}

	// ------------------------------------------------------------------
	// Drawing
	// ------------------------------------------------------------------

	/** Draws a sprite with its box's top-left corner at the given point. */
	void draw(Graphics2D graphics, int id, int x, int y)
	{
		Sprite sprite = get(id);
		if (sprite != null)
		{
			graphics.drawImage(sprite.image, x + sprite.offsetX, y + sprite.offsetY, null);
		}
	}

	/** Draws a sprite with its box centred in the given rectangle, as icons are on buttons. */
	void drawCentred(Graphics2D graphics, int id, int x, int y, int width, int height)
	{
		Sprite sprite = get(id);
		if (sprite != null)
		{
			draw(graphics, id, x + (width - sprite.maxWidth) / 2, y + (height - sprite.maxHeight) / 2);
		}
	}

	/**
	 * Draws a sprite stretched across a wider box. Both ends are drawn as they are, the given
	 * number of pixels each, and the middle is stretched between them, so a bevelled corner
	 * keeps its shape. Only the width changes; a box no wider than the sprite draws it as is.
	 */
	void drawStretched(Graphics2D graphics, int id, int x, int y, int width, int endCap)
	{
		Sprite sprite = get(id);
		if (sprite == null)
		{
			return;
		}

		BufferedImage image = sprite.image;
		int imageWidth = image.getWidth();
		int imageHeight = image.getHeight();
		int extra = width - sprite.maxWidth;
		if (extra <= 0 || imageWidth <= endCap * 2)
		{
			draw(graphics, id, x, y);
			return;
		}

		int left = x + sprite.offsetX;
		int right = left + imageWidth + extra;
		int top = y + sprite.offsetY;
		int bottom = top + imageHeight;
		graphics.drawImage(image, left, top, left + endCap, bottom, 0, 0, endCap, imageHeight, null);
		graphics.drawImage(image, left + endCap, top, right - endCap, bottom,
			endCap, 0, imageWidth - endCap, imageHeight, null);
		graphics.drawImage(image, right - endCap, top, right, bottom,
			imageWidth - endCap, 0, imageWidth, imageHeight, null);
	}

	/**
	 * Repeats a sprite across a rectangle, clipped to it, stepping by the sprite's box the way
	 * the game tiles a sprite component.
	 */
	void tile(Graphics2D graphics, int id, int x, int y, int width, int height)
	{
		Sprite sprite = get(id);
		if (sprite == null || width <= 0 || height <= 0)
		{
			return;
		}

		Shape clip = graphics.getClip();
		graphics.clipRect(x, y, width, height);
		for (int tileY = y; tileY < y + height; tileY += sprite.maxHeight)
		{
			for (int tileX = x; tileX < x + width; tileX += sprite.maxWidth)
			{
				graphics.drawImage(sprite.image, tileX + sprite.offsetX, tileY + sprite.offsetY, null);
			}
		}
		graphics.setClip(clip);
	}

	/**
	 * Draws a box from eight pieces: four corners, and four edges tiled between them. The
	 * middle is left alone, so the caller fills it first.
	 */
	void drawNineSlice(Graphics2D graphics, int topLeft, int top, int topRight, int left, int right,
		int bottomLeft, int bottom, int bottomRight, int x, int y, int width, int height)
	{
		int topLeftWidth = widthOf(topLeft, 0);
		int topLeftHeight = heightOf(topLeft, 0);
		int topRightWidth = widthOf(topRight, 0);
		int topRightHeight = heightOf(topRight, 0);
		int bottomLeftWidth = widthOf(bottomLeft, 0);
		int bottomLeftHeight = heightOf(bottomLeft, 0);
		int bottomRightWidth = widthOf(bottomRight, 0);
		int bottomRightHeight = heightOf(bottomRight, 0);

		int topHeight = heightOf(top, 0);
		int bottomHeight = heightOf(bottom, 0);
		int leftWidth = widthOf(left, 0);
		int rightWidth = widthOf(right, 0);

		tile(graphics, top, x + topLeftWidth, y, width - topLeftWidth - topRightWidth, topHeight);
		tile(graphics, bottom, x + bottomLeftWidth, y + height - bottomHeight,
			width - bottomLeftWidth - bottomRightWidth, bottomHeight);
		tile(graphics, left, x, y + topLeftHeight, leftWidth, height - topLeftHeight - bottomLeftHeight);
		tile(graphics, right, x + width - rightWidth, y + topRightHeight,
			rightWidth, height - topRightHeight - bottomRightHeight);

		draw(graphics, topLeft, x, y);
		draw(graphics, topRight, x + width - topRightWidth, y);
		draw(graphics, bottomLeft, x, y + height - bottomLeftHeight);
		draw(graphics, bottomRight, x + width - bottomRightWidth, y + height - bottomRightHeight);
	}

	/**
	 * A sprite's pixels, recoloured to a tint if one is given and scaled down to fit a box if
	 * they are larger than it. Built once per sprite, tint and size, and rebuilt along with
	 * everything else when the theme changes; a member's new colour simply asks for another.
	 */
	@Nullable
	BufferedImage icon(int id, @Nullable Color tint, int maxWidth, int maxHeight)
	{
		Sprite sprite = get(id);
		if (sprite == null)
		{
			return null;
		}

		long key = ((long) id << 42) | ((tint == null ? 0L : 1L) << 41)
			| ((long) (tint == null ? 0 : tint.getRGB() & 0xFFFFFF) << 17)
			| ((long) (maxWidth & 0xFF) << 9) | (maxHeight & 0x1FF);
		BufferedImage icon = icons.get(key);
		if (icon == null)
		{
			icon = fit(tint == null ? sprite.image : tint(sprite.image, tint), maxWidth, maxHeight);
			icons.put(key, icon);
		}
		return icon;
	}

	/**
	 * Recolours an image to a tint while keeping its shading: every opaque pixel takes the
	 * tint's hue and at least most of its saturation, and keeps its own brightness. Grey metal
	 * takes the colour, highlights stay light and the black outline stays black.
	 */
	private static BufferedImage tint(BufferedImage source, Color tint)
	{
		float[] target = Color.RGBtoHSB(tint.getRed(), tint.getGreen(), tint.getBlue(), null);
		float saturation = target[1] * TINT_SATURATION;
		float[] hsb = new float[3];

		BufferedImage result = new BufferedImage(source.getWidth(), source.getHeight(), BufferedImage.TYPE_INT_ARGB);
		for (int y = 0; y < source.getHeight(); y++)
		{
			for (int x = 0; x < source.getWidth(); x++)
			{
				int argb = source.getRGB(x, y);
				int alpha = argb >>> 24;
				if (alpha == 0)
				{
					continue;
				}
				Color.RGBtoHSB((argb >> 16) & 0xFF, (argb >> 8) & 0xFF, argb & 0xFF, hsb);
				int rgb = Color.HSBtoRGB(target[0], Math.max(hsb[1], saturation), hsb[2]);
				result.setRGB(x, y, (alpha << 24) | (rgb & 0xFFFFFF));
			}
		}
		return result;
	}

	/** Scales an image down, keeping its proportions, if it is larger than the box. */
	private static BufferedImage fit(BufferedImage image, int maxWidth, int maxHeight)
	{
		double scale = Math.min((double) maxWidth / image.getWidth(), (double) maxHeight / image.getHeight());
		if (scale >= 1)
		{
			return image;
		}

		int width = Math.max(1, (int) Math.round(image.getWidth() * scale));
		int height = Math.max(1, (int) Math.round(image.getHeight() * scale));
		BufferedImage scaled = new BufferedImage(width, height, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = scaled.createGraphics();
		try
		{
			graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
			graphics.setRenderingHint(RenderingHints.KEY_RENDERING, RenderingHints.VALUE_RENDER_QUALITY);
			graphics.drawImage(image, 0, 0, width, height, null);
		}
		finally
		{
			graphics.dispose();
		}
		return scaled;
	}

	/** The width of a sprite's box, or the fallback when it is missing. */
	int widthOf(int id, int fallback)
	{
		Sprite sprite = get(id);
		return sprite == null ? fallback : sprite.maxWidth;
	}

	/** The height of a sprite's box, or the fallback when it is missing. */
	int heightOf(int id, int fallback)
	{
		Sprite sprite = get(id);
		return sprite == null ? fallback : sprite.maxHeight;
	}
}

package com.groupironmencompanion.bank;

import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.JagexColors;

/**
 * Text drawn the way the game draws it, for the parts of the plugin that stand in for game
 * interfaces: the group bank window and its Group tab.
 * <p>
 * The game's interface text is a 1-bit bitmap font with a 1px black drop shadow. RuneLite
 * ships the same fonts as {@link FontManager}'s RuneScape fonts, but overlays are drawn with
 * antialiasing on, which gives every glyph a grey smoothed edge that the game's own text never
 * has. Turning text antialiasing off for these overlays is what makes them read as part of the
 * game. {@code OverlayRenderer} restores the rendering hints after each overlay, so this never
 * leaks into anyone else's drawing.
 */
final class GameText
{
	/** The game's small font, used for stack sizes and footers. */
	static final Font SMALL = FontManager.getRunescapeSmallFont();

	/** The game's regular font, used for buttons, tabs and body text. */
	static final Font REGULAR = FontManager.getRunescapeFont();

	/** The game's bold font, used for interface titles. */
	static final Font BOLD = FontManager.getRunescapeBoldFont();

	/**
	 * The small font and progressively smaller sizes of it, largest first, for labels that
	 * must fit a fixed space such as a bank tab tile. The RuneScape fonts are drawn for one
	 * size, so the smaller ones are only used when a label would not fit otherwise.
	 */
	static final Font[] LABEL_SIZES = {
		SMALL, SMALL.deriveFont(14f), SMALL.deriveFont(13f), SMALL.deriveFont(12f), SMALL.deriveFont(11f),
	};

	/** The orange the game uses for interface titles, buttons and labels ({@code 0xff981f}). */
	static final Color ORANGE = JagexColors.DARK_ORANGE_INTERFACE_TEXT;

	/** What interface text turns to while the mouse is over it. */
	static final Color HOVER = Color.WHITE;

	private static final Color SHADOW = Color.BLACK;

	private GameText()
	{
	}

	/**
	 * Switches off text antialiasing, so the bitmap fonts render pixel for pixel like the
	 * game's. Call once at the start of an overlay's render.
	 */
	static void prepare(Graphics2D graphics)
	{
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		graphics.setRenderingHint(RenderingHints.KEY_FRACTIONALMETRICS, RenderingHints.VALUE_FRACTIONALMETRICS_OFF);
	}

	/** Draws text with the game's 1px black shadow below and to the right. */
	static void drawShadowed(Graphics2D graphics, String text, int x, int y, Color colour)
	{
		graphics.setColor(SHADOW);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(colour);
		graphics.drawString(text, x, y);
	}

	/** The baseline that centres a line of text vertically in a box of the given height. */
	static int centredBaseline(FontMetrics metrics, int top, int height)
	{
		return top + (height - metrics.getAscent() - metrics.getDescent()) / 2 + metrics.getAscent();
	}
}

package com.groupironmencompanion.bank;

import com.groupironmencompanion.ClientInputState;
import com.groupironmencompanion.GroupIronmenCompanionConfig;
import java.awt.Cursor;
import java.awt.Rectangle;
import java.awt.event.MouseEvent;
import java.awt.event.MouseWheelEvent;
import javax.inject.Inject;
import javax.inject.Singleton;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.game.chatbox.ChatboxTextInput;
import net.runelite.client.input.MouseAdapter;
import net.runelite.client.input.MouseWheelListener;
import net.runelite.client.ui.ClientUI;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Mouse and keyboard handling for the group bank window.
 * <p>
 * Input is only ever consumed while the window is open and the pointer is inside it, or on
 * the small Group tab. Every action it can take is client-side: opening, closing and
 * resizing the plugin's own overlay, switching tab, scrolling, and typing into the plugin's
 * own search box. No input is translated into anything the game sends to the server.
 */
@Singleton
public class GroupBankInput extends MouseAdapter implements MouseWheelListener
{
	private static final int SCROLL_ROWS = 3;

	/**
	 * How far in from the window's edge a press starts a resize: the width of the frame's
	 * border, so the border itself is the handle and nothing inside it is covered.
	 */
	private static final int RESIZE_MARGIN = 6;

	private static final int EDGE_LEFT = 1;
	private static final int EDGE_RIGHT = 2;
	private static final int EDGE_TOP = 4;
	private static final int EDGE_BOTTOM = 8;

	/** The edges being dragged, or 0 when not resizing. */
	private int resizeEdges;

	/** The pointer, window and stored location when the resize started. */
	private java.awt.Point resizeStartPoint;
	private Rectangle resizeStartWindow;
	private java.awt.Point resizeStartLocation;

	/** Whether the cursor currently shows a resize arrow that this handler put there. */
	private boolean resizeCursorShown;

	@Inject
	private GroupBankViewer viewer;

	@Inject
	private GroupBankOverlay overlay;

	@Inject
	private GroupBankTabOverlay tabOverlay;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientUI clientUI;

	@Inject
	private GroupIronmenCompanionConfig config;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ChatboxPanelManager chatboxPanelManager;

	@Inject
	private ClientInputState inputState;

	/** Set while the scrollbar is being dragged, so movement keeps scrolling after the press. */
	private boolean draggingScrollbar;

	/**
	 * The mouse buttons whose press this window swallowed, one bit per button. A release or
	 * click is only swallowed when its press was: one that began on the game, such as the end
	 * of a middle-button camera drag, must reach the game wherever it lands, or the game never
	 * hears the button come up and keeps turning the camera.
	 */
	private int swallowedButtons;

	/** The search prompt this window opened, so closing it never closes anyone else's. */
	private ChatboxTextInput searchInput;

	// ------------------------------------------------------------------
	// Mouse
	// ------------------------------------------------------------------

	@Override
	public MouseEvent mousePressed(MouseEvent event)
	{
		if (!config.bankViewer() || !inputState.isLoggedIn())
		{
			return event;
		}

		// Alt is RuneLite's overlay drag modifier; leave those clicks alone so the window
		// stays repositionable like any other overlay. A click while the game's right-click
		// menu is open is picking an option from it, which is drawn over the window.
		if (event.isAltDown() || inputState.isMenuOpen())
		{
			return event;
		}

		java.awt.Point point = event.getPoint();

		Rectangle tab = tabOverlay.getHit();
		if (tab != null && tab.contains(point))
		{
			if (!viewer.isOpen())
			{
				openBesideBank();
			}
			else
			{
				closeAll();
			}
			swallow(event);
			return event;
		}

		if (!viewer.isOpen())
		{
			return event;
		}

		// One snapshot for the whole decision, so every test below sees the same frame.
		GroupBankOverlay.HitBoxes hits = overlay.getHits();

		if (!hits.window.contains(point))
		{
			// A click elsewhere dismisses the search prompt but still reaches the game.
			clientThread.invoke(this::closeSearch);
			return event;
		}

		// Only the left button resizes, so a middle-button camera drag that happens to start
		// on the border still turns the camera.
		int edges = SwingUtilities.isLeftMouseButton(event) ? edgesAt(hits.window, point) : 0;
		if (edges != 0)
		{
			startResize(edges, point, hits.window);
			swallow(event);
			return event;
		}

		if (hits.scrollbar.contains(point))
		{
			draggingScrollbar = true;
			int row = overlay.scrollRowForY(point.y);
			clientThread.invoke(() -> viewer.setScrollRow(row));
			swallow(event);
			return event;
		}

		if (hits.scrollUp.contains(point) || hits.scrollDown.contains(point))
		{
			int rows = hits.scrollUp.contains(point) ? -1 : 1;
			clientThread.invoke(() -> scrollBy(rows));
			event.consume();
			return event;
		}

		if (hits.close.contains(point))
		{
			clientThread.invoke(() ->
			{
				closeSearch();
				viewer.setOpen(false);
			});
			swallow(event);
			return event;
		}

		for (GroupBankOverlay.TabHit hit : hits.tabs)
		{
			if (hit.bounds.contains(point))
			{
				clientThread.invoke(() ->
				{
					viewer.setActiveTab(hit.tab);
					closeSearch();
				});
				swallow(event);
				return event;
			}
		}

		boolean onSearchBox = hits.search.contains(point);
		clientThread.invoke(() ->
		{
			if (onSearchBox)
			{
				openSearch();
			}
			else
			{
				closeSearch();
			}
		});

		// Swallow anything else inside the window so clicks do not fall through to the game.
		swallow(event);
		return event;
	}

	@Override
	public MouseEvent mouseClicked(MouseEvent event)
	{
		if (isSwallowed(event))
		{
			event.consume();
		}
		return event;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent event)
	{
		draggingScrollbar = false;

		if (resizeEdges != 0 && SwingUtilities.isLeftMouseButton(event))
		{
			finishResize(event.getPoint());
		}

		// Only eat a release if we ate its press. A camera drag that starts on the game and
		// ends over the window has to reach the game, or the camera keeps turning.
		if (isSwallowed(event))
		{
			swallowedButtons &= ~buttonBit(event);
			event.consume();
		}
		return event;
	}

	@Override
	public MouseEvent mouseDragged(MouseEvent event)
	{
		if (resizeEdges != 0)
		{
			resizeTo(event.getPoint());
			event.consume();
			return event;
		}

		if (!draggingScrollbar)
		{
			return event;
		}
		if (!config.bankViewer() || !viewer.isOpen())
		{
			draggingScrollbar = false;
			return event;
		}

		// Track the pointer even once it leaves the bar, which is how scrollbars behave
		// everywhere else; the row is clamped, so dragging past either end just pins it.
		int row = overlay.scrollRowForY(event.getY());
		clientThread.invoke(() -> viewer.setScrollRow(row));
		event.consume();
		return event;
	}

	/**
	 * Whether a canvas point is on the group bank window or its Group tab, where the game's own
	 * menu options for whatever lies behind them must not show.
	 */
	public boolean covers(java.awt.Point point)
	{
		if (!config.bankViewer() || !inputState.isLoggedIn())
		{
			return false;
		}
		Rectangle tab = tabOverlay.getHit();
		if (tab != null && tab.contains(point))
		{
			return true;
		}
		return viewer.isOpen() && overlay.getHits().window.contains(point);
	}

	/** Swallows a press, remembering its button so the matching release is swallowed too. */
	private void swallow(MouseEvent event)
	{
		swallowedButtons |= buttonBit(event);
		event.consume();
	}

	private boolean isSwallowed(MouseEvent event)
	{
		return (swallowedButtons & buttonBit(event)) != 0;
	}

	private static int buttonBit(MouseEvent event)
	{
		return 1 << Math.max(0, Math.min(event.getButton(), 30));
	}

	@Override
	public MouseWheelEvent mouseWheelMoved(MouseWheelEvent event)
	{
		if (!config.bankViewer() || !viewer.isOpen() || !inputState.isLoggedIn())
		{
			return event;
		}
		// Anywhere in the window, not only over the grid: a turn over the title, the tabs or
		// the search box otherwise fell through to the game and zoomed the camera.
		if (!overlay.getHits().window.contains(event.getPoint()))
		{
			return event;
		}

		int step = event.getWheelRotation() > 0 ? SCROLL_ROWS : -SCROLL_ROWS;
		clientThread.invoke(() ->
		{
			int next = viewer.getScrollRow() + step;
			viewer.setScrollRow(Math.max(0, Math.min(overlay.maxScrollRow(), next)));
		});

		event.consume();
		return event;
	}

	/** Scrolls by whole rows, as the scrollbar's arrows do in the bank. Client thread only. */
	private void scrollBy(int rows)
	{
		viewer.setScrollRow(Math.max(0, Math.min(overlay.maxScrollRow(), viewer.getScrollRow() + rows)));
	}

	// ------------------------------------------------------------------
	// Resizing
	// ------------------------------------------------------------------

	/**
	 * Shows a resize arrow while the pointer is over the window's border, as RuneLite does
	 * for its own resizable overlays. Only a cursor this handler set is ever put back, so a
	 * custom cursor from another plugin is left alone the rest of the time.
	 */
	@Override
	public MouseEvent mouseMoved(MouseEvent event)
	{
		if (resizeEdges == 0)
		{
			boolean enabled = config.bankViewer() && viewer.isOpen() && !event.isAltDown();
			showResizeCursor(enabled ? edgesAt(overlay.getHits().window, event.getPoint()) : 0);
		}
		return event;
	}

	/**
	 * Which of the window's edges a point is on, as flags, or 0 for none. Holding Alt is left
	 * to RuneLite, which moves the window instead.
	 */
	private static int edgesAt(Rectangle window, java.awt.Point point)
	{
		if (!window.contains(point))
		{
			return 0;
		}

		int edges = 0;
		if (point.x < window.x + RESIZE_MARGIN)
		{
			edges |= EDGE_LEFT;
		}
		else if (point.x >= window.x + window.width - RESIZE_MARGIN)
		{
			edges |= EDGE_RIGHT;
		}
		if (point.y < window.y + RESIZE_MARGIN)
		{
			edges |= EDGE_TOP;
		}
		else if (point.y >= window.y + window.height - RESIZE_MARGIN)
		{
			edges |= EDGE_BOTTOM;
		}
		return edges;
	}

	private void startResize(int edges, java.awt.Point point, Rectangle window)
	{
		resizeEdges = edges;
		resizeStartPoint = point;
		resizeStartWindow = new Rectangle(window);
		java.awt.Point location = overlay.getPreferredLocation();
		resizeStartLocation = location != null ? new java.awt.Point(location) : window.getLocation();
		showResizeCursor(edges);
	}

	/**
	 * Resizes to follow the pointer to the pixel, within the window's minimum and the canvas.
	 * Dragging the left or top edge moves the window by however much the size changed, so the
	 * opposite edge stays exactly where it was even when the size stops at a limit.
	 */
	private void resizeTo(java.awt.Point point)
	{
		int dx = point.x - resizeStartPoint.x;
		int dy = point.y - resizeStartPoint.y;
		Rectangle start = resizeStartWindow;

		int width = start.width
			+ ((resizeEdges & EDGE_RIGHT) != 0 ? dx : 0)
			- ((resizeEdges & EDGE_LEFT) != 0 ? dx : 0);
		int height = start.height
			+ ((resizeEdges & EDGE_BOTTOM) != 0 ? dy : 0)
			- ((resizeEdges & EDGE_TOP) != 0 ? dy : 0);
		java.awt.Dimension size = overlay.clampSize(width, height);

		overlay.setPreferredSize(size);
		if ((resizeEdges & (EDGE_LEFT | EDGE_TOP)) != 0)
		{
			int moveX = (resizeEdges & EDGE_LEFT) != 0 ? start.width - size.width : 0;
			int moveY = (resizeEdges & EDGE_TOP) != 0 ? start.height - size.height : 0;
			overlay.setPreferredLocation(new java.awt.Point(
				resizeStartLocation.x + moveX, resizeStartLocation.y + moveY));
		}
	}

	/** Ends a resize and stores the size, the way RuneLite stores an overlay it resized. */
	private void finishResize(java.awt.Point point)
	{
		resizeTo(point);
		resizeEdges = 0;
		overlayManager.saveOverlay(overlay);
		showResizeCursor(edgesAt(overlay.getHits().window, point));
	}

	private void showResizeCursor(int edges)
	{
		if (edges != 0)
		{
			clientUI.setCursor(Cursor.getPredefinedCursor(cursorFor(edges)));
			resizeCursorShown = true;
		}
		else if (resizeCursorShown)
		{
			clientUI.setCursor(clientUI.getDefaultCursor());
			resizeCursorShown = false;
		}
	}

	private static int cursorFor(int edges)
	{
		switch (edges)
		{
			case EDGE_LEFT | EDGE_TOP:
				return Cursor.NW_RESIZE_CURSOR;
			case EDGE_RIGHT | EDGE_TOP:
				return Cursor.NE_RESIZE_CURSOR;
			case EDGE_LEFT | EDGE_BOTTOM:
				return Cursor.SW_RESIZE_CURSOR;
			case EDGE_RIGHT | EDGE_BOTTOM:
				return Cursor.SE_RESIZE_CURSOR;
			case EDGE_LEFT:
				return Cursor.W_RESIZE_CURSOR;
			case EDGE_RIGHT:
				return Cursor.E_RESIZE_CURSOR;
			case EDGE_TOP:
				return Cursor.N_RESIZE_CURSOR;
			default:
				return Cursor.S_RESIZE_CURSOR;
		}
	}

	// ------------------------------------------------------------------
	// Searching
	// ------------------------------------------------------------------

	/**
	 * Opens the game's own chatbox text input for the search box.
	 * <p>
	 * Capturing keystrokes directly does not work here. RuneLite's key remapping consumes
	 * W, A, S and D for camera movement before any other listener sees them, and KeyManager
	 * dispatches in registration order with no way to get in front of it. Anyone using WASD
	 * camera could not type those letters into the search.
	 * <p>
	 * Going through the chatbox solves it at the source: key remapping already stands down
	 * while the chatbox is taking input, so every letter arrives, and camera keys keep
	 * working normally the rest of the time because nothing is being intercepted at all.
	 */
	private void openSearch()
	{
		viewer.setSearchFocused(true);
		searchInput = chatboxPanelManager.openTextInput("Search group bank")
			.value(viewer.getFilter())
			.onChanged(value -> viewer.setFilter(value.trim()))
			.onClose(() -> viewer.setSearchFocused(false))
			.build();
	}

	/**
	 * Closes the search prompt if it is the thing currently open. The chatbox may have been
	 * taken over since, by a Withdraw-X amount, the bank's own search or another plugin's
	 * prompt, and closing that would throw away whatever the player was typing.
	 */
	private void closeSearch()
	{
		viewer.setSearchFocused(false);
		if (searchInput != null && chatboxPanelManager.getCurrentInput() == searchInput)
		{
			chatboxPanelManager.close();
		}
		searchInput = null;
	}

	// ------------------------------------------------------------------
	// Helpers
	// ------------------------------------------------------------------

	/**
	 * Closes the window and any search prompt with it. Safe to call from any thread, so the
	 * hotkey and the game events that dismiss the window can share one path.
	 */
	public void closeAll()
	{
		clientThread.invoke(() ->
		{
			closeSearch();
			viewer.setOpen(false);
		});
	}

	/**
	 * Opens the window. Called from the hotkey and the Group tab on the AWT thread, so it
	 * hops to the client thread. A window with no stored position gets placed beside the
	 * bank the first time it's drawn (see {@link GroupBankOverlay}).
	 * <p>
	 * A remembered position always wins. RuneLite persists it when you alt-drag the overlay
	 * and restores it on startup, so re-docking on every open would throw that away.
	 */
	public void openBesideBank()
	{
		clientThread.invoke(() -> viewer.setOpen(true));
	}
}

