import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * A small list of online group members, drawn inside the world map while it is open.
 * <p>
 * Left-clicking a name jumps the map to that member. Right-clicking asks the Shortest Path
 * plugin to route to them. Both are the plugin's own drawing and its own click handling: no
 * menu entry is created, no game widget is touched, and jumping the map view is a client-side
 * call that sends nothing to the server.
 */
@Slf4j
@Singleton
public class GroupMapOverlay extends Overlay
{
	private static final Color BACKGROUND = new Color(22, 19, 15, 225);
	private static final Color BORDER = new Color(94, 82, 62);
	private static final Color TEXT_DIM = new Color(170, 155, 125);
	private static final Color HOVER = new Color(255, 255, 255, 38);
	private static final Color ROUTING = new Color(0x55, 0xC5, 0x5A);

	/**
	 * The hint line is secondary, so it uses the small font whatever the interface font is.
	 * This replaces a 9pt system font that was hard to read and looked nothing like the
	 * rest of the client.
	 */
	private static final Font HINT_FONT = FontManager.getRunescapeSmallFont();

	private static final BasicStroke BORDER_STROKE = new BasicStroke(1f);

	private static final int WIDTH = 150;
	private static final int PADDING = 6;
	private static final int MARGIN = 8;

	/** Extra space added to the font's own line height, for the rows and the title. */
	private static final int ROW_SPACING = 2;
	private static final int TITLE_SPACING = 4;

	@Inject
	private Client client;

	@Inject
	private GroupState groupState;

	@Inject
	private GroupIronmenCompanionConfig config;

	@Inject
	private RouteTracker routeTracker;

	@Inject
	private GroupMapMarkers markers;

	@Inject
	private WorldMapPlusBridge worldMapPlus;

	@Inject
	private RuneLiteConfig runeLiteConfig;

	@Inject
	private PanelBackground panelBackground;

	/** Rows of the last drawn frame, published for the AWT-side input handler. */
	private volatile List<Row> rows = Collections.emptyList();

	/**
	 * The overworld map, remembered while it is the one on screen.
	 * <p>
	 * There is no way to ask the client for a particular map, only for the one currently
	 * loaded, so this is captured whenever the overworld happens to be showing. That is the
	 * state the map opens in, so in practice it is captured almost immediately.
	 */
	private volatile WorldMapData surfaceMap;

	@Inject
	public GroupMapOverlay()
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.mapPanel())
		{
			rows = Collections.emptyList();
			return null;
		}

		Rectangle map = mapBounds();
		if (map == null)
		{
			rows = Collections.emptyList();
			return null;
		}

		rememberSurfaceMap();

		List<GroupMember> members = new ArrayList<>();
		for (GroupMember member : groupState.getMembers())
		{
			if (groupState.isLocalPlayer(member) || member.getWorldPoint() == null)
			{
				continue;
			}
			if (!member.isOnline(config.offlineAfterMinutes()))
			{
				continue;
			}
			members.add(member);
		}

		if (members.isEmpty())
		{
			rows = Collections.emptyList();
			return null;
		}

		// The list is a RuneLite panel rather than a game interface, so it uses RuneLite's
		// interface font, the one the user picked for overlay panels, and sizes its rows to it.
		Font font = runeLiteConfig.interfaceFont().getFont();
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();
		FontMetrics hintMetrics = graphics.getFontMetrics(HINT_FONT);
		int rowHeight = metrics.getHeight() + ROW_SPACING;
		int titleHeight = metrics.getHeight() + TITLE_SPACING;
		int hintHeight = hintMetrics.getHeight();

		boolean routing = config.mapPanelRouting();
		int height = titleHeight + members.size() * rowHeight + PADDING
			+ (routing ? hintHeight : 0);
		int x = map.x + MARGIN;
		int y = map.y + MARGIN;

		graphics.setColor(panelBackground.get(BACKGROUND));
		graphics.fillRect(x, y, WIDTH, height);
		graphics.setColor(BORDER);
		graphics.setStroke(BORDER_STROKE);
		graphics.drawRect(x, y, WIDTH - 1, height - 1);

		drawShadowed(graphics, "Group", x + PADDING,
			y + (titleHeight - metrics.getHeight()) / 2 + metrics.getAscent(), TEXT_DIM);

		Point mouse = client.getMouseCanvasPosition();
		List<Row> drawn = new ArrayList<>(members.size());

		int rowY = y + titleHeight;

		for (GroupMember member : members)
		{
			Rectangle bounds = new Rectangle(x + 1, rowY, WIDTH - 2, rowHeight);
			boolean hovered = mouse != null && bounds.contains(mouse.getX(), mouse.getY());

			if (hovered)
			{
				graphics.setColor(HOVER);
				graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
			}

			boolean isTarget = routing && routeTracker.isRoutingTo(member);
			if (isTarget)
			{
				graphics.setColor(ROUTING);
				graphics.fillRect(bounds.x, bounds.y + 3, 3, rowHeight - 6);
			}

			drawShadowed(graphics, abbreviate(member.getName(), metrics, WIDTH - PADDING * 2 - 10),
				x + PADDING + 4, rowY + (rowHeight - metrics.getHeight()) / 2 + metrics.getAscent(),
				member.getColour());

			drawn.add(new Row(member.getName(), bounds));
			rowY += rowHeight;
		}

		if (routing)
		{
			graphics.setFont(HINT_FONT);
			drawShadowed(graphics, "click: jump  ·  right: route", x + PADDING,
				rowY + hintMetrics.getAscent(), TEXT_DIM);
		}

		rows = Collections.unmodifiableList(drawn);

		// Ask World Map Plus which of these it can show, so that a click can decide without
		// waiting. Rate-limited and deduplicated inside the bridge, so this is cheap.
		List<WorldPoint> positions = new ArrayList<>(members.size());
		for (GroupMember member : members)
		{
			WorldPoint position = member.getWorldPoint();
			if (position != null)
			{
				positions.add(position);
			}
		}
		worldMapPlus.requestCoverage(positions);

		return null;
	}

	/**
	 * Notes the overworld map while it is on screen, so it can be returned to later.
	 * Lumbridge is unambiguously on the overworld, so a map containing it is that map.
	 */
	private void rememberSurfaceMap()
	{
		WorldMap worldMap = client.getWorldMap();
		WorldMapData data = worldMap == null ? null : worldMap.getWorldMapData();
		if (data != null && data.surfaceContainsPosition(3222, 3218))
		{
			surfaceMap = data;
		}
	}

	/**
	 * Centres the world map on a member. Client thread only.
	 * <p>
	 * The map only moves to somewhere the map currently on screen actually covers, so this
	 * works out what is reachable from the present view before asking:
	 * <ol>
	 * <li>their true position, when the displayed map covers it, which is the case on the
	 * overworld and inside the dungeon they are actually in;</li>
	 * <li>otherwise the surface entrance leading to them, which is where their pin is when
	 * looking at the overworld;</li>
	 * <li>and if neither is on the displayed map, which happens while looking at some other
	 * dungeon, back to the overworld first and then to the entrance.</li>
	 * </ol>
	 * Without that last step, clicking a member from inside an unrelated dungeon map simply
	 * did nothing, because every candidate position lay outside the map being drawn.
	 */
	void jumpTo(GroupMember member)
	{
		WorldPoint truePosition = member == null ? null : member.getWorldPoint();
		if (truePosition == null)
		{
			return;
		}

		// World Map Plus, when it is installed, shows the member where they really are,
		// underground or not.
		worldMapPlus.focus(truePosition, member.getName());

		if (worldMapPlus.isExactlyCovered(truePosition))
		{
			// It has imagery of the tile they are standing on, so it is about to show them
			// there and the game's map underneath is better left where the user had it.
			// Moving it as well would drag the view to a surface entrance they did not ask
			// for, which for a detached area is somewhere else entirely: click a member in
			// Guardians of the Rift and the map beneath would jump to the Wizards' Tower.
			//
			// This is known in advance rather than awaited, because the answer arrives a tick
			// or more after the question and a click has to act now. Positions are asked
			// about while the map is open, so by the time anybody clicks the answer is in.
			return;
		}

		WorldMap worldMap = client.getWorldMap();
		if (worldMap == null)
		{
			return;
		}

		WorldMapData data = worldMap.getWorldMapData();
		if (data == null || data.surfaceContainsPosition(truePosition.getX(), truePosition.getY()))
		{
			worldMap.setWorldMapPositionTarget(truePosition);
			return;
		}

		// Underground members have an entrance on the surface; members already on the surface
		// are their own target.
		WorldPoint entrance = markers.getDrawnEntrance(member.getName(), truePosition);
		WorldPoint surfaceTarget = entrance != null ? entrance : truePosition;

		if (data.surfaceContainsPosition(surfaceTarget.getX(), surfaceTarget.getY()))
		{
			worldMap.setWorldMapPositionTarget(surfaceTarget);
			return;
		}

		WorldMapData surface = surfaceMap;
		if (surface == null)
		{
			// The overworld has not been seen this session, so there is nothing to return to.
			return;
		}

		try
		{
			worldMap.initializeWorldMap(surface);
			worldMap.setWorldMapPositionTarget(surfaceTarget);
		}
		catch (RuntimeException e)
		{
			log.debug("Could not switch the world map back to the overworld", e);
		}
	}

	/** The member whose row contains this canvas point, or null. */
	@Nullable
	String memberAt(java.awt.Point point)
	{
		for (Row row : rows)
		{
			if (row.bounds.contains(point))
			{
				return row.member;
			}
		}
		return null;
	}

	/** True while the world map is open and the panel is being drawn. */
	boolean isShowing()
	{
		return !rows.isEmpty();
	}

	@Nullable
	private Rectangle mapBounds()
	{
		Widget map = client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER);
		if (map == null || map.isHidden())
		{
			return null;
		}
		Rectangle bounds = map.getBounds();
		return bounds == null || bounds.width <= 0 ? null : bounds;
	}

	/** Text with the 1px shadow RuneLite's own panels give their text. */
	private static void drawShadowed(Graphics2D graphics, String text, int x, int y, Color colour)
	{
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(colour);
		graphics.drawString(text, x, y);
	}

	/**
	 * Shortens text to fit, ending it with three dots, since the RuneScape fonts have no
	 * single ellipsis character.
	 */
	private static String abbreviate(String text, FontMetrics metrics, int maxWidth)
	{
		if (metrics.stringWidth(text) <= maxWidth)
		{
			return text;
		}
		String result = text;
		while (result.length() > 1 && metrics.stringWidth(result + "...") > maxWidth)
		{
			result = result.substring(0, result.length() - 1);
		}
		return result + "...";
	}

	/** One drawn row, in canvas coordinates. */
	private static final class Row
	{
		private final String member;
		private final Rectangle bounds;

		Row(String member, Rectangle bounds)
		{
			this.member = member;
			this.bounds = bounds;
		}
	}
}

package com.groupironmencompanion.map;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * Works out which named area of the world a position is in, and which surface entrance leads
 * there, from data extracted out of the game cache.
 * <p>
 * The world map draws each detached area, dungeons included, in its own corner of the world
 * grid, and RuneLite only draws a world map point when the map currently on screen actually
 * covers it. So a member standing in a dungeon appears correctly once you pan to that
 * dungeon's map, and is simply absent from the overworld. This class supplies the missing
 * half: where on the overworld to draw a marker saying "they are below here".
 * <p>
 * The backing resource is generated by {@code tools/mapdump}, which reads the world map
 * definitions and the map's own intermap links straight out of the game cache. Nothing here
 * is hand-measured, and regenerating it after a game update is a single command.
 */
@Slf4j
public final class MapAreas
{
	private static final String RESOURCE = "/com/groupironmencompanion/map-areas.json";

	/**
	 * The standard underground band. Areas at or above this are laid out directly beneath
	 * their surface counterpart, offset by exactly this much, which is what makes the
	 * projection fallback below work when the cache offers no explicit link.
	 */
	private static final int UNDERGROUND_Y = 6400;

	/** How near a link outside every known area has to be before it is trusted, in tiles. */
	private static final int LOOSE_LINK_RADIUS = 64;

	/**
	 * How far a projected position may be from a real entrance and still snap to it.
	 * <p>
	 * Deliberately tight. A generous radius mislabels: the Barrows tunnels project to within
	 * 85 tiles of the Shade Catacombs entrance, which is a different dungeon entirely. Keeping
	 * this small means an unrecognised area falls back to the bare projection rather than
	 * confidently pointing at the wrong door. Holding the marker still as a member walks
	 * around underground is {@code GroupMapMarkers}' job, not this one's.
	 */
	private static final int ENTRANCE_SNAP_RADIUS = 64;

	/**
	 * Places in the underground band that aren't under anything, by map square.
	 * <p>
	 * The projection below assumes an area sits 6400 tiles under its surface. True for caves
	 * and the Barrows tunnels, but not for somewhere like Guardians of the Rift, which has no
	 * map of its own: projecting it lands in the sea east of Morytania. Nothing in the cache
	 * tells the two apart, so these are listed by hand. Each has a name and, if known, the
	 * surface spot you travel from. To size a new one, use tools/mapdump's regionProbe.
	 */
	private static final Map<Integer, Detached> DETACHED_AREAS = detachedAreas();

	private static Map<Integer, Detached> detachedAreas()
	{
		Map<Integer, Detached> detached = new HashMap<>();

		// The arena's transport is at (3615, 9469), three tiles from the top of square
		// (56, 147), so it runs into (56, 148) and the box is a square wider each way. Only
		// used where no real area claims the square, and real ones border it on both sides.
		// You get there from the Wizards' Tower basement; the cache links its ladder (3104, 3162)
		// to the basement (3103, 9576).
		addBox(detached, 55, 57, 147, 148,
			new Detached("Guardians of the Rift", new WorldPoint(3104, 3162, 0)));

		return detached;
	}

	private static void addBox(Map<Integer, Detached> into, int squareX0, int squareX1,
		int squareY0, int squareY1, Detached area)
	{
		for (int x = squareX0; x <= squareX1; x++)
		{
			for (int y = squareY0; y <= squareY1; y++)
			{
				into.put(x * 256 + y, area);
			}
		}
	}

	private static final class Detached
	{
		private final String name;
		private final WorldPoint surfaceEntrance;

		Detached(String name, @Nullable WorldPoint surfaceEntrance)
		{
			this.name = name;
			this.surfaceEntrance = surfaceEntrance;
		}
	}

	private static volatile MapAreas instance;

	private final Map<Integer, Area> bySquare;
	private final Link[] looseLinks;
	private final Entrance[] entrances;

	private MapAreas(Resource resource)
	{
		bySquare = new HashMap<>();
		if (resource.areas != null)
		{
			for (Area area : resource.areas)
			{
				if (area.squares == null)
				{
					continue;
				}
				for (int square : area.squares)
				{
					bySquare.put(square, area);
				}
			}
		}
		looseLinks = resource.looseLinks == null ? new Link[0] : resource.looseLinks;
		entrances = resource.entrances == null ? new Entrance[0] : resource.entrances;
	}

	public static MapAreas get(Gson gson)
	{
		MapAreas local = instance;
		if (local == null)
		{
			synchronized (MapAreas.class)
			{
				local = instance;
				if (local == null)
				{
					instance = local = load(gson);
				}
			}
		}
		return local;
	}

	private static MapAreas load(Gson gson)
	{
		try (InputStream in = MapAreas.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("Group Ironmen Tracker In-Game Companion: {} is missing from the plugin jar", RESOURCE);
				return new MapAreas(new Resource());
			}
			Resource resource = gson.fromJson(
				new InputStreamReader(in, StandardCharsets.UTF_8), Resource.class);
			return new MapAreas(resource == null ? new Resource() : resource);
		}
		catch (IOException | JsonSyntaxException e)
		{
			log.warn("Group Ironmen Tracker In-Game Companion: could not read {}", RESOURCE, e);
			return new MapAreas(new Resource());
		}
	}

	/** Squares are 64x64 tiles, packed the same way the generator packs them. */
	private static int squareOf(int x, int y)
	{
		return (x / 64) * 256 + (y / 64);
	}

	/**
	 * Describes where a position is. Returns null when the position is on the overworld map,
	 * because a member standing there is already drawn where they are.
	 */
	@Nullable
	public Located locate(WorldPoint point)
	{
		if (point == null)
		{
			return null;
		}

		int square = squareOf(point.getX(), point.getY());

		Area area = bySquare.get(square);
		if (area == null && point.getY() < UNDERGROUND_Y)
		{
			// Not in any detached area and not in the underground band: this is the overworld.
			return null;
		}

		if (area == null)
		{
			Detached detached = DETACHED_AREAS.get(square);
			if (detached != null)
			{
				// No map, nothing above it. Pin it where you travel from, if we know.
				return new Located(detached.name, detached.surfaceEntrance, null);
			}
		}

		String areaName = area == null ? null : area.name;

		// 1. The area's own exits, as the world map itself defines them.
		if (area != null && area.exits != null && area.exits.length > 0)
		{
			Link best = nearest(area.exits, point, Integer.MAX_VALUE);
			if (best != null)
			{
				return new Located(areaName, new WorldPoint(best.ex, best.ey, 0), best.name);
			}
		}

		// 2. A link the cache places outside every named area, if one is genuinely close.
		Link loose = nearest(looseLinks, point, LOOSE_LINK_RADIUS);
		if (loose != null)
		{
			return new Located(areaName, new WorldPoint(loose.ex, loose.ey, 0), loose.name);
		}

		// 3. Project straight up out of the underground band, then snap to the nearest real
		// entrance. Areas in this band sit directly below the surface they belong to, so the
		// projection lands near the right doorway, but on its own it would track the member's
		// every step. Snapping anchors the marker to the entrance nearest them instead.
		if (point.getY() >= UNDERGROUND_Y)
		{
			WorldPoint projected = new WorldPoint(point.getX(), point.getY() - UNDERGROUND_Y, 0);

			Entrance snapped = nearestEntrance(projected);
			if (snapped != null)
			{
				return new Located(areaName, new WorldPoint(snapped.x, snapped.y, 0), snapped.name);
			}

			// Nothing known nearby; the bare projection still beats no marker at all.
			return new Located(areaName, projected, null);
		}

		// Known area, no way to place it on the surface. The name alone is still worth having.
		return new Located(areaName, null, null);
	}

	/** The curated surface entrance nearest a point, within the snap radius. */
	@Nullable
	private Entrance nearestEntrance(WorldPoint point)
	{
		Entrance best = null;
		long bestDistance = Long.MAX_VALUE;
		long limit = (long) ENTRANCE_SNAP_RADIUS * ENTRANCE_SNAP_RADIUS;

		for (Entrance entrance : entrances)
		{
			long dx = entrance.x - point.getX();
			long dy = entrance.y - point.getY();
			long distance = dx * dx + dy * dy;
			if (distance < bestDistance)
			{
				bestDistance = distance;
				best = entrance;
			}
		}

		return bestDistance <= limit ? best : null;
	}

	@Nullable
	private static Link nearest(Link[] links, WorldPoint point, int maxDistance)
	{
		Link best = null;
		long bestDistance = Long.MAX_VALUE;
		long limit = (long) maxDistance * maxDistance;

		for (Link link : links)
		{
			long dx = link.x - point.getX();
			long dy = link.y - point.getY();
			long distance = dx * dx + dy * dy;
			if (distance < bestDistance)
			{
				bestDistance = distance;
				best = link;
			}
		}

		return bestDistance <= limit ? best : null;
	}

	/** Where a member is, and how to find them from the overworld. */
	public static final class Located
	{
		private final String areaName;
		private final WorldPoint entrance;
		private final String entranceName;

		Located(String areaName, WorldPoint entrance, String entranceName)
		{
			this.areaName = areaName;
			this.entrance = entrance;
			this.entranceName = entranceName;
		}

		/** The game's name for the map they are on, e.g. "Taverley Underground". */
		@Nullable
		public String getAreaName()
		{
			return areaName;
		}

		/** The surface point that leads to them, or null when nothing leads there. */
		@Nullable
		public WorldPoint getEntrance()
		{
			return entrance;
		}

		/** The entrance's own name, e.g. "Taverley Dungeon", when one is known. */
		@Nullable
		public String getEntranceName()
		{
			return entranceName == null || entranceName.isEmpty() ? null : entranceName;
		}

		/** The best label available for this location. */
		public String describe()
		{
			if (getEntranceName() != null)
			{
				return entranceName;
			}
			if (areaName != null)
			{
				return areaName;
			}
			return "underground";
		}
	}

	// ------------------------------------------------------------------
	// Resource shape, bound by Gson from concrete classes and plain arrays
	// ------------------------------------------------------------------

	private static final class Resource
	{
		private Area[] areas;
		private Link[] looseLinks;
		private Entrance[] entrances;
	}

	/** A named surface entrance, from RuneLite's curated dungeon entrance list. */
	private static final class Entrance
	{
		private int x;
		private int y;
		private String name;
	}

	private static final class Area
	{
		private String name;
		private int[] squares;
		private Link[] exits;
	}

	private static final class Link
	{
		private int x;
		private int y;
		private int ex;
		private int ey;
		private String name;
	}
}

package com.groupironmencompanion.map;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Ellipse2D;
import java.awt.geom.GeneralPath;
import java.awt.image.BufferedImage;
import java.util.Locale;
import net.runelite.api.Point;

/**
 * Draws the world map markers. Everything is generated at runtime so the plugin ships no
 * image assets and the colours follow whatever the user has configured.
 */
final class MarkerImages
{
	private static final int WIDTH = 18;
	private static final int HEIGHT = 24;

	/**
	 * The tip of the pin, the point of the image that belongs on the member's tile. Without
	 * it the world map centres the image there, which puts the tip half a pin too low.
	 */
	static final Point TIP = new Point(WIDTH / 2, HEIGHT - 1);

	private MarkerImages()
	{
	}

	/** A solid pin with the member's initial, used for a member's true position. */
	static BufferedImage pin(Color colour, String memberName)
	{
		BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

			GeneralPath body = teardrop();

			g.setColor(new Color(0, 0, 0, 140));
			g.setStroke(new BasicStroke(3f));
			g.draw(body);

			g.setColor(colour);
			g.fill(body);

			g.setColor(Color.BLACK);
			g.setStroke(new BasicStroke(1f));
			g.draw(body);

			drawInitial(g, colour, memberName);
		}
		finally
		{
			g.dispose();
		}
		return image;
	}

	/**
	 * A hollow ring with a downward chevron, used at a dungeon entrance to say "this member
	 * is somewhere below here" rather than "this member is standing here".
	 */
	static BufferedImage entrance(Color colour, String memberName)
	{
		BufferedImage image = new BufferedImage(WIDTH, HEIGHT, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		try
		{
			g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

			GeneralPath body = teardrop();

			g.setColor(new Color(0, 0, 0, 140));
			g.setStroke(new BasicStroke(3f));
			g.draw(body);

			g.setColor(new Color(20, 20, 20, 190));
			g.fill(body);

			g.setColor(colour);
			g.setStroke(new BasicStroke(2f));
			g.draw(body);

			// Downward chevron, marking that they are on a layer below this point.
			g.setStroke(new BasicStroke(2f));
			g.drawLine(WIDTH / 2 - 3, 7, WIDTH / 2, 11);
			g.drawLine(WIDTH / 2 + 3, 7, WIDTH / 2, 11);

			drawInitial(g, colour, memberName);
		}
		finally
		{
			g.dispose();
		}
		return image;
	}

	private static GeneralPath teardrop()
	{
		GeneralPath path = new GeneralPath();
		Ellipse2D head = new Ellipse2D.Float(1f, 1f, WIDTH - 2f, WIDTH - 2f);
		path.append(head, false);

		GeneralPath tail = new GeneralPath();
		tail.moveTo(WIDTH / 2f - 4f, WIDTH - 4f);
		tail.lineTo(WIDTH / 2f, HEIGHT - 1f);
		tail.lineTo(WIDTH / 2f + 4f, WIDTH - 4f);
		tail.closePath();
		path.append(tail, false);

		return path;
	}

	private static void drawInitial(Graphics2D g, Color colour, String memberName)
	{
		if (memberName == null || memberName.isEmpty())
		{
			return;
		}
		String initial = memberName.substring(0, 1).toUpperCase(Locale.ROOT);

		g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
		int textWidth = g.getFontMetrics().stringWidth(initial);
		int x = (WIDTH - textWidth) / 2;
		int y = WIDTH / 2 + 4;

		g.setColor(contrasting(colour));
		g.drawString(initial, x, y);
	}

	/** Black on light markers, white on dark ones, so the initial stays readable. */
	private static Color contrasting(Color colour)
	{
		double luminance = (0.299 * colour.getRed() + 0.587 * colour.getGreen() + 0.114 * colour.getBlue()) / 255.0;
		return luminance > 0.55 ? Color.BLACK : Color.WHITE;
	}
}

package com.groupironmencompanion.map;

import java.util.ArrayList;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;

/**
 * Talks to the World Map Plus plugin, if it's installed, over {@link PluginMessage}s.
 * <p>
 * Member markers need nothing from here; World Map Plus draws world map points on its own. This
 * is for jumping its view to a member, and asking which tiles it has a map for.
 * <pre>
 *   namespace "worldmapplus"
 *   "focus"  { point, zoom?, name?, exact?, id? }
 *            exact: if no map has imagery of the tile, leave the view alone
 *   "covers" { points: List&lt;WorldPoint&gt; (max 16), id }
 *   -&gt; "covers_reply" { id, covered[], exact[], mapNames[], mapKinds[] }, parallel to points
 * </pre>
 * Replies come a tick or more later (they're queued on that plugin's game tick, never sent from
 * inside its handler), and not at all if it isn't installed. So: wait about two seconds, then
 * assume no. They hold replies for five seconds, longer than we wait, so ignore ids we've
 * already given up on. The ask limit of eight a second is shared with every other plugin.
 * <p>
 * Client thread only.
 */
@Singleton
public class WorldMapPlusBridge
{
	private static final String NAMESPACE = "worldmapplus";
	private static final String MESSAGE_FOCUS = "focus";
	private static final String MESSAGE_COVERS = "covers";
	private static final String REPLY_COVERS = "covers_reply";

	// Close enough to see where they're standing.
	static final double MEMBER_ZOOM = 6.0;

	private static final int MAX_POINTS = 16;

	// Only changes when that plugin updates; short so a newly added map shows up.
	private static final long ANSWER_TTL_MILLIS = 60_000;

	// Well under their shared limit, and still answered long before anyone clicks.
	private static final long ASK_INTERVAL_MILLIS = 1_000;

	private static final long REPLY_TIMEOUT_MILLIS = 2_000;

	private final EventBus eventBus;

	// By tile rather than map square, since a square can straddle a map's edge.
	private final Map<WorldPoint, Coverage> known = new HashMap<>();
	private final Map<String, Pending> pending = new HashMap<>();

	private long lastAskMillis;
	private int nextId;

	@Inject
	public WorldMapPlusBridge(EventBus eventBus)
	{
		this.eventBus = eventBus;
	}

	public void focus(WorldPoint point, String name)
	{
		if (point == null)
		{
			return;
		}
		Map<String, Object> data = new HashMap<>();
		data.put("point", point);
		data.put("zoom", MEMBER_ZOOM);
		data.put("name", name == null ? "" : name);
		// Otherwise a tile with no map sends their view to black space off the nearest one.
		data.put("exact", Boolean.TRUE);
		eventBus.post(new PluginMessage(NAMESPACE, MESSAGE_FOCUS, data));
	}

	/**
	 * Whether World Map Plus has imagery of this tile, as far as we know. False if we haven't
	 * heard, so not having the plugin is just the normal "no".
	 */
	public boolean isExactlyCovered(WorldPoint point)
	{
		if (point == null)
		{
			return false;
		}
		Coverage coverage = known.get(point);
		return coverage != null && !coverage.isStale() && coverage.exact;
	}

	/**
	 * Asks about any tiles we don't have a fresh answer for. Cheap to call often: it's rate
	 * limited and does nothing when there's nothing new. Ask ahead of time, since a click
	 * can't wait for the reply.
	 */
	public void requestCoverage(Collection<WorldPoint> points)
	{
		expire();
		if (points == null || points.isEmpty())
		{
			return;
		}

		long now = System.currentTimeMillis();
		if (now - lastAskMillis < ASK_INTERVAL_MILLIS)
		{
			return;
		}

		List<WorldPoint> asking = new ArrayList<>();
		for (WorldPoint point : points)
		{
			if (point == null || asking.size() >= MAX_POINTS)
			{
				continue;
			}
			Coverage coverage = known.get(point);
			if (coverage == null || coverage.isStale())
			{
				asking.add(point);
			}
		}
		if (asking.isEmpty())
		{
			return;
		}

		lastAskMillis = now;
		// Their ids must be short and only letters, digits and _ - . :
		String id = "gim-" + (nextId++);
		pending.put(id, new Pending(asking, now));

		Map<String, Object> data = new HashMap<>();
		data.put("id", id);
		data.put("points", asking);
		eventBus.post(new PluginMessage(NAMESPACE, MESSAGE_COVERS, data));
	}

	/** Sees every plugin message, so ignores anything that isn't a reply to us. */
	public void onPluginMessage(PluginMessage message)
	{
		if (message == null || !NAMESPACE.equals(message.getNamespace())
			|| !REPLY_COVERS.equals(message.getName()))
		{
			return;
		}

		Map<String, Object> data = message.getData();
		if (data == null)
		{
			return;
		}

		// Unknown or already given up on.
		Pending asked = pending.remove(asText(data.get("id")));
		if (asked == null)
		{
			return;
		}

		// Only "exact" matters to us: we stand aside only when they have the actual tile.
		List<?> exact = asList(data.get("exact"));
		if (exact == null)
		{
			return;
		}

		// It's another plugin's data, so don't assume the list is as long as what we asked.
		long now = System.currentTimeMillis();
		for (int i = 0; i < asked.points.size(); i++)
		{
			boolean isExact = i < exact.size() && Boolean.TRUE.equals(exact.get(i));
			known.put(asked.points.get(i), new Coverage(isExact, now));
		}
	}

	/** Forgets everything, when the group changes or the plugin stops. */
	public void reset()
	{
		known.clear();
		pending.clear();
		lastAskMillis = 0;
	}

	private void expire()
	{
		long now = System.currentTimeMillis();
		known.values().removeIf(Coverage::isStale);
		pending.values().removeIf(waiting -> now - waiting.at > REPLY_TIMEOUT_MILLIS);
	}

	@Nullable
	private static String asText(Object value)
	{
		return value instanceof String ? (String) value : null;
	}

	@Nullable
	private static List<?> asList(Object value)
	{
		return value instanceof List ? (List<?>) value : null;
	}

	private static final class Coverage
	{
		private final boolean exact;
		private final long at;

		Coverage(boolean exact, long at)
		{
			this.exact = exact;
			this.at = at;
		}

		boolean isStale()
		{
			return System.currentTimeMillis() - at > ANSWER_TTL_MILLIS;
		}
	}

	private static final class Pending
	{
		private final List<WorldPoint> points;
		private final long at;

		Pending(List<WorldPoint> points, long at)
		{
			this.points = points;
			this.at = at;
		}
	}
}

package com.groupironmencompanion.overlay;

import com.groupironmencompanion.GroupIronmenCompanionConfig;
import com.groupironmencompanion.activity.Activity;
import com.groupironmencompanion.activity.ActivityTracker;
import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupState;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.ComponentConstants;

/**
 * A compact, always-on summary of the group: each member's name and world, their hitpoints,
 * prayer and run energy as bars, and a best guess at what they are doing.
 * <p>
 * Frameless rows in the game's own fonts and bar colours. Alt-drag to move it, alt-drag the
 * edge to set its width; the height follows the members shown. It only shows what your
 * group's trackers publish.
 */
@Singleton
public class GroupStatusOverlay extends Overlay
{
	/** Width until the user resizes it: wide enough for "Fishing at Catherby". */
	static final int DEFAULT_WIDTH = 140;

	/** The narrowest it can be dragged, which still fits a name and a world. */
	static final int MIN_WIDTH = 100;

	/** Space between one member and the next. */
	static final int MEMBER_GAP = 4;

	/** Space between the name's baseline and the top of the bars. */
	static final int NAME_GAP = 3;

	/** Space above the activity line. */
	static final int ACTIVITY_GAP = 1;

	/** Bar heights without numbers: hitpoints stands out, prayer and run are slim. */
	static final int HP_BAR_HEIGHT = 5;
	static final int PRAYER_BAR_HEIGHT = 3;
	static final int RUN_BAR_HEIGHT = 3;

	/** Padding inside the translucent backdrop, when it is on. */
	static final int BACKDROP_PADDING = 4;

	/** Gap between a bar and its number when numbers are drawn beside the bars. */
	static final int VALUE_GAP = 3;

	/** Hitpoints colours as the game's own health bars and the opponent information overlay use. */
	private static final Color HP_FILL = new Color(0, 146, 54);
	private static final Color HP_EMPTY = new Color(102, 15, 16);

	/** The core status bars plugin's prayer colour, and the game's run orb yellow. */
	private static final Color PRAYER_FILL = new Color(50, 200, 200);
	private static final Color RUN_FILL = new Color(199, 174, 0);

	/** The empty part of the prayer and run bars: dark enough to read, distinct from the outline. */
	private static final Color BAR_EMPTY = new Color(40, 40, 40);

	private static final Color OUTLINE = Color.BLACK;
	private static final Color SHADOW = Color.BLACK;
	private static final Color WORLD = new Color(0xB0, 0xB0, 0xB0);
	private static final Color ACTIVITY = new Color(0xC8, 0xC8, 0xC8);
	private static final Color OFFLINE = new Color(0x80, 0x80, 0x80);
	private static final Color VALUE = Color.WHITE;

	private static final String ELLIPSIS = "...";

	private final GroupState groupState;
	private final ActivityTracker activityTracker;
	private final GroupIronmenCompanionConfig config;

	/** Height of a digit in the small font, measured once, to centre numbers on a bar. */
	private int digitHeight = -1;

	@Inject
	public GroupStatusOverlay(GroupState groupState, ActivityTracker activityTracker,
		GroupIronmenCompanionConfig config)
	{
		this.groupState = groupState;
		this.activityTracker = activityTracker;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setResizable(true);
		setMinimumSize(MIN_WIDTH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.statusOverlay())
		{
			return null;
		}

		List<GroupMember> shown = new ArrayList<>();
		for (GroupMember member : groupState.getMembers())
		{
			boolean online = member.isOnline(config.offlineAfterMinutes());
			if (!online && !config.statusShowOffline())
			{
				continue;
			}
			if (groupState.isLocalPlayer(member) && !config.statusShowSelf())
			{
				continue;
			}
			shown.add(member);
		}
		if (shown.isEmpty())
		{
			return null;
		}

		Dimension preferred = getPreferredSize();
		int width = preferred == null ? DEFAULT_WIDTH : Math.max(MIN_WIDTH, preferred.width);
		boolean backdrop = config.statusBackdrop() == GroupIronmenCompanionConfig.StatusBackdrop.TRANSLUCENT;
		int padding = backdrop ? BACKDROP_PADDING : 0;
		int inner = width - 2 * padding;
		Instant now = Instant.now();

		// Measure first, so the backdrop can go down before anything is drawn on it.
		int height = layout(graphics, shown, padding, inner, now, false) + padding;
		if (backdrop)
		{
			graphics.setColor(ComponentConstants.STANDARD_BACKGROUND_COLOR);
			graphics.fillRect(0, 0, width, height);
		}
		layout(graphics, shown, padding, inner, now, true);

		return new Dimension(width, height);
	}

	/** Lays out every member from the top, drawing only when asked; returns the bottom edge. */
	private int layout(Graphics2D graphics, List<GroupMember> members, int padding, int width, Instant now,
		boolean paint)
	{
		int y = padding;
		for (int i = 0; i < members.size(); i++)
		{
			if (i > 0)
			{
				y += MEMBER_GAP;
			}
			y = member(graphics, members.get(i), padding, y, width, now, paint);
		}
		return y;
	}

	/** One member, from their name down; returns the bottom edge. */
	private int member(Graphics2D graphics, GroupMember member, int x, int y, int width, Instant now, boolean paint)
	{
		boolean online = member.isOnline(config.offlineAfterMinutes());
		Font bold = FontManager.getRunescapeBoldFont();
		Font small = FontManager.getRunescapeSmallFont();
		FontMetrics boldMetrics = graphics.getFontMetrics(bold);
		FontMetrics smallMetrics = graphics.getFontMetrics(small);

		// Name, with the world, or how long ago an offline member was seen, on the right.
		String right = null;
		if (!online)
		{
			right = member.getLastSeenText();
		}
		else if (member.hasStats())
		{
			right = "W" + member.getWorld();
		}
		int baseline = y + boldMetrics.getAscent();
		if (paint)
		{
			int rightWidth = right == null ? 0 : smallMetrics.stringWidth(right) + VALUE_GAP;
			if (right != null)
			{
				text(graphics, small, right, x + width - smallMetrics.stringWidth(right), baseline,
					online ? WORLD : OFFLINE);
			}
			String name = ellipsise(member.getName(), boldMetrics, width - rightWidth);
			text(graphics, bold, name, x, baseline, online ? member.getColour() : OFFLINE);
		}
		y = baseline;

		// Offline members are one grey line: their bars and activity would only be stale.
		if (!online)
		{
			return y + boldMetrics.getDescent();
		}

		if (config.statusShowVitals() && member.hasStats())
		{
			y += NAME_GAP;
			y = bars(graphics, member, x, y, width, paint);
		}
		else
		{
			y += boldMetrics.getDescent();
		}

		Activity activity = config.statusShowActivity() ? activityTracker.get(member.getName()) : null;
		if (activity != null)
		{
			y += ACTIVITY_GAP;
			int activityBaseline = y + smallMetrics.getAscent();
			if (paint)
			{
				String line = ellipsise(activity.describe(now, true), smallMetrics, width);
				text(graphics, small, line, x, activityBaseline, ACTIVITY);
			}
			y = activityBaseline + smallMetrics.getDescent();
		}
		return y;
	}

	/** The three vitals bars, as the user asked for them; returns the bottom edge. */
	private int bars(Graphics2D graphics, GroupMember member, int x, int y, int width, boolean paint)
	{
		Font small = FontManager.getRunescapeSmallFont();
		FontMetrics metrics = graphics.getFontMetrics(small);

		Bar[] bars = {
			new Bar(member.getHitpoints(), member.getMaxHitpoints(), HP_FILL, HP_EMPTY, HP_BAR_HEIGHT,
				member.getHitpoints() + "/" + member.getMaxHitpoints()),
			new Bar(member.getPrayer(), member.getMaxPrayer(), PRAYER_FILL, BAR_EMPTY, PRAYER_BAR_HEIGHT,
				member.getPrayer() + "/" + member.getMaxPrayer()),
			new Bar(member.getRunEnergyPercent(), 100, RUN_FILL, BAR_EMPTY, RUN_BAR_HEIGHT,
				member.getRunEnergyPercent() + "%"),
		};

		switch (config.statusValues())
		{
			case ON_BARS:
			{
				// Tall enough to carry a number, all three stacked inside one outline.
				int barHeight = digitHeight(graphics, small) + 4;
				int total = 1 + bars.length * (barHeight + 1);
				if (paint)
				{
					graphics.setColor(OUTLINE);
					graphics.fillRect(x, y, width, total);
				}
				int top = y + 1;
				for (Bar bar : bars)
				{
					if (paint)
					{
						fill(graphics, bar, x + 1, top, width - 2, barHeight);
						int textX = x + (width - metrics.stringWidth(bar.label)) / 2;
						text(graphics, small, bar.label, textX, top + (barHeight + digitHeight) / 2, VALUE);
					}
					top += barHeight + 1;
				}
				return y + total;
			}

			case BESIDE:
			{
				// Each bar on its own row, its number right-aligned in a column beside it.
				int column = metrics.stringWidth("999/999");
				int barWidth = width - column - VALUE_GAP;
				int rowHeight = digitHeight(graphics, small) + 2;
				int top = y;
				for (Bar bar : bars)
				{
					if (paint)
					{
						int outlineHeight = bar.height + 2;
						int outlineTop = top + (rowHeight - outlineHeight) / 2;
						graphics.setColor(OUTLINE);
						graphics.fillRect(x, outlineTop, barWidth, outlineHeight);
						fill(graphics, bar, x + 1, outlineTop + 1, barWidth - 2, bar.height);
						text(graphics, small, bar.label, x + width - metrics.stringWidth(bar.label),
							top + (rowHeight + digitHeight) / 2, VALUE);
					}
					top += rowHeight + 1;
				}
				return top - 1;
			}

			default:
			{
				// Bars only, stacked inside one shared 1px outline.
				int total = 1;
				for (Bar bar : bars)
				{
					total += bar.height + 1;
				}
				if (paint)
				{
					graphics.setColor(OUTLINE);
					graphics.fillRect(x, y, width, total);
					int top = y + 1;
					for (Bar bar : bars)
					{
						fill(graphics, bar, x + 1, top, width - 2, bar.height);
						top += bar.height + 1;
					}
				}
				return y + total;
			}
		}
	}

	private static void fill(Graphics2D graphics, Bar bar, int x, int y, int width, int height)
	{
		double fraction = bar.max <= 0 || bar.current < 0 ? 0 : Math.min(1, (double) bar.current / bar.max);
		int filled = (int) Math.round(width * fraction);
		graphics.setColor(bar.empty);
		graphics.fillRect(x + filled, y, width - filled, height);
		graphics.setColor(bar.fill);
		graphics.fillRect(x, y, filled, height);
	}

	/** Text with the game's one-pixel drop shadow. */
	private static void text(Graphics2D graphics, Font font, String text, int x, int y, Color colour)
	{
		graphics.setFont(font);
		graphics.setColor(SHADOW);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(colour);
		graphics.drawString(text, x, y);
	}

	/** Shortens text to fit a width, marking the cut. */
	static String ellipsise(String text, FontMetrics metrics, int width)
	{
		if (metrics.stringWidth(text) <= width)
		{
			return text;
		}
		int room = width - metrics.stringWidth(ELLIPSIS);
		int end = text.length();
		while (end > 0 && metrics.stringWidth(text.substring(0, end)) > room)
		{
			end--;
		}
		return text.substring(0, end).trim() + ELLIPSIS;
	}

	/**
	 * How tall a digit is in the small font. The font's ascent includes room for accents that
	 * numbers never use, so centring on it would sit every number too low.
	 */
	private int digitHeight(Graphics2D graphics, Font font)
	{
		if (digitHeight < 0)
		{
			digitHeight = (int) Math.ceil(font.createGlyphVector(graphics.getFontRenderContext(), "0")
				.getVisualBounds().getHeight());
		}
		return digitHeight;
	}

	private static final class Bar
	{
		final int current;
		final int max;
		final Color fill;
		final Color empty;
		final int height;
		final String label;

		Bar(int current, int max, Color fill, Color empty, int height, String label)
		{
			this.current = current;
			this.max = max;
			this.fill = fill;
			this.empty = empty;
			this.height = height;
			this.label = label;
		}
	}
}

package com.groupironmencompanion.overlay;

import java.awt.Color;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.RuneLiteConfig;

/**
 * The background colour for the plugin's RuneLite-style panels: the world map member list,
 * the skills hover panel and the group bank's item tooltip.
 * <p>
 * This is RuneLite's own overlay colour, which is also what the Resource Packs plugin
 * rewrites to suit a pack, so the panels change with everything else. Each panel still sits
 * over something busy (the world map, the game world, the bank), so a theme colour more
 * transparent than the panel's own default is made as opaque as that default: the user's
 * colour, kept legible.
 */
@Singleton
public class PanelBackground
{
	@Inject
	private RuneLiteConfig runeLiteConfig;

	/** The last answer, so a colour is only built when the theme or the caller changes. */
	private Color lastTheme;
	private Color lastDefault;
	private Color lastResult;

	/** The background to use for a panel whose own default is the given colour. */
	public Color get(Color panelDefault)
	{
		Color theme = runeLiteConfig.overlayBackgroundColor();
		if (theme == null)
		{
			return panelDefault;
		}

		if (!theme.equals(lastTheme) || !panelDefault.equals(lastDefault))
		{
			lastTheme = theme;
			lastDefault = panelDefault;
			lastResult = theme.getAlpha() >= panelDefault.getAlpha()
				? theme
				: new Color(theme.getRed(), theme.getGreen(), theme.getBlue(), panelDefault.getAlpha());
		}
		return lastResult;
	}
}

package com.groupironmencompanion.overlay;

import com.groupironmencompanion.GroupIronmenCompanionConfig;
import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupSkill;
import com.groupironmencompanion.data.GroupState;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.text.NumberFormat;
import java.util.List;
import java.util.Locale;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Experience;
import net.runelite.api.widgets.Widget;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * Adds the group's levels to the Skills tab.
 * <p>
 * Hovering a skill draws a panel listing every member's level, experience and experience to
 * the next level, each in that member's colour.
 * <p>
 * The panel is deliberately <em>not</em> a mouse-following tooltip. It is anchored beside the
 * Skills tab so it never covers the game's own experience tooltip, never runs off the edge of
 * the screen, and sits in the same place every time. The skill widgets are only read for
 * their on-screen bounds, to work out which one the mouse is over; nothing about the
 * interface is modified, hidden, resized or given a new click zone.
 */
@Singleton
public class SkillHoverOverlay extends Overlay
{
	private static final NumberFormat NUMBERS = NumberFormat.getIntegerInstance(Locale.ENGLISH);
	private static final Color DIM = new Color(0xB0, 0xB0, 0xB0);

	/**
	 * Nearly opaque so the panel stays legible over the game world behind it. Used as is when
	 * not matching the interface theme, and as the minimum opacity when it is.
	 */
	private static final Color BACKGROUND = new Color(22, 19, 15, 235);

	private static final int PANEL_WIDTH = 200;
	private static final int MIN_PANEL_WIDTH = 128;
	private static final int GAP = 4;

	/** Keeps the panel clear of the click-to-move text the client draws top-left. */
	private static final int TOP_MARGIN = 24;
	private static final int SIDE_MARGIN = 4;

	@Inject
	private Client client;

	@Inject
	private GroupState groupState;

	@Inject
	private GroupIronmenCompanionConfig config;

	@Inject
	private RuneLiteConfig runeLiteConfig;

	@Inject
	private PanelBackground panelBackground;

	@Inject
	public SkillHoverOverlay()
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.skillHover() || groupState.isEmpty())
		{
			return null;
		}

		// The union of the visible skill tiles is the real Skills grid. The interface's own
		// root component covers far more than the grid, so anchoring to it put the panel on
		// top of the very thing it is meant to sit beside.
		Rectangle grid = new Rectangle();
		GroupSkill hovered = scanSkills(grid);
		if (hovered == null || grid.isEmpty())
		{
			return null;
		}

		Placement placement = choosePlacement(grid);

		// A RuneLite panel, not a game interface, so it uses RuneLite's interface font: the
		// one the user picked for overlay panels. Being a dynamic overlay it would otherwise
		// get the font meant for text drawn over the game world.
		graphics.setFont(runeLiteConfig.interfaceFont().getFont());

		PanelComponent panel = buildPanel(hovered, placement.width);
		if (panel == null)
		{
			return null;
		}

		// The panel's height depends on how its text lays out, and the position depends on
		// the height, so measure first. Measuring means rendering, so it is done against a
		// scratch context clipped to nothing: same font and metrics, no pixels touched.
		Dimension size;
		Graphics2D scratch = (Graphics2D) graphics.create();
		try
		{
			scratch.setClip(0, 0, 0, 0);
			panel.setPreferredLocation(new Point(0, 0));
			size = panel.render(scratch);
		}
		finally
		{
			scratch.dispose();
		}

		if (size == null)
		{
			return null;
		}

		int canvasHeight = client.getCanvasHeight();
		int y = Math.max(TOP_MARGIN, Math.min(grid.y, canvasHeight - size.height - 4));
		panel.setPreferredLocation(new Point(placement.x, y));
		panel.render(graphics);

		return null;
	}

	/**
	 * Chooses which side of the Skills grid to sit on, and how wide to be.
	 * <p>
	 * The panel is sized to the gap it is going into rather than being a fixed width, because
	 * on a narrow client neither side has room for a full-width panel and the old behaviour
	 * was to give up and draw straight over the skills. Covering the game world is always
	 * preferable to covering the interface being read.
	 */
	private Placement choosePlacement(Rectangle grid)
	{
		int canvasWidth = client.getCanvasWidth();

		int leftSpace = grid.x - GAP - SIDE_MARGIN;
		int rightSpace = canvasWidth - (grid.x + grid.width) - GAP - SIDE_MARGIN;

		boolean useLeft;
		switch (config.skillHoverPosition())
		{
			case LEFT:
				useLeft = true;
				break;

			case RIGHT:
				useLeft = false;
				break;

			case SCREEN_CENTRE:
				int centred = Math.min(PANEL_WIDTH, canvasWidth - SIDE_MARGIN * 2);
				return new Placement(Math.max(SIDE_MARGIN, (canvasWidth - centred) / 2), centred);

			case AUTO:
			default:
				useLeft = leftSpace >= rightSpace;
				break;
		}

		int space = useLeft ? leftSpace : rightSpace;
		int width = Math.max(MIN_PANEL_WIDTH, Math.min(PANEL_WIDTH, space));

		int x = useLeft
			? grid.x - GAP - width
			: grid.x + grid.width + GAP;

		// Only clamp to the canvas, never back across the grid.
		x = Math.max(SIDE_MARGIN, Math.min(x, canvasWidth - width - SIDE_MARGIN));
		return new Placement(x, width);
	}

	private static final class Placement
	{
		private final int x;
		private final int width;

		Placement(int x, int width)
		{
			this.x = x;
			this.width = width;
		}
	}

	@Nullable
	private PanelComponent buildPanel(GroupSkill hovered, int width)
	{
		List<GroupMember> members = groupState.getMembers();
		if (members.isEmpty())
		{
			return null;
		}

		PanelComponent panel = new PanelComponent();
		panel.setPreferredSize(new Dimension(width, 0));
		panel.setBackgroundColor(panelBackground.get(BACKGROUND));
		panel.getChildren().add(TitleComponent.builder()
			.text(hovered.getDisplayName())
			.color(Color.WHITE)
			.build());

		boolean anyData = false;
		for (GroupMember member : members)
		{
			if (groupState.isLocalPlayer(member) && !config.skillHoverIncludeSelf())
			{
				continue;
			}
			if (!config.skillHoverOffline() && !member.isOnline(config.offlineAfterMinutes()))
			{
				continue;
			}
			if (addMember(panel, member, hovered))
			{
				anyData = true;
			}
		}

		return anyData ? panel : null;
	}

	/**
	 * Adds two lines for one member: name and level, then experience and the gap to the next
	 * level. Returns false when this member has never reported the skill.
	 */
	private boolean addMember(PanelComponent panel, GroupMember member, GroupSkill skill)
	{
		boolean isLocal = groupState.isLocalPlayer(member);

		int xp;
		int level;
		if (isLocal)
		{
			// Read your own values live so they stay correct between server polls.
			xp = client.getSkillExperience(skill.getSkill());
			level = Experience.getLevelForXp(xp);
		}
		else
		{
			xp = member.getXp(skill);
			level = member.getLevel(skill);
		}

		if (xp < 0 || level < 0)
		{
			return false;
		}

		String name = isLocal ? member.getName() + " (you)" : member.getName();
		panel.getChildren().add(LineComponent.builder()
			.left(name)
			.leftColor(member.getColour())
			.right("Lv " + level)
			.rightColor(member.getColour())
			.build());

		String toNext;
		if (level >= Experience.MAX_VIRT_LEVEL)
		{
			toNext = "maxed";
		}
		else
		{
			int remaining = Experience.getXpForLevel(level + 1) - xp;
			toNext = NUMBERS.format(remaining) + " to " + (level + 1);
		}

		panel.getChildren().add(LineComponent.builder()
			.left("  " + NUMBERS.format(xp) + " xp")
			.leftColor(DIM)
			.right(toNext)
			.rightColor(DIM)
			.build());

		return true;
	}

	/**
	 * Walks the skill tiles once, accumulating their union into {@code grid} and returning
	 * whichever one the mouse is over. Widgets are only read, never modified.
	 */
	@Nullable
	private GroupSkill scanSkills(Rectangle grid)
	{
		net.runelite.api.Point mouse = client.getMouseCanvasPosition();
		if (mouse == null)
		{
			return null;
		}

		GroupSkill hovered = null;
		for (GroupSkill skill : GroupSkill.VALUES)
		{
			Widget widget = client.getWidget(skill.getComponentId());
			if (widget == null || widget.isHidden())
			{
				continue;
			}
			Rectangle bounds = widget.getBounds();
			if (bounds == null || bounds.isEmpty())
			{
				continue;
			}

			if (grid.isEmpty())
			{
				grid.setBounds(bounds);
			}
			else
			{
				grid.add(bounds);
			}

			if (bounds.contains(mouse.getX(), mouse.getY()))
			{
				hovered = skill;
			}
		}
		return hovered;
	}
}

package com.groupironmencompanion.place;

import java.util.Objects;

/**
 * A named place and how a member stands in relation to it: at it, near it, or beneath it.
 * <p>
 * Kept apart from the words around it so an activity can choose its own preposition:
 * "Fishing at Catherby", "Idle in Catherby", but always "Mining beneath Falador" and
 * "Fishing near Port Sarim" whatever the activity would have said.
 */
public final class Place
{
	public enum Relation
	{
		AT,
		NEAR,
		BENEATH
	}

	private final String name;
	private final Relation relation;
	private final boolean upstairs;

	public Place(String name, Relation relation, boolean upstairs)
	{
		this.name = Objects.requireNonNull(name);
		this.relation = Objects.requireNonNull(relation);
		this.upstairs = upstairs;
	}

	public static Place at(String name)
	{
		return new Place(name, Relation.AT, false);
	}

	public String getName()
	{
		return name;
	}

	public Relation getRelation()
	{
		return relation;
	}

	public boolean isUpstairs()
	{
		return upstairs;
	}

	/**
	 * The place as the end of a sentence: {@code phrase("at")} gives "at Catherby", while a
	 * place that is only near or beneath somewhere says so instead of the preposition given.
	 */
	public String phrase(String preposition)
	{
		String lead;
		switch (relation)
		{
			case NEAR:
				lead = "near";
				break;
			case BENEATH:
				lead = "beneath";
				break;
			default:
				lead = preposition;
				break;
		}
		return lead + " " + name + (upstairs ? ", upstairs" : "");
	}

	/** The place on its own: "Catherby", "Near Catherby", "Beneath Falador". */
	@Override
	public String toString()
	{
		switch (relation)
		{
			case NEAR:
				return "Near " + name + (upstairs ? ", upstairs" : "");
			case BENEATH:
				return "Beneath " + name;
			default:
				// A few names read as part of a sentence ("their house"), so start it properly.
				String capitalised = name.isEmpty() ? name
					: Character.toUpperCase(name.charAt(0)) + name.substring(1);
				return capitalised + (upstairs ? ", upstairs" : "");
		}
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (!(o instanceof Place))
		{
			return false;
		}
		Place other = (Place) o;
		return upstairs == other.upstairs && relation == other.relation && name.equals(other.name);
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(name, relation, upstairs);
	}
}

package com.groupironmencompanion.place;

import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.GZIPInputStream;
import javax.annotation.Nullable;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;

/**
 * What a place is called, so a member's whereabouts can be said in words.
 * <p>
 * Two sources, built offline into one bundled file. A region's curated name is used first:
 * those name a whole 64-tile region and never name a monster. Where there is none (anywhere
 * added to the game since that list was written) the world map's own labels answer instead:
 * the nearest one within a few dozen tiles, preferring the ones the game draws largest, so a
 * region's name beats the name of a monster standing in it.
 * <p>
 * Region names come from the Location Display plugin by trinhc2 (BSD 2-Clause), the map labels
 * from the game cache; see the README. Ported from Golems Don't Die, where the same file is
 * built by {@code dev-tools/BuildPlaceNames.java}.
 * <p>
 * The file is read lazily on first use, from the plugin jar only, and is immutable afterwards,
 * so lookups are safe from any thread.
 */
@Slf4j
@Singleton
public class PlaceNames
{
	private static final String RESOURCE = "/com/groupironmencompanion/places.gz";

	/** Bumped by the generator whenever the format changes, so an older file is never misread. */
	private static final int VERSION = 2;

	// The file has about a thousand labels and 850 regions. These only stop a corrupt count
	// from asking for a huge array: that throws OutOfMemoryError, which the catch below
	// doesn't see, on whatever thread first asked for a place name.
	private static final int MAX_LABELS = 20_000;
	private static final int MAX_REGIONS = 1 << 16;

	/** How far a label may be from a tile and still name it, in tiles. */
	private static final int LABEL_REACH = 48;

	/** How much a larger label is favoured over a nearer one, in tiles per step of size. */
	private static final int SIZE_WORTH = 24;

	private volatile Data data;

	/** What to call this tile, or null when nothing is known nearby. */
	@Nullable
	public String nameFor(WorldPoint at)
	{
		return at == null ? null : nameFor(at.getX(), at.getY(), at.getPlane());
	}

	@Nullable
	public String nameFor(int x, int y, int plane)
	{
		Data d = data();
		String region = d.regions.get(regionOf(x, y));
		if (region != null)
		{
			return region;
		}

		String nearest = null;
		int best = Integer.MAX_VALUE;
		for (int i = 0; i < d.labels.length; i++)
		{
			int[] label = d.labels[i];
			int distance = span(label[0] - x, label[1] - y);
			if (distance > LABEL_REACH)
			{
				continue;
			}
			// A big label a little further off is the better answer: "Ape Atoll" over
			// "Scimitar monkeys", a region over whatever stands on its shore.
			int score = distance - label[3] * SIZE_WORTH + (label[2] == plane ? 0 : LABEL_REACH);
			if (score < best)
			{
				best = score;
				nearest = d.labelNames[i];
			}
		}
		return nearest;
	}

	/**
	 * The nearest map label however far off, for somewhere nothing names. "Near" it is still
	 * an answer a player can go looking with. A label on the same floor is preferred.
	 */
	@Nullable
	public String nearest(int x, int y, int plane)
	{
		Data d = data();
		String nearest = null;
		int best = Integer.MAX_VALUE;
		for (int i = 0; i < d.labels.length; i++)
		{
			int[] label = d.labels[i];
			int score = span(label[0] - x, label[1] - y) + (label[2] == plane ? 0 : LABEL_REACH);
			if (score < best)
			{
				best = score;
				nearest = d.labelNames[i];
			}
		}
		return nearest;
	}

	static int regionOf(int x, int y)
	{
		return (x >> 6) << 8 | (y >> 6);
	}

	/** Chebyshev distance: how many tiles apart two points are when diagonals count as one. */
	private static int span(int dx, int dy)
	{
		return Math.max(Math.abs(dx), Math.abs(dy));
	}

	private Data data()
	{
		Data local = data;
		if (local == null)
		{
			synchronized (this)
			{
				local = data;
				if (local == null)
				{
					data = local = load();
				}
			}
		}
		return local;
	}

	private static Data load()
	{
		try (InputStream in = PlaceNames.class.getResourceAsStream(RESOURCE))
		{
			if (in == null)
			{
				log.warn("Group Ironmen Tracker In-Game Companion: {} is missing from the plugin jar", RESOURCE);
				return Data.EMPTY;
			}
			try (DataInputStream stream = new DataInputStream(new GZIPInputStream(in)))
			{
				int version = stream.readInt();
				if (version != VERSION)
				{
					log.warn("Group Ironmen Tracker In-Game Companion: place names are version {}, expected {}",
						version, VERSION);
					return Data.EMPTY;
				}

				int count = stream.readInt();
				if (count < 0 || count > MAX_LABELS)
				{
					throw new IOException("bad label count " + count);
				}
				int[][] labels = new int[count][];
				String[] labelNames = new String[count];
				for (int i = 0; i < count; i++)
				{
					labelNames[i] = stream.readUTF();
					labels[i] = new int[]{stream.readUnsignedShort(), stream.readUnsignedShort(),
						stream.readByte(), stream.readUnsignedByte()};
				}

				int named = stream.readInt();
				if (named < 0 || named > MAX_REGIONS)
				{
					throw new IOException("bad region count " + named);
				}
				Map<Integer, String> regions = new HashMap<>(named * 2);
				for (int i = 0; i < named; i++)
				{
					String name = stream.readUTF();
					regions.put(stream.readUnsignedByte() << 8 | stream.readUnsignedByte(), name);
				}
				return new Data(labels, labelNames, Collections.unmodifiableMap(regions));
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("Group Ironmen Tracker In-Game Companion: could not read {}", RESOURCE, e);
			return Data.EMPTY;
		}
	}

	/** Labels as {x, y, plane, size} with their names in step, and curated names by region id. */
	private static final class Data
	{
		static final Data EMPTY = new Data(new int[0][], new String[0], Collections.emptyMap());

		final int[][] labels;
		final String[] labelNames;
		final Map<Integer, String> regions;

		Data(int[][] labels, String[] labelNames, Map<Integer, String> regions)
		{
			this.labels = labels;
			this.labelNames = labelNames;
			this.regions = regions;
		}
	}
}

package com.groupironmencompanion.place;

import com.google.gson.Gson;
import com.groupironmencompanion.map.MapAreas;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.coords.WorldPoint;

/**
 * Where a member is, in words: "Catherby", "Taverley Dungeon", "Beneath Falador".
 * <p>
 * Said the way a player would say it. The bundled {@link PlaceNames} answer almost
 * everywhere; the companion's own {@link MapAreas} names the detached areas and dungeons they
 * miss; a cave nobody named is described by the ground above it; and anywhere else is "near"
 * the closest name on the map, which a player can still go looking with.
 * <p>
 * Instances are uploaded as the coordinates of the template they were copied from, so raids
 * and boss rooms resolve like anywhere else. The few templates that sit somewhere meaningless,
 * such as the player-owned house's room palette, are named by {@link #INSTANCES} instead.
 */
@Singleton
public class Whereabouts
{
	/** Caves are laid out this many tiles north of the ground they run beneath. */
	private static final int CAVE_OFFSET = 6400;

	/**
	 * Instance templates and minigames whose map labels say the wrong thing, by region id.
	 * <p>
	 * The house's room palette sits in an empty corner of the map; raid rooms are labelled
	 * with their boss ("Verzik Vitur", "Great Olm"); the Nightmare Zone's arena is a copy of
	 * the King Black Dragon's lair. Region ids are the ones RuneLite's own Discord plugin uses
	 * for these places.
	 */
	private static final Map<Integer, String> INSTANCES;

	static
	{
		Map<Integer, String> instances = new HashMap<>();
		name(instances, "their house", 7534, 7535, 7790, 7791, 8046, 8047, 8302, 8303);
		name(instances, "Chambers of Xeric", 12889);
		name(instances, "Theatre of Blood", 12611, 12612, 12613, 12867, 12869, 13122, 13123, 13125, 13379);
		name(instances, "Tombs of Amascut", 14160, 14162, 14164, 14674, 14676, 15184, 15186, 15188, 15696,
			15698, 15700);
		name(instances, "Hallowed Sepulchre", 8797, 9051, 9052, 9053, 9054, 9309, 9563, 9565, 9821, 10074,
			10075, 10077);
		name(instances, "Motherlode Mine", 14679, 14680, 14681, 14935, 14936, 14937, 15191, 15192, 15193);
		name(instances, "Guardians of the Rift", 14484);
		name(instances, "Nightmare Zone", 9033);
		name(instances, "Fortis Colosseum", 7216);
		name(instances, "Castle Wars", 9620);
		INSTANCES = Collections.unmodifiableMap(instances);
	}

	private static void name(Map<Integer, String> instances, String name, int... regions)
	{
		for (int region : regions)
		{
			instances.put(region, name);
		}
	}

	private final PlaceNames names;
	private final Gson gson;

	@Inject
	public Whereabouts(PlaceNames names, @Nullable Gson gson)
	{
		this.names = names;
		this.gson = gson;
	}

	/** Where this tile is, or null when even the nearest map label is unknown. */
	@Nullable
	public Place of(@Nullable WorldPoint at)
	{
		if (at == null)
		{
			return null;
		}

		boolean upstairs = at.getPlane() > 0;

		String instance = INSTANCES.get(PlaceNames.regionOf(at.getX(), at.getY()));
		if (instance != null)
		{
			return Place.at(instance);
		}

		String named = names.nameFor(at);
		if (named != null)
		{
			return new Place(named, Place.Relation.AT, upstairs);
		}

		String area = mapArea(at);
		if (area != null)
		{
			return new Place(area, Place.Relation.AT, upstairs);
		}

		if (at.getY() >= CAVE_OFFSET)
		{
			int above = at.getY() - CAVE_OFFSET;
			String over = names.nameFor(at.getX(), above, 0);
			if (over == null)
			{
				over = names.nearest(at.getX(), above, 0);
			}
			if (over != null)
			{
				return new Place(over, Place.Relation.BENEATH, false);
			}
		}

		String near = names.nearest(at.getX(), at.getY(), at.getPlane());
		return near == null ? null : new Place(near, Place.Relation.NEAR, upstairs);
	}

	/**
	 * The game's own name for a dungeon or detached area, from the map data the world map
	 * markers already use, or null on the overworld or where it only knows "underground".
	 */
	@Nullable
	private String mapArea(WorldPoint at)
	{
		if (gson == null)
		{
			return null;
		}
		MapAreas.Located located = MapAreas.get(gson).locate(at);
		if (located == null)
		{
			return null;
		}
		if (located.getEntranceName() != null)
		{
			return located.getEntranceName();
		}
		return located.getAreaName();
	}
}

package com.groupironmencompanion.route;

import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupState;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.events.PluginMessage;

/**
 * Keeps a Shortest Path route pointed at a moving group member.
 * <p>
 * The target is stored as a member name rather than a fixed point, so as their position
 * updates the route is re-issued to follow them. It is retargeted only when they have
 * actually moved a meaningful distance, because re-pathing costs a search and their
 * coordinates jitter by a tile as they walk.
 * <p>
 * Arrival is judged against the member's <em>true</em> position, including plane, not the
 * surface entrance drawn on the overworld map: following someone into a dungeon should not
 * count as done the moment you reach the ladder.
 * <p>
 * Before each retarget, Shortest Path is asked whether it is still showing our route. If the
 * player cleared it, or set a route of their own, following stops there instead of putting
 * our route back over theirs.
 */
@Singleton
public class RouteTracker
{
	/** How far the target must move before the route is recalculated, in tiles. */
	private static final int RETARGET_DISTANCE = 8;

	/** How close counts as having arrived, in tiles. */
	private static final int ARRIVAL_DISTANCE = 3;

	@Inject
	private Client client;

	@Inject
	private GroupState groupState;

	@Inject
	private ShortestPathBridge bridge;

	private volatile String targetName;
	private WorldPoint lastRouted;

	/** Where to route next, held while Shortest Path is asked whether our route is still up. */
	private WorldPoint pendingRetarget;

	/** The member currently being routed to, or null when no route is active. */
	@Nullable
	public String getTargetName()
	{
		return targetName;
	}

	public boolean isRoutingTo(GroupMember member)
	{
		return member != null && GroupState.namesMatch(targetName, member.getName());
	}

	/** Starts routing to a member, or stops if they were already the target. */
	public void toggle(GroupMember member)
	{
		if (member == null)
		{
			return;
		}
		if (isRoutingTo(member))
		{
			stop();
			return;
		}

		targetName = member.getName();
		lastRouted = null;
		pendingRetarget = null;
		update();
	}

	public void stop()
	{
		if (targetName == null)
		{
			return;
		}
		targetName = null;
		lastRouted = null;
		pendingRetarget = null;
		bridge.clear();
	}

	/**
	 * Re-points the route at the target's latest position, and ends it on arrival. Safe to
	 * call every tick; it only talks to Shortest Path when something has actually changed.
	 * Must run on the client thread.
	 */
	public void update()
	{
		String name = targetName;
		if (name == null)
		{
			return;
		}

		GroupMember member = groupState.getMember(name);
		if (member == null)
		{
			// They left the group, so there is nothing left to follow.
			stop();
			return;
		}

		WorldPoint target = member.getWorldPoint();
		if (target == null)
		{
			return;
		}

		// Members upload real coordinates, so compare against ours, not instance ones.
		Player local = client.getLocalPlayer();
		WorldPoint here = local == null ? null : WorldPoint.fromLocalInstance(client, local.getLocalLocation());
		if (here != null && here.getPlane() == target.getPlane()
			&& here.distanceTo2D(target) <= ARRIVAL_DISTANCE)
		{
			stop();
			return;
		}

		if (lastRouted == null)
		{
			lastRouted = target;
			bridge.pathTo(target);
		}
		else if (lastRouted.distanceTo2D(target) > RETARGET_DISTANCE
			|| lastRouted.getPlane() != target.getPlane())
		{
			// Retargeted once Shortest Path confirms the route on screen is still ours. Its
			// answer comes back within a frame, so asking again on a later tick only happens
			// if one was lost.
			pendingRetarget = target;
			bridge.requestTarget();
		}
	}

	/**
	 * Handles Shortest Path's answer about the route it is showing. If it is still ours, the
	 * route moves to the member's latest position; if not, following stops and whatever the
	 * player has on screen is left alone. Client thread.
	 */
	public void onPluginMessage(PluginMessage message)
	{
		WorldPoint routed = lastRouted;
		WorldPoint next = pendingRetarget;
		if (routed == null || next == null)
		{
			return;
		}

		Boolean ours = bridge.isPathingTo(message, routed);
		if (ours == null)
		{
			return;
		}

		pendingRetarget = null;
		if (!ours)
		{
			targetName = null;
			lastRouted = null;
			return;
		}
		lastRouted = next;
		bridge.pathTo(next);
	}
}

package com.groupironmencompanion.route;

import java.util.Collection;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;

/**
 * Drives the Shortest Path plugin.
 * <p>
 * Hub plugins each get their own classloader, so this cannot compile against
 * {@code shortestpath.ShortestPathPlugin} or cast it, and reflection is forbidden.
 * RuneLite's answer is {@link PluginMessage}: a namespaced event carrying a plain data map.
 * Everything crossing the boundary is either a JDK type or {@link WorldPoint}, which lives in
 * runelite-api on the shared parent classloader, so both sides agree on it. No dependency is
 * added to the build.
 * <p>
 * Contract, from Shortest Path's {@code onPluginMessage}:
 * <pre>
 *   namespace "shortestpath"
 *   name      "path"   data { "start": WorldPoint|Integer|null,
 *                             "target": WorldPoint|Integer|Set,
 *                             "config": Map&lt;String,Object&gt; }
 *   name      "clear"  data {}
 *   name      "getTarget"      data { "id": Object }
 *     answered by "currentTarget" data { "id": Object, "set": Boolean,
 *                                      "target": List&lt;WorldPoint&gt; when set }
 * </pre>
 * If Shortest Path is not installed then nothing subscribes to the event and the post is a
 * harmless no-op, so this degrades gracefully by construction.
 */
@Slf4j
@Singleton
public class ShortestPathBridge
{
	private static final String NAMESPACE = "shortestpath";
	private static final String MESSAGE_PATH = "path";
	private static final String MESSAGE_CLEAR = "clear";
	private static final String MESSAGE_GET_TARGET = "getTarget";
	private static final String MESSAGE_CURRENT_TARGET = "currentTarget";

	private static final String KEY_START = "start";
	private static final String KEY_TARGET = "target";
	private static final String KEY_ID = "id";
	private static final String KEY_SET = "set";

	/** Marks this plugin's target requests, so answers to anyone else's are ignored. */
	private static final String REQUEST_ID = "group-ironmen-companion";

	private final EventBus eventBus;

	@Inject
	public ShortestPathBridge(EventBus eventBus)
	{
		this.eventBus = eventBus;
	}

	/**
	 * Paths from the player's current position to {@code target}. A null start lets Shortest
	 * Path use wherever the player happens to be.
	 */
	public void pathTo(WorldPoint target)
	{
		if (target == null)
		{
			return;
		}

		Map<String, Object> data = new HashMap<>();
		data.put(KEY_START, null);
		data.put(KEY_TARGET, target);

		log.debug("Requesting path to {}", target);
		eventBus.post(new PluginMessage(NAMESPACE, MESSAGE_PATH, data));
	}

	/** Clears any path currently drawn. */
	public void clear()
	{
		eventBus.post(new PluginMessage(NAMESPACE, MESSAGE_CLEAR));
	}

	/** Asks Shortest Path what it is pathing to. The answer arrives later as a message. */
	public void requestTarget()
	{
		Map<String, Object> data = new HashMap<>();
		data.put(KEY_ID, REQUEST_ID);
		eventBus.post(new PluginMessage(NAMESPACE, MESSAGE_GET_TARGET, data));
	}

	/**
	 * Reads Shortest Path's answer to {@link #requestTarget}.
	 *
	 * @return whether it is still pathing to {@code target}, or null when the message is not
	 *         an answer to this plugin's request
	 */
	@Nullable
	public Boolean isPathingTo(PluginMessage message, WorldPoint target)
	{
		if (!NAMESPACE.equals(message.getNamespace()) || !MESSAGE_CURRENT_TARGET.equals(message.getName()))
		{
			return null;
		}
		Map<String, Object> data = message.getData();
		if (data == null || !REQUEST_ID.equals(data.get(KEY_ID)))
		{
			return null;
		}

		Object targets = data.get(KEY_TARGET);
		return Boolean.TRUE.equals(data.get(KEY_SET))
			&& targets instanceof Collection
			&& ((Collection<?>) targets).contains(target);
	}
}

package com.groupironmencompanion.scene;

import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.extern.slf4j.Slf4j;

/**
 * Worn models for every equippable item, generated by {@code tools/geardump} and bundled.
 * <p>
 * The client only tells us an item's inventory icon, not what it looks like worn, so this is
 * pulled from the game cache at build time. Items newer than the table just aren't drawn
 * (the body shows instead). Regenerate after game updates.
 */
@Slf4j
final class GearTable
{
	// Must match GearDump.FORMAT_VERSION.
	private static final int FORMAT_VERSION = 1;

	private static final String RESOURCE = "/com/groupironmencompanion/gear.dat";

	// So a bad file fails to load instead of allocating whatever a broken count says.
	private static final int MAX_ITEMS = 100_000;
	private static final int MAX_BODY_PARTS = 16;

	// Item id to {model0, model1, model2}.
	private final Map<Integer, int[]> worn;

	// Default male body model per part: hair, jaw, torso, arms, hands, legs, feet.
	private final int[] body;

	private GearTable(Map<Integer, int[]> worn, int[] body)
	{
		this.worn = worn;
		this.body = body;
	}

	/** The bundled table, or null if it's missing or unreadable. */
	@Nullable
	static GearTable load()
	{
		try (InputStream resource = GearTable.class.getResourceAsStream(RESOURCE))
		{
			if (resource == null)
			{
				log.warn("Group Ironmen Companion: the worn-model table is missing from the jar");
				return null;
			}

			DataInputStream stream = new DataInputStream(resource);
			int version = stream.readInt();
			if (version != FORMAT_VERSION)
			{
				log.warn("Group Ironmen Companion: worn-model table is version {}, expected {}", version, FORMAT_VERSION);
				return null;
			}

			int parts = stream.readInt();
			if (parts < 0 || parts > MAX_BODY_PARTS)
			{
				log.warn("Group Ironmen Companion: worn-model table declares {} body parts", parts);
				return null;
			}
			int[] body = new int[parts];
			for (int i = 0; i < parts; i++)
			{
				body[i] = stream.readInt();
			}

			int count = stream.readInt();
			if (count < 0 || count > MAX_ITEMS)
			{
				log.warn("Group Ironmen Companion: worn-model table declares {} items", count);
				return null;
			}
			Map<Integer, int[]> worn = new HashMap<>(count * 2);
			for (int i = 0; i < count; i++)
			{
				int id = stream.readInt();
				int[] models = {stream.readInt(), stream.readInt(), stream.readInt()};
				// Vertical offset. Unused: our figures are built from whole parts at one origin.
				stream.readShort();
				worn.put(id, models);
			}

			log.debug("Loaded worn models for {} items", worn.size());
			return new GearTable(worn, body);
		}
		catch (IOException e)
		{
			log.warn("Group Ironmen Companion: could not read the worn-model table", e);
			return null;
		}
	}

	@Nullable
	int[] wornModels(int itemId)
	{
		return worn.get(itemId);
	}

	int bodyModel(int part)
	{
		return part >= 0 && part < body.length ? body[part] : -1;
	}

	int itemCount()
	{
		return worn.size();
	}
}

package com.groupironmencompanion.scene;

import javax.annotation.Nullable;
import net.runelite.api.AnimationController;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;

/**
 * One translucent figure in the scene.
 * <p>
 * Backed by a {@link RuneLiteObject}: drawn by the client, but not in the player or NPC lists,
 * not clickable, and unknown to the server.
 * <p>
 * Positions arrive about once a second, so the figure eases toward each new one instead of
 * snapping. It lags its owner a little and walks in straight lines, since we only get
 * endpoints, not the path.
 */
class Ghost
{
	private static final int UNITS_PER_TILE = 128;

	// Fraction of the remaining distance covered each frame. Picked by eye: keeps up with a
	// running player without making a new position look like a jump.
	private static final double EASE = 0.25;

	// Further than this and it's a hop or teleport, so jump instead of walking through walls.
	private static final int SNAP_DISTANCE_TILES = 12;

	private static final double ARRIVED_UNITS = 1.0;

	// Roughly head height, so the hover point sits on the figure rather than its feet.
	private static final int LABEL_HEIGHT = 200;

	// Names come from the group's server, so they get clipped before they size a label.
	private static final int MAX_TEXT = 32;

	private final Client client;
	private final RuneLiteObject object;

	// Where it's drawn and where it's heading, in local units.
	private double x;
	private double y;
	private int plane;
	private int targetX;
	private int targetY;
	private boolean dirty = true;

	// Remembered so an unchanged animation isn't restarted every tick, which looks like twitching.
	private int poseId = -1;
	private int actionId = -1;
	private int ticksUntilAction;
	private Model model;

	private String title = "";
	private String detail;

	Ghost(Client client, LocalPoint start, int plane)
	{
		this.client = client;
		this.x = start.getX();
		this.y = start.getY();
		this.targetX = start.getX();
		this.targetY = start.getY();
		this.plane = plane;

		this.object = client.createRuneLiteObject();
		apply();
	}

	String getTitle()
	{
		return title;
	}

	/** A second line for the hover label, or null. */
	@Nullable
	String getDetail()
	{
		return detail;
	}

	void setLabel(String title, @Nullable String detail)
	{
		this.title = clip(title);
		this.detail = detail == null || detail.isEmpty() ? null : clip(detail);
	}

	void setModel(@Nullable Model model)
	{
		if (model == this.model)
		{
			return;
		}
		this.model = model;
		object.setModel(model);
		object.setActive(model != null);
	}

	boolean isMoving()
	{
		return Math.abs(targetX - x) >= ARRIVED_UNITS || Math.abs(targetY - y) >= ARRIVED_UNITS;
	}

	void moveTo(LocalPoint point, int plane)
	{
		targetX = point.getX();
		targetY = point.getY();

		boolean changedPlane = plane != this.plane;
		this.plane = plane;

		double tiles = Math.hypot(targetX - x, targetY - y) / UNITS_PER_TILE;
		if (changedPlane || tiles > SNAP_DISTANCE_TILES)
		{
			x = targetX;
			y = targetY;
			dirty = true;
		}
	}

	/** Eases toward the target. Runs every frame, so a figure that's arrived does nothing. */
	void advance()
	{
		if (!isMoving())
		{
			if (dirty)
			{
				x = targetX;
				y = targetY;
				apply();
			}
			return;
		}

		double dx = targetX - x;
		double dy = targetY - y;
		x += dx * EASE;
		y += dy * EASE;
		face(dx, dy);
		apply();
	}

	void faceTowards(LocalPoint point)
	{
		face(point.getX() - x, point.getY() - y);
	}

	/**
	 * Sets the pose (standing, walking, running), which loops, and an action (a swing, a chop)
	 * that {@link #onGameTick} plays every few ticks. Pass -1 for no action.
	 */
	void setAnimation(int poseId, int actionId)
	{
		if (poseId != this.poseId)
		{
			this.poseId = poseId;
			object.setPoseAnimationController(looping(poseId));
		}
		if (actionId != this.actionId)
		{
			this.actionId = actionId;
			object.setAnimationController(null);
			// Start straight away rather than waiting out the last action's interval.
			ticksUntilAction = 0;
		}
	}

	/** Plays the action every {@link GhostAnimations#ACTION_INTERVAL_TICKS}, once each time. */
	void onGameTick()
	{
		if (actionId < 0 || --ticksUntilAction > 0)
		{
			return;
		}
		ticksUntilAction = GhostAnimations.ACTION_INTERVAL_TICKS;

		// Not looped: it clears itself when done so the pose shows between swings.
		AnimationController controller = new AnimationController(client, actionId);
		controller.setOnFinished(finished -> object.setAnimationController(null));
		object.setAnimationController(controller);
	}

	/** Where the figure is on screen, or null if it isn't. */
	@Nullable
	Point canvasLocation()
	{
		LocalPoint point = localPoint();
		return point == null ? null : Perspective.localToCanvas(client, point, plane, LABEL_HEIGHT);
	}

	void destroy()
	{
		object.setActive(false);
	}

	private AnimationController looping(int animationId)
	{
		AnimationController controller = new AnimationController(client, animationId);
		controller.loop();
		return controller;
	}

	// The world view is read each time rather than kept, since a figure can outlive a scene reload.
	@Nullable
	private LocalPoint localPoint()
	{
		WorldView view = client.getTopLevelWorldView();
		return view == null ? null : new LocalPoint((int) x, (int) y, view);
	}

	private void apply()
	{
		LocalPoint point = localPoint();
		if (point == null)
		{
			return;
		}
		object.setLocation(point, plane);
		dirty = false;
	}

	// Jagex angles go 0-2047 anticlockwise from south: 0 south, 512 west, 1024 north, 1536 east.
	private void face(double dx, double dy)
	{
		if (Math.abs(dx) < 1 && Math.abs(dy) < 1)
		{
			return;
		}
		int orientation = (int) (Math.atan2(-dx, -dy) * (1024.0 / Math.PI));
		object.setOrientation(orientation & 0x7FF);
	}

	private static String clip(String text)
	{
		if (text == null)
		{
			return "";
		}
		return text.length() <= MAX_TEXT ? text : text.substring(0, MAX_TEXT) + "…";
	}
}

package com.groupironmencompanion.scene;

import com.groupironmencompanion.activity.Activity;
import com.groupironmencompanion.data.GroupSkill;
import javax.annotation.Nullable;
import net.runelite.api.gameval.AnimationID;

/**
 * Picks a ghost's animations.
 * <p>
 * What a member is doing comes from their {@link Activity}, the same guess the status overlay
 * and side panel show, so the figure and the text always agree. How they're moving comes from
 * their position between updates. No client calls in here, so it's all testable.
 */
final class GhostAnimations
{
	/** Ticks between swings, chops and so on. Four is the usual weapon speed. */
	static final int ACTION_INTERVAL_TICKS = 4;

	// Walking is a tile a tick and running is two. Sits above sqrt(2) so a diagonal step
	// measured as a straight line still counts as walking.
	private static final double RUN_THRESHOLD_TILES_PER_TICK = 1.7;

	enum Movement
	{
		STILL,
		WALKING,
		RUNNING
	}

	private GhostAnimations()
	{
	}

	/**
	 * How fast someone covered a distance.
	 *
	 * @param tiles        distance between two reported positions
	 * @param elapsedTicks ticks between them, at least one
	 */
	static Movement movementFor(double tiles, int elapsedTicks)
	{
		if (tiles <= 0 || elapsedTicks <= 0)
		{
			return Movement.STILL;
		}
		return tiles / elapsedTicks > RUN_THRESHOLD_TILES_PER_TICK ? Movement.RUNNING : Movement.WALKING;
	}

	static int poseFor(Movement movement)
	{
		switch (movement)
		{
			case RUNNING:
				return AnimationID.HUMAN_RUNNING;
			case WALKING:
				return AnimationID.HUMAN_WALK_F;
			case STILL:
			default:
				return AnimationID.HUMAN_READY;
		}
	}

	/**
	 * The action to repeat, or -1 for none. Nobody swings or chops while moving, so a moving
	 * member gets no action, though they're still fighting as far as {@link #isFighting} goes.
	 */
	static int actionFor(@Nullable Activity activity, WeaponClass weapon, boolean moving)
	{
		if (activity == null || moving)
		{
			return -1;
		}
		switch (activity.getKind())
		{
			case FIGHTING:
				return attackFor(activity.getSkill(), weapon);
			case FISHING:
			case PICKPOCKETING:
			case SKILLING:
				return skillingFor(activity.getSkill());
			default:
				return -1;
		}
	}

	/** Moving doesn't end a fight: someone kiting or running from an NPC is still fighting it. */
	static boolean isFighting(@Nullable Activity activity)
	{
		return activity != null && activity.getKind() == Activity.Kind.FIGHTING;
	}

	// The plain human attack animations, not each weapon's own (those are in a stance table
	// the API doesn't expose). Close enough to read as the right kind of attack.
	private static int attackFor(@Nullable GroupSkill skill, WeaponClass weapon)
	{
		// XP says more than a weapon name we may not recognise.
		if (skill == GroupSkill.MAGIC)
		{
			return AnimationID.HUMAN_CASTING;
		}
		if (skill == GroupSkill.RANGED && weapon != WeaponClass.CROSSBOW && weapon != WeaponClass.THROWN)
		{
			return AnimationID.HUMAN_BOW;
		}

		switch (weapon)
		{
			case BOW:
				return AnimationID.HUMAN_BOW;
			case CROSSBOW:
				return AnimationID.HUMAN_CROSSBOW;
			case THROWN:
				return AnimationID.HUMAN_THROW;
			case STAFF:
				return AnimationID.HUMAN_CASTING;
			case MELEE_STAB:
				return AnimationID.HUMAN_SWORD_STAB;
			case MELEE_CRUSH:
				return AnimationID.HUMAN_AXE_SMASH;
			case MELEE_SLASH:
				return AnimationID.HUMAN_SWORD_SLASH;
			case UNARMED:
			default:
				return AnimationID.HUMAN_UNARMEDPUNCH;
		}
	}

	// One representative animation per skill. Agility and Sailing have none: the movement
	// already says it.
	private static int skillingFor(@Nullable GroupSkill skill)
	{
		if (skill == null)
		{
			return -1;
		}
		switch (skill)
		{
			case WOODCUTTING:
				return AnimationID.HUMAN_WOODCUTTING_RUNE_AXE;
			case MINING:
				return AnimationID.HUMAN_MINING_RUNE_PICKAXE;
			case FISHING:
				return AnimationID.HUMAN_FISH_ONSPOT;
			case FARMING:
				return AnimationID.PICKING_LOW;
			case COOKING:
				return AnimationID.HUMAN_COOKING;
			case FIREMAKING:
				return AnimationID.HUMAN_CREATEFIRE;
			case SMITHING:
				return AnimationID.HUMAN_SMITHING;
			case HERBLORE:
				return AnimationID.HUMAN_HERBING_VIAL;
			case FLETCHING:
				return AnimationID.HUMAN_FLETCHING;
			case CRAFTING:
				return AnimationID.HUMAN_LEATHER_CRAFTING;
			case THIEVING:
				return AnimationID.HUMAN_PICKPOCKET;
			case RUNECRAFT:
				return AnimationID.HUMAN_RUNECRAFT;
			case MAGIC:
				return AnimationID.HUMAN_CASTING;
			case CONSTRUCTION:
				return AnimationID.HUMAN_POH_BUILD;
			case PRAYER:
			case HUNTER:
				return AnimationID.HUMAN_PICKUPFLOOR;
			default:
				return -1;
		}
	}
}

package com.groupironmencompanion.scene;

import java.util.Arrays;

/**
 * Works out which mesh goes in each of a figure's twelve appearance slots.
 * <p>
 * Starts with the body, then each equipped item replaces what it covers. An item's second mesh
 * is whatever it puts over the body underneath: a platebody's sleeves go in the arms slot,
 * while a chainbody has none and leaves the arms showing.
 * <p>
 * Headgear always hides hair and beard. Full helms and med helms look the same in the data,
 * and missing hair under a med helm is less noticeable than hair poking through a full helm.
 */
final class GhostAppearance
{
	// Appearance slots, in the game's order.
	static final int HEAD = 0;
	static final int CAPE = 1;
	static final int AMULET = 2;
	static final int WEAPON = 3;
	static final int TORSO = 4;
	static final int SHIELD = 5;
	static final int ARMS = 6;
	static final int LEGS = 7;
	static final int HAIR = 8;
	static final int HANDS = 9;
	static final int BOOTS = 10;
	static final int JAW = 11;

	static final int SLOT_COUNT = 12;

	// Male body kit parts, as numbered in the cache.
	private static final int KIT_HAIR = 0;
	private static final int KIT_JAW = 1;
	private static final int KIT_TORSO = 2;
	private static final int KIT_ARMS = 3;
	private static final int KIT_HANDS = 4;
	private static final int KIT_LEGS = 5;
	private static final int KIT_FEET = 6;

	// Equipment slot (EquipmentInventorySlot index) to appearance slot. Rings and ammo aren't drawn.
	private static final int[] EQUIPMENT_TO_SLOT = {
		HEAD,   // 0  head
		CAPE,   // 1  cape
		AMULET, // 2  amulet
		WEAPON, // 3  weapon
		TORSO,  // 4  body
		SHIELD, // 5  shield
		-1,     // 6
		LEGS,   // 7  legs
		-1,     // 8
		HANDS,  // 9  gloves
		BOOTS,  // 10 boots
		-1,     // 11
		-1,     // 12 ring
		-1      // 13 ammo
	};

	private GhostAppearance()
	{
	}

	/**
	 * The mesh for each slot, -1 where nothing is drawn.
	 *
	 * @param equippedItemIds item id per equipment slot, 0 for empty; may be short or null
	 */
	static int[] resolve(int[] equippedItemIds, GearTable table)
	{
		int[] slots = new int[SLOT_COUNT];
		Arrays.fill(slots, -1);

		slots[HAIR] = table.bodyModel(KIT_HAIR);
		slots[JAW] = table.bodyModel(KIT_JAW);
		slots[TORSO] = table.bodyModel(KIT_TORSO);
		slots[ARMS] = table.bodyModel(KIT_ARMS);
		slots[HANDS] = table.bodyModel(KIT_HANDS);
		slots[LEGS] = table.bodyModel(KIT_LEGS);
		slots[BOOTS] = table.bodyModel(KIT_FEET);

		if (equippedItemIds == null)
		{
			return slots;
		}

		int count = Math.min(equippedItemIds.length, EQUIPMENT_TO_SLOT.length);
		for (int equipSlot = 0; equipSlot < count; equipSlot++)
		{
			int slot = EQUIPMENT_TO_SLOT[equipSlot];
			int itemId = equippedItemIds[equipSlot];
			if (slot < 0 || itemId <= 0)
			{
				continue;
			}

			// Unknown to the table (newer than it): leave the body showing.
			int[] models = table.wornModels(itemId);
			if (models == null)
			{
				continue;
			}

			slots[slot] = models[0];
			applySecondary(slots, slot, models[1]);
		}
		return slots;
	}

	private static void applySecondary(int[] slots, int slot, int secondary)
	{
		switch (slot)
		{
			case TORSO:
				if (secondary > 0)
				{
					slots[ARMS] = secondary;
				}
				break;
			case HEAD:
				slots[HAIR] = -1;
				slots[JAW] = secondary > 0 ? secondary : -1;
				break;
			default:
				// A second mesh on anything else is rare and the data doesn't say where it goes,
				// so it's left off rather than guessed.
				break;
		}
	}
}

package com.groupironmencompanion.scene;

import com.groupironmencompanion.GroupIronmenCompanionConfig;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.util.Collection;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Names the ghost under the cursor, with what it's doing underneath.
 * <p>
 * Styled to look nothing like the game's right-click menu, because it isn't one. Nothing here
 * can be clicked: it registers no mouse listener and the plugin creates no menu entries. It
 * just reads where the cursor is.
 */
@Singleton
public class GhostLabelOverlay extends Overlay
{
	private static final Color BACKGROUND = new Color(14, 22, 38, 225);
	private static final Color BORDER = new Color(96, 148, 205, 190);
	private static final Color TITLE_TEXT = new Color(176, 214, 255);
	private static final Color DETAIL_TEXT = new Color(150, 170, 196);

	private static final Font FONT = new Font(Font.SANS_SERIF, Font.PLAIN, 12);

	// How close the cursor has to be to a figure, in pixels.
	private static final int HOVER_RADIUS = 28;

	private static final int PADDING = 6;
	private static final int LINE_HEIGHT = 14;
	private static final int CURSOR_OFFSET = 14;
	private static final int CORNER = 6;

	@Inject
	private Client client;

	@Inject
	private GroupIronmenCompanionConfig config;

	@Inject
	private GroupScenePresence presence;

	@Inject
	public GhostLabelOverlay()
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// This runs every frame, so check the empty list before touching config.
		Collection<Ghost> ghosts = presence.getVisible();
		if (ghosts.isEmpty() || !config.scenePresence() || !config.scenePresenceLabels())
		{
			return null;
		}

		Point mouse = client.getMouseCanvasPosition();
		if (mouse == null)
		{
			return null;
		}

		Ghost hovered = nearest(ghosts, mouse);
		if (hovered != null)
		{
			draw(graphics, mouse, hovered);
		}
		return null;
	}

	// The closest one, so overlapping figures resolve to the one actually pointed at.
	@Nullable
	private static Ghost nearest(Collection<Ghost> ghosts, Point mouse)
	{
		Ghost best = null;
		double bestDistance = HOVER_RADIUS;
		for (Ghost ghost : ghosts)
		{
			Point canvas = ghost.canvasLocation();
			if (canvas == null)
			{
				continue;
			}
			double distance = Math.hypot(canvas.getX() - mouse.getX(), canvas.getY() - mouse.getY());
			if (distance < bestDistance)
			{
				bestDistance = distance;
				best = ghost;
			}
		}
		return best;
	}

	private void draw(Graphics2D graphics, Point mouse, Ghost ghost)
	{
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setFont(FONT);
		FontMetrics metrics = graphics.getFontMetrics();

		String title = ghost.getTitle();
		String detail = ghost.getDetail();

		int width = metrics.stringWidth(title);
		if (detail != null)
		{
			width = Math.max(width, metrics.stringWidth(detail));
		}
		int boxWidth = width + PADDING * 2;
		int boxHeight = (detail == null ? 1 : 2) * LINE_HEIGHT + PADDING * 2 - 2;

		// Beside the cursor, flipped to the other side near the canvas edge.
		int x = mouse.getX() + CURSOR_OFFSET;
		int y = mouse.getY() + CURSOR_OFFSET;
		if (x + boxWidth > client.getCanvasWidth())
		{
			x = Math.max(0, mouse.getX() - boxWidth - 4);
		}
		if (y + boxHeight > client.getCanvasHeight())
		{
			y = Math.max(0, mouse.getY() - boxHeight - 4);
		}

		graphics.setColor(BACKGROUND);
		graphics.fillRoundRect(x, y, boxWidth, boxHeight, CORNER, CORNER);
		graphics.setColor(BORDER);
		graphics.setStroke(new BasicStroke(1f));
		graphics.drawRoundRect(x, y, boxWidth - 1, boxHeight - 1, CORNER, CORNER);

		int textY = y + PADDING + metrics.getAscent() - 2;
		graphics.setColor(TITLE_TEXT);
		graphics.drawString(title, x + PADDING, textY);
		if (detail != null)
		{
			graphics.setColor(DETAIL_TEXT);
			graphics.drawString(detail, x + PADDING, textY + LINE_HEIGHT);
		}
	}
}

package com.groupironmencompanion.scene;

import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;
import net.runelite.api.gameval.NpcID;

/**
 * Builds the translucent blue models.
 * <p>
 * Members are built from the gear they're wearing, using {@link GearTable}. The body under it
 * is a fixed default since nobody publishes their build or skin, and it's all tinted blue
 * anyway. Built models are cached by outfit, so a group in matching gear shares one.
 */
@Slf4j
@Singleton
public class GhostModels
{
	// Used only if the gear table can't be read.
	private static final int BASE_FIGURE_NPC = NpcID.MAN;

	// Jagex colours are packed as hue << 10 | saturation << 7 | luminance.
	private static final int HUE_SHIFT = 10;
	private static final int SATURATION_SHIFT = 7;
	private static final int LUMINANCE_MASK = 0x7F;

	// A pale, washed-out blue.
	private static final int GHOST_HUE = 41;
	private static final int GHOST_SATURATION = 2;

	private static final int CACHE_LIMIT = 32;

	@Inject
	private Client client;

	// Client thread only.
	private final Map<Integer, Model> cache = new HashMap<>();
	private final Map<String, Model> outfits = new HashMap<>();

	private GearTable gear;
	private boolean gearLoadAttempted;

	// Transparency is baked into the mesh, so changing it means rebuilding.
	private int cachedTransparency = -1;

	/**
	 * A member wearing these items. Client thread.
	 *
	 * @param transparency 0 opaque to 255 invisible
	 */
	@Nullable
	Model member(int[] equippedItemIds, int transparency)
	{
		GearTable table = gear();
		if (table == null)
		{
			return forNpc(BASE_FIGURE_NPC, transparency);
		}
		if (transparency != cachedTransparency)
		{
			dropCaches(transparency);
		}

		int[] slots = GhostAppearance.resolve(equippedItemIds, table);
		String key = Arrays.toString(slots);
		Model cached = outfits.get(key);
		if (cached != null)
		{
			return cached;
		}

		Model built = assemble(slots, transparency);
		if (built != null)
		{
			if (outfits.size() >= CACHE_LIMIT)
			{
				outfits.clear();
			}
			outfits.put(key, built);
		}
		return built;
	}

	/** The NPC a member is fighting. Client thread. */
	@Nullable
	Model forNpc(int npcId, int transparency)
	{
		if (transparency != cachedTransparency)
		{
			dropCaches(transparency);
		}

		Model cached = cache.get(npcId);
		if (cached != null)
		{
			return cached;
		}

		Model built = build(npcId, transparency);
		if (built != null)
		{
			if (cache.size() >= CACHE_LIMIT)
			{
				cache.clear();
			}
			cache.put(npcId, built);
		}
		return built;
	}

	void clear()
	{
		cache.clear();
		outfits.clear();
		cachedTransparency = -1;
	}

	// If any mesh isn't loaded yet, give up and try next tick rather than draw a missing limb.
	@Nullable
	private Model assemble(int[] slots, int transparency)
	{
		ModelData[] parts = new ModelData[slots.length];
		int count = 0;
		for (int model : slots)
		{
			if (model <= 0)
			{
				continue;
			}
			ModelData mesh = client.loadModelData(model);
			if (mesh == null)
			{
				return null;
			}
			parts[count++] = mesh;
		}
		if (count == 0)
		{
			return null;
		}

		ModelData merged = client.mergeModels(Arrays.copyOf(parts, count));
		return merged == null ? null : tint(merged, transparency).light();
	}

	@Nullable
	private Model build(int npcId, int transparency)
	{
		NPCComposition composition = client.getNpcDefinition(npcId);
		int[] parts = composition == null ? null : composition.getModels();
		if (parts == null || parts.length == 0)
		{
			return null;
		}

		ModelData[] meshes = new ModelData[parts.length];
		for (int i = 0; i < parts.length; i++)
		{
			meshes[i] = client.loadModelData(parts[i]);
			if (meshes[i] == null)
			{
				return null;
			}
		}

		ModelData merged = client.mergeModels(meshes);
		return merged == null ? null : tint(merged, transparency).light();
	}

	@Nullable
	private GearTable gear()
	{
		if (!gearLoadAttempted)
		{
			gearLoadAttempted = true;
			gear = GearTable.load();
		}
		return gear;
	}

	private void dropCaches(int transparency)
	{
		cache.clear();
		outfits.clear();
		cachedTransparency = transparency;
	}

	// Recolours every face blue, keeping its brightness so the shape still has depth, and makes
	// it see-through.
	private ModelData tint(ModelData model, int transparency)
	{
		ModelData tinted = model.cloneColors();
		short[] colours = tinted.getFaceColors();
		if (colours != null)
		{
			for (int i = 0; i < colours.length; i++)
			{
				int luminance = colours[i] & LUMINANCE_MASK;
				colours[i] = (short) ((GHOST_HUE << HUE_SHIFT) | (GHOST_SATURATION << SATURATION_SHIFT) | luminance);
			}
		}

		// true allocates the array if the model had no transparency data, which most don't.
		ModelData translucent = tinted.cloneTransparencies(true);
		byte[] faces = translucent.getFaceTransparencies();
		if (faces == null)
		{
			log.debug("Ghost model has no transparency data; drawing it opaque");
			return translucent;
		}
		Arrays.fill(faces, (byte) Math.max(0, Math.min(255, transparency)));
		return translucent;
	}
}

package com.groupironmencompanion.scene;

import com.groupironmencompanion.GroupIronmenCompanionConfig;
import com.groupironmencompanion.activity.Activity;
import com.groupironmencompanion.activity.ActivityTracker;
import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupState;
import com.groupironmencompanion.data.ItemStack;
import com.groupironmencompanion.scene.GhostAnimations.Movement;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.game.ItemManager;

/**
 * Draws group members on other worlds, and whatever they're fighting, as translucent figures.
 * <p>
 * The figures are {@link net.runelite.api.RuneLiteObject}s: the client draws them, but they're
 * not in the player or NPC lists, can't be clicked, and the server never hears about them.
 * <p>
 * What each figure does comes from {@link ActivityTracker}, the same guess the status overlay
 * and side panel show, so the two never disagree. Only members inside the loaded scene get a
 * figure, so anyone further away costs one coordinate check.
 */
@Singleton
public class GroupScenePresence
{
	// A fight further away than this is one they've walked off from.
	private static final int INTERACTION_MAX_TILES = 12;

	// The name and weapon lookups are keyed on things the group's server sends, so they're
	// capped rather than trusted to stay small.
	private static final int LOOKUP_CACHE_LIMIT = 256;

	@Inject
	private Client client;

	@Inject
	private GroupState groupState;

	@Inject
	private ActivityTracker activityTracker;

	@Inject
	private GroupIronmenCompanionConfig config;

	@Inject
	private GhostModels models;

	@Inject
	private ScenePresenceGate gate;

	@Inject
	private ItemManager itemManager;

	// All client thread, keyed by member name.
	private final Map<String, Ghost> memberGhosts = new HashMap<>();
	private final Map<String, Ghost> npcGhosts = new HashMap<>();
	private final Map<String, MemberTrail> trails = new HashMap<>();

	// Finding an NPC's id by name means walking the scene's NPC list, so it's done once.
	private final Map<String, Integer> npcIdByName = new HashMap<>();
	private final Map<Integer, WeaponClass> weaponClasses = new HashMap<>();

	// Read by the hover label.
	private volatile List<Ghost> visible = Collections.emptyList();

	private int tickCounter;

	/** Rebuilds the figures. Game tick, client thread. */
	public void onGameTick()
	{
		if (!gate.allowed())
		{
			clear();
			return;
		}

		WorldView view = client.getTopLevelWorldView();
		if (view == null)
		{
			clear();
			return;
		}

		tickCounter++;
		int transparency = config.scenePresenceTransparency();
		Instant now = Instant.now();
		Set<String> present = new HashSet<>();

		for (GroupMember member : groupState.getMembers())
		{
			if (groupState.isLocalPlayer(member) || !member.isOnline(config.offlineAfterMinutes()))
			{
				continue;
			}

			WorldPoint position = member.getWorldPoint();
			if (position == null || member.isOnBoat() || alreadyDrawnByTheGame(view, member))
			{
				continue;
			}

			LocalPoint local = LocalPoint.fromWorld(view, position);
			if (!drawable(view, local, position.getPlane()))
			{
				continue;
			}

			present.add(member.getName());
			updateMember(view, member, position, local, transparency, now);
		}

		retireAllExcept(present);
		republish();
	}

	/** Eases the figures along. Every frame, client thread. */
	public void onClientTick()
	{
		for (Ghost ghost : memberGhosts.values())
		{
			ghost.advance();
		}
		for (Ghost ghost : npcGhosts.values())
		{
			ghost.advance();
		}
	}

	public Collection<Ghost> getVisible()
	{
		return visible;
	}

	/** Removes every figure. Client thread. */
	public void clear()
	{
		for (Ghost ghost : memberGhosts.values())
		{
			ghost.destroy();
		}
		for (Ghost ghost : npcGhosts.values())
		{
			ghost.destroy();
		}
		memberGhosts.clear();
		npcGhosts.clear();
		trails.clear();
		visible = Collections.emptyList();
	}

	/** Also drops cached models and lookups, after a settings change. Client thread. */
	public void reset()
	{
		clear();
		models.clear();
		npcIdByName.clear();
		weaponClasses.clear();
	}

	private void updateMember(WorldView view, GroupMember member, WorldPoint position, LocalPoint local,
		int transparency, Instant now)
	{
		String name = member.getName();
		Activity activity = activityTracker.get(name);

		Ghost ghost = memberGhosts.computeIfAbsent(name, key -> new Ghost(client, local, position.getPlane()));
		ghost.setModel(models.member(equippedItemIds(member), transparency));
		ghost.moveTo(local, position.getPlane());
		ghost.setLabel(name, activity == null ? null : activity.describe(now, false));

		MemberTrail trail = trails.computeIfAbsent(name, key -> new MemberTrail());
		trail.observe(position, tickCounter);

		boolean moving = ghost.isMoving();
		int pose = GhostAnimations.poseFor(moving ? trail.getMovement() : Movement.STILL);
		ghost.setAnimation(pose, GhostAnimations.actionFor(activity, weaponOf(member), moving));
		ghost.onGameTick();

		updateTarget(view, member, position, local, transparency, ghost, activity, moving);
	}

	/**
	 * Turns the member to face whoever they're interacting with, and draws the NPC if it's a
	 * fight. The opponent stays while they move, since running from an NPC is still a fight.
	 * <p>
	 * We get the NPC's name and position but not its id, which a model needs. Members are in
	 * the same place on different worlds, so the same NPC is almost always in our scene too and
	 * we borrow its id. If it isn't, there's just no opponent drawn.
	 */
	private void updateTarget(WorldView view, GroupMember member, WorldPoint position, LocalPoint local,
		int transparency, Ghost ghost, @Nullable Activity activity, boolean moving)
	{
		String name = member.getName();
		String target = activity == null ? null : activity.getTarget();
		GroupMember.Interaction interaction = member.getInteraction();

		// The activity is worked out on the polling thread, so the interaction may already have
		// moved on to someone else. Only trust it when both agree on who.
		WorldPoint at = target != null && interaction != null && target.equals(interaction.getName())
			? interaction.getLocation()
			: null;
		LocalPoint atLocal = at != null && at.getPlane() == position.getPlane()
			&& at.distanceTo(position) <= INTERACTION_MAX_TILES
			? LocalPoint.fromWorld(view, at)
			: null;

		if (atLocal == null || !drawable(view, atLocal, at.getPlane()))
		{
			retireNpc(name);
			return;
		}

		if (!moving)
		{
			ghost.faceTowards(atLocal);
		}

		Integer npcId = GhostAnimations.isFighting(activity) && config.scenePresenceOpponents()
			? resolveNpcId(view, target)
			: null;
		if (npcId == null)
		{
			retireNpc(name);
			return;
		}

		Ghost opponent = npcGhosts.computeIfAbsent(name, key -> new Ghost(client, atLocal, at.getPlane()));
		opponent.setModel(models.forNpc(npcId, transparency));
		opponent.moveTo(atLocal, at.getPlane());
		opponent.faceTowards(local);
		opponent.setLabel(target, "Fighting " + name);
	}

	/**
	 * Whether we're willing to draw at a position. It has to be in the loaded scene, and on a
	 * real plane: the plane comes straight off the group's server and the client indexes arrays
	 * by it, so nothing outside 0-3 gets through.
	 */
	private static boolean drawable(WorldView view, @Nullable LocalPoint point, int plane)
	{
		if (point == null || !isRealPlane(plane))
		{
			return false;
		}
		int x = point.getSceneX();
		int y = point.getSceneY();
		return x >= 0 && y >= 0 && x < view.getSizeX() && y < view.getSizeY();
	}

	/**
	 * Whether the game is drawing this member already because they're on our world. Uses the
	 * reported world when there is one. Before their stats arrive there isn't, so check the
	 * scene for a player with their name instead.
	 */
	private boolean alreadyDrawnByTheGame(WorldView view, GroupMember member)
	{
		int world = member.getWorld();
		if (world > 0)
		{
			return isOurWorld(world, client.getWorld());
		}
		for (Player player : view.players())
		{
			if (GroupState.namesMatch(player.getName(), member.getName()))
			{
				return true;
			}
		}
		return false;
	}

	static boolean isOurWorld(int memberWorld, int localWorld)
	{
		return memberWorld > 0 && memberWorld == localWorld;
	}

	static boolean isRealPlane(int plane)
	{
		return plane >= 0 && plane < Constants.MAX_Z;
	}

	// Any NPC with the name has the right model. Misses aren't remembered, so it tries again
	// as the scene changes.
	@Nullable
	private Integer resolveNpcId(WorldView view, @Nullable String name)
	{
		if (name == null || name.isEmpty())
		{
			return null;
		}
		Integer known = npcIdByName.get(name);
		if (known != null)
		{
			return known;
		}
		for (NPC npc : view.npcs())
		{
			if (name.equals(npc.getName()))
			{
				remember(npcIdByName, name, npc.getId());
				return npc.getId();
			}
		}
		return null;
	}

	// Equipment arrives positionally, so a slot's index is the equipment slot and empty is 0.
	private static int[] equippedItemIds(GroupMember member)
	{
		List<ItemStack> equipment = member.getEquipment();
		int[] ids = new int[equipment.size()];
		for (int slot = 0; slot < ids.length; slot++)
		{
			ItemStack item = equipment.get(slot);
			ids[slot] = item == null || item.isEmpty() ? 0 : item.getId();
		}
		return ids;
	}

	private WeaponClass weaponOf(GroupMember member)
	{
		List<ItemStack> equipment = member.getEquipment();
		int slot = EquipmentInventorySlot.WEAPON.getSlotIdx();
		ItemStack weapon = slot < equipment.size() ? equipment.get(slot) : null;
		if (weapon == null || weapon.isEmpty())
		{
			return WeaponClass.UNARMED;
		}

		WeaponClass known = weaponClasses.get(weapon.getId());
		if (known != null)
		{
			return known;
		}

		WeaponClass resolved;
		try
		{
			resolved = WeaponClass.classify(itemManager.getItemComposition(weapon.getId()).getName());
		}
		catch (RuntimeException e)
		{
			// An id this client doesn't know yet.
			resolved = WeaponClass.UNARMED;
		}
		remember(weaponClasses, weapon.getId(), resolved);
		return resolved;
	}

	private static <K, V> void remember(Map<K, V> cache, K key, V value)
	{
		if (cache.size() >= LOOKUP_CACHE_LIMIT)
		{
			cache.clear();
		}
		cache.put(key, value);
	}

	private void retireAllExcept(Set<String> present)
	{
		retire(memberGhosts, present);
		retire(npcGhosts, present);
		trails.keySet().retainAll(present);
	}

	private static void retire(Map<String, Ghost> ghosts, Set<String> present)
	{
		for (Iterator<Map.Entry<String, Ghost>> it = ghosts.entrySet().iterator(); it.hasNext(); )
		{
			Map.Entry<String, Ghost> entry = it.next();
			if (!present.contains(entry.getKey()))
			{
				entry.getValue().destroy();
				it.remove();
			}
		}
	}

	private void retireNpc(String memberName)
	{
		Ghost opponent = npcGhosts.remove(memberName);
		if (opponent != null)
		{
			opponent.destroy();
		}
	}

	private void republish()
	{
		List<Ghost> drawn = new ArrayList<>(memberGhosts.size() + npcGhosts.size());
		drawn.addAll(memberGhosts.values());
		drawn.addAll(npcGhosts.values());
		visible = Collections.unmodifiableList(drawn);
	}
}

package com.groupironmencompanion.scene;

import com.groupironmencompanion.scene.GhostAnimations.Movement;
import net.runelite.api.coords.WorldPoint;

/**
 * Tracks how fast a member is moving.
 * <p>
 * Positions arrive less often than this is asked, so most ticks bring the same position as
 * last time. Calling that "stopped" made a running member flicker between running and
 * standing, so speed is only measured when the position actually changes, and held until it
 * does again. Whether the figure is still moving is up to the {@link Ghost}, which knows how
 * far it has left to go.
 */
class MemberTrail
{
	private WorldPoint lastPosition;
	private int lastChangeTick = -1;
	private Movement movement = Movement.STILL;

	/** @param tick a game tick counter that only ever goes up */
	void observe(WorldPoint position, int tick)
	{
		if (lastPosition == null)
		{
			lastPosition = position;
			lastChangeTick = tick;
			return;
		}
		if (lastPosition.equals(position))
		{
			return;
		}

		if (lastPosition.getPlane() != position.getPlane())
		{
			// Stairs or a teleport, not a walk.
			movement = Movement.STILL;
		}
		else
		{
			int elapsed = Math.max(1, tick - lastChangeTick);
			movement = GhostAnimations.movementFor(lastPosition.distanceTo2D(position), elapsed);
		}

		lastPosition = position;
		lastChangeTick = tick;
	}

	/** How they were last seen moving. Only asked while the figure is moving, so never STILL. */
	Movement getMovement()
	{
		return movement == Movement.STILL ? Movement.WALKING : movement;
	}
}

package com.groupironmencompanion.scene;

import com.groupironmencompanion.GroupIronmenCompanionConfig;
import java.util.EnumSet;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldType;
import net.runelite.api.WorldView;
import net.runelite.api.gameval.VarbitID;

/**
 * Decides whether ghosts can be drawn at all.
 * <p>
 * Never in the Wilderness or on a PvP world, and there's deliberately no setting for that. A
 * figure you can't click is fine next to a farming patch, but in the Wilderness it looks like
 * a player and can stand between you and a real one. Don't add a setting for it.
 * <p>
 * Not in instances either, since coordinates there are remapped and a member's position
 * would land somewhere unrelated.
 */
@Singleton
public class ScenePresenceGate
{
	// Worlds where players can attack you anywhere, plus other combat worlds where a ghost
	// would mean nothing.
	private static final Set<WorldType> FORBIDDEN_WORLDS = EnumSet.of(
		WorldType.PVP,
		WorldType.BOUNTY,
		WorldType.HIGH_RISK,
		WorldType.DEADMAN,
		WorldType.LAST_MAN_STANDING,
		WorldType.PVP_ARENA,
		WorldType.TOURNAMENT_WORLD,
		WorldType.BETA_WORLD);

	@Inject
	private Client client;

	@Inject
	private GroupIronmenCompanionConfig config;

	/** Checked every tick, never cached: hopping or crossing the ditch changes the answer. */
	public boolean allowed()
	{
		if (!config.scenePresence()
			|| client.getGameState() != GameState.LOGGED_IN
			|| isForbiddenWorld(client.getWorldType())
			|| client.getVarbitValue(VarbitID.INSIDE_WILDERNESS) != 0)
		{
			return false;
		}
		WorldView view = client.getTopLevelWorldView();
		return view != null && !view.isInstance();
	}

	static boolean isForbiddenWorld(Set<WorldType> types)
	{
		if (types == null)
		{
			// Not told yet. Draw nothing until we are.
			return true;
		}
		// RuneLite's own check first, so a PvP world type added later is covered too.
		if (WorldType.isPvpWorld(types))
		{
			return true;
		}
		for (WorldType type : types)
		{
			if (FORBIDDEN_WORLDS.contains(type))
			{
				return true;
			}
		}
		return false;
	}
}

package com.groupironmencompanion.scene;

import java.util.Locale;

/**
 * Rough weapon types, enough to pick an attack animation.
 * <p>
 * Goes by item name. The real weapon type is in the cache but not in the API, and getting a
 * name wrong only means a ghost swings the wrong way.
 */
enum WeaponClass
{
	UNARMED,
	MELEE_STAB,
	MELEE_SLASH,
	MELEE_CRUSH,
	BOW,
	CROSSBOW,
	THROWN,
	STAFF;

	/** Most specific match first, since names like "dragon crossbow" contain several. */
	static WeaponClass classify(String itemName)
	{
		if (itemName == null || itemName.isEmpty())
		{
			return UNARMED;
		}

		String name = itemName.toLowerCase(Locale.ROOT);

		if (name.contains("crossbow") || name.contains("c'bow") || name.contains("ballista"))
		{
			return CROSSBOW;
		}
		if (name.contains("bow") || name.contains("blowpipe"))
		{
			return BOW;
		}
		if (name.contains("staff") || name.contains("wand") || name.contains("sceptre")
			|| name.contains("trident"))
		{
			return STAFF;
		}
		if (name.contains("knife") || name.contains("dart") || name.contains("javelin")
			|| name.contains("thrownaxe") || name.contains("chinchompa"))
		{
			return THROWN;
		}
		if (name.contains("dagger") || name.contains("rapier") || name.contains("spear")
			|| name.contains("hasta") || name.contains("partisan"))
		{
			return MELEE_STAB;
		}
		if (name.contains("maul") || name.contains("hammer") || name.contains("mace")
			|| name.contains("club") || name.contains("bludgeon"))
		{
			return MELEE_CRUSH;
		}
		if (name.contains("sword") || name.contains("scimitar") || name.contains("axe")
			|| name.contains("halberd") || name.contains("whip") || name.contains("claws")
			|| name.contains("blade") || name.contains("cleaver") || name.contains("machete"))
		{
			return MELEE_SLASH;
		}

		// A cape, a bucket, a skilling tool. Punching beats nothing.
		return UNARMED;
	}
}

package com.groupironmencompanion.ui;

import com.groupironmencompanion.data.Diaries;
import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupState;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.ThinProgressBar;

/**
 * Achievement diary progress for the group: overall completion per member, and a per-region
 * breakdown of each tier.
 */
class DiariesView extends JPanel
{
	private static final String ALL_REGIONS = "All regions";

	private static final Color COMPLETE = new Color(0x55, 0xC5, 0x5A);
	private static final Color PARTIAL = new Color(0xE6, 0x96, 0x1E);
	private static final Color NONE = new Color(0x9E, 0x50, 0x50);
	private static final Color UNKNOWN = new Color(0x77, 0x77, 0x77);

	private final GroupState groupState;

	private final JComboBox<String> regionPicker = new JComboBox<>();
	private final JPanel rows = new JPanel();

	DiariesView(GroupState groupState)
	{
		this.groupState = groupState;

		setLayout(new BorderLayout(0, 6));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		DefaultComboBoxModel<String> model = new DefaultComboBoxModel<>();
		model.addElement(ALL_REGIONS);
		for (Diaries.Region region : Diaries.regions())
		{
			model.addElement(region.getName());
		}
		regionPicker.setModel(model);
		regionPicker.setPreferredSize(new Dimension(0, 24));
		regionPicker.setFocusable(false);
		regionPicker.setForeground(ColorScheme.TEXT_COLOR);
		regionPicker.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		regionPicker.addActionListener(e -> refresh());

		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		rows.setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(regionPicker, BorderLayout.NORTH);
		add(rows, BorderLayout.CENTER);
	}

	void refresh()
	{
		rows.removeAll();

		List<GroupMember> members = groupState.getMembers();
		if (members.isEmpty())
		{
			JLabel empty = new JLabel("No group data yet");
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setHorizontalAlignment(SwingConstants.CENTER);
			rows.add(empty);
		}
		else
		{
			Object selected = regionPicker.getSelectedItem();
			Diaries.Region region = null;
			if (selected != null && !ALL_REGIONS.equals(selected))
			{
				for (Diaries.Region candidate : Diaries.regions())
				{
					if (candidate.getName().equals(selected))
					{
						region = candidate;
						break;
					}
				}
			}

			for (GroupMember member : members)
			{
				rows.add(region == null ? overallRow(member) : regionRow(member, region));
			}
		}

		revalidate();
		repaint();
	}

	private JPanel overallRow(GroupMember member)
	{
		Diaries.Progress progress = Diaries.totalProgressOf(member);

		JPanel panel = card(member);
		JLabel count = new JLabel(progress.isKnown()
			? progress.getCompleted() + " / " + progress.getTotal() + " tasks"
			: "not reported");
		count.setFont(FontManager.getRunescapeSmallFont());
		count.setForeground(progress.isKnown() ? ColorScheme.LIGHT_GRAY_COLOR : UNKNOWN);
		count.setHorizontalAlignment(SwingConstants.RIGHT);
		((JPanel) panel.getComponent(0)).add(count, BorderLayout.EAST);

		if (progress.isKnown() && progress.getTotal() > 0)
		{
			ThinProgressBar bar = new ThinProgressBar();
			bar.setForeground(COMPLETE);
			bar.setMaximumValue(progress.getTotal());
			bar.setValue(progress.getCompleted());
			bar.setPreferredSize(new Dimension(0, 5));
			panel.add(bar);
		}

		return panel;
	}

	private JPanel regionRow(GroupMember member, Diaries.Region region)
	{
		JPanel panel = card(member);

		for (Diaries.Tier tier : Diaries.Tier.values())
		{
			Diaries.Progress progress = Diaries.progressOf(member, region, tier);

			JLabel name = new JLabel(tier.getLabel());
			name.setFont(FontManager.getRunescapeSmallFont());
			name.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

			JLabel value = new JLabel(progress.isKnown()
				? progress.getCompleted() + " / " + progress.getTotal()
				: "-");
			value.setFont(FontManager.getRunescapeSmallFont());
			value.setForeground(colourOf(progress));
			value.setHorizontalAlignment(SwingConstants.RIGHT);

			JPanel line = new JPanel(new GridLayout(1, 2));
			line.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			line.add(name);
			line.add(value);
			panel.add(line);
		}

		return panel;
	}

	/** A member card whose first component is a header ready for an EAST label. */
	private JPanel card(GroupMember member)
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			BorderFactory.createEmptyBorder(5, 6, 5, 6)));

		JLabel name = ServerText.label(groupState.isLocalPlayer(member) ? member.getName() + " (you)" : member.getName());
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(member.getColour());

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.add(name, BorderLayout.WEST);
		panel.add(header);

		return panel;
	}

	private static Color colourOf(Diaries.Progress progress)
	{
		if (!progress.isKnown())
		{
			return UNKNOWN;
		}
		if (progress.isComplete())
		{
			return COMPLETE;
		}
		return progress.getCompleted() > 0 ? PARTIAL : NONE;
	}
}

package com.groupironmencompanion.ui;

import com.groupironmencompanion.GroupIronmenCompanionConfig;
import com.groupironmencompanion.activity.ActivityTracker;
import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupState;
import java.awt.BorderLayout;
import java.awt.GridLayout;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import javax.swing.Timer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.materialtabs.MaterialTab;
import net.runelite.client.ui.components.materialtabs.MaterialTabGroup;

/**
 * The sidebar dashboard: connection status, member vitals, a group-wide item search, and
 * skill, quest and diary comparisons.
 * <p>
 * Everything shown is read from your group's server. The panel has no controls that affect
 * the game.
 */
public class GroupPanel extends PluginPanel
{
	/**
	 * How often the Group tab redraws while the sidebar shows it, so "last seen", idle times
	 * and short-lived activities keep moving when no member has uploaded anything new.
	 */
	private static final int TICK_MILLIS = 5000;

	private final GroupState groupState;
	private final GroupIronmenCompanionConfig config;
	private final ActivityTracker activityTracker;

	private final JLabel statusLabel = new JLabel();
	private final JPanel membersView = new JPanel();
	private final ItemSearchView itemsView;
	private final SkillsView skillsView;
	private final QuestsView questsView;
	private final DiariesView diariesView;

	private final Map<String, MemberCard> cards = new HashMap<>();

	private final Timer ticker = new Timer(TICK_MILLIS, e -> tick());

	/**
	 * Rebuild for whichever tab is on screen.
	 * <p>
	 * A refresh runs on every poll, and rebuilding all five views each time meant decoding
	 * every quest and all 492 diary tasks for every member several times a minute for panels
	 * nobody was looking at. Only the visible one is rebuilt; the rest catch up when selected.
	 */
	private Runnable activeView = () ->
	{
	};

	/** The Group tab's rebuild, held once so {@link #refreshMembersIfShown} can recognise it. */
	private final Runnable membersRefresh = this::refreshMembers;

	public GroupPanel(GroupState groupState, GroupIronmenCompanionConfig config,
		ActivityTracker activityTracker, ItemManager itemManager, ClientThread clientThread)
	{
		super(true);
		this.groupState = groupState;
		this.config = config;
		this.activityTracker = activityTracker;

		this.itemsView = new ItemSearchView(groupState, itemManager, clientThread);
		this.skillsView = new SkillsView(groupState);
		this.questsView = new QuestsView(groupState);
		this.diariesView = new DiariesView(groupState);

		setLayout(new BorderLayout(0, 6));
		setBackground(ColorScheme.DARK_GRAY_COLOR);
		setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setBorder(BorderFactory.createEmptyBorder(0, 0, 4, 0));

		membersView.setLayout(new BoxLayout(membersView, BoxLayout.Y_AXIS));
		membersView.setBackground(ColorScheme.DARK_GRAY_COLOR);

		JPanel display = new JPanel(new BorderLayout());
		display.setBackground(ColorScheme.DARK_GRAY_COLOR);

		MaterialTabGroup tabs = new MaterialTabGroup(display);
		// MaterialTabGroup defaults to a FlowLayout, which wraps extra tabs onto a second row
		// that BorderLayout.NORTH then clips to nothing. A grid keeps every tab visible and
		// reports an honest preferred height.
		tabs.setLayout(new GridLayout(0, 3, 4, 2));
		MaterialTab groupTab = new MaterialTab("Group", tabs, membersView);
		MaterialTab itemsTab = new MaterialTab("Items", tabs, itemsView);
		MaterialTab skillsTab = new MaterialTab("Skills", tabs, skillsView);
		MaterialTab questsTab = new MaterialTab("Quests", tabs, questsView);
		MaterialTab diariesTab = new MaterialTab("Diaries", tabs, diariesView);

		groupTab.setOnSelectEvent(() -> select(membersRefresh));
		itemsTab.setOnSelectEvent(() -> select(itemsView::refresh));
		skillsTab.setOnSelectEvent(() -> select(skillsView::refresh));
		questsTab.setOnSelectEvent(() -> select(questsView::refresh));
		diariesTab.setOnSelectEvent(() -> select(diariesView::refresh));

		tabs.addTab(groupTab);
		tabs.addTab(itemsTab);
		tabs.addTab(skillsTab);
		tabs.addTab(questsTab);
		tabs.addTab(diariesTab);
		tabs.select(groupTab);
		activeView = membersRefresh;

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARK_GRAY_COLOR);
		header.add(statusLabel, BorderLayout.NORTH);
		header.add(tabs, BorderLayout.SOUTH);

		add(header, BorderLayout.NORTH);
		add(display, BorderLayout.CENTER);
	}

	@Override
	public void onActivate()
	{
		ticker.start();
		refresh();
	}

	@Override
	public void onDeactivate()
	{
		ticker.stop();
	}

	/** Also stops when the panel is taken down, which does not always deactivate it first. */
	@Override
	public void removeNotify()
	{
		ticker.stop();
		super.removeNotify();
	}

	/** Only the Group tab shows anything that ages on its own. */
	private void tick()
	{
		if (activeView == membersRefresh)
		{
			membersRefresh.run();
		}
	}

	/** Safe to call from any thread. */
	public void refresh()
	{
		SwingUtilities.invokeLater(this::refreshOnEdt);
	}

	/**
	 * Redraws the Group tab if it is the one on screen. Online state, "last seen" and the
	 * activity line all age with the clock, so they need redrawing even when no new data
	 * arrives. The other tabs only change with the data. Safe to call from any thread.
	 */
	public void refreshMembersIfShown()
	{
		SwingUtilities.invokeLater(() ->
		{
			if (activeView == membersRefresh)
			{
				refreshMembers();
			}
		});
	}

	public void setStatus(String status)
	{
		SwingUtilities.invokeLater(() -> statusLabel.setText("<html>" + escape(status) + "</html>"));
	}

	/** Remembers which view is on screen and rebuilds it once, on selection. */
	private boolean select(Runnable view)
	{
		activeView = view;
		view.run();
		return true;
	}

	private void refreshOnEdt()
	{
		activeView.run();
	}

	private void refreshMembers()
	{
		List<GroupMember> members = groupState.getMembers();
		Instant now = Instant.now();

		// Reuse a card per member so the panel does not flicker on every poll.
		List<String> present = new ArrayList<>(members.size());
		membersView.removeAll();

		int shown = 0;
		for (GroupMember member : members)
		{
			boolean online = member.isOnline(config.offlineAfterMinutes());
			if (!online && !config.panelShowOffline())
			{
				continue;
			}
			if (groupState.isLocalPlayer(member) && !config.panelShowSelf())
			{
				continue;
			}

			present.add(member.getName());
			MemberCard card = cards.computeIfAbsent(member.getName(), name -> new MemberCard());
			card.update(member, online,
				config.panelShowActivity() ? activityTracker.get(member.getName()) : null, now,
				groupState.isLocalPlayer(member));
			membersView.add(card);
			shown++;
		}

		cards.keySet().retainAll(present);

		if (shown == 0)
		{
			JLabel empty = new JLabel(members.isEmpty()
				? "<html>No group data yet.<br>Check your group name and token in the plugin settings.</html>"
				: "<html>Every member is hidden by the<br>side panel settings.</html>");
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			membersView.add(empty);
		}

		membersView.revalidate();
		membersView.repaint();
	}

	private static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}
}

package com.groupironmencompanion.ui;

import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupState;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.util.AsyncBufferedImage;

/**
 * Searches everything the group owns and shows who is holding it.
 * <p>
 * Read-only: results are drawn from item ids and quantities the group's own clients reported
 * to your shared server. Nothing here can move an item.
 */
class ItemSearchView extends JPanel
{
	private static final int MAX_RESULTS = 60;
	private static final NumberFormat NUMBERS = NumberFormat.getIntegerInstance(Locale.ENGLISH);

	private final GroupState groupState;
	private final ItemManager itemManager;
	private final ClientThread clientThread;

	/**
	 * Increments on every search. A lookup hops to the client thread and back, so two quick
	 * keystrokes can return out of order; results from anything but the latest are dropped.
	 */
	private final java.util.concurrent.atomic.AtomicLong searchGeneration = new java.util.concurrent.atomic.AtomicLong();

	private final IconTextField search = new IconTextField();
	private final JPanel results = new JPanel();
	private final JLabel emptyLabel = new JLabel();

	ItemSearchView(GroupState groupState, ItemManager itemManager, ClientThread clientThread)
	{
		this.groupState = groupState;
		this.itemManager = itemManager;
		this.clientThread = clientThread;

		setLayout(new BorderLayout(0, 6));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		search.setIcon(IconTextField.Icon.SEARCH);
		search.setPreferredSize(new Dimension(0, 26));
		search.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		search.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		search.addActionListener(e -> refresh());
		search.addKeyListener(new java.awt.event.KeyAdapter()
		{
			@Override
			public void keyReleased(java.awt.event.KeyEvent e)
			{
				refresh();
			}
		});

		results.setLayout(new BoxLayout(results, BoxLayout.Y_AXIS));
		results.setBackground(ColorScheme.DARK_GRAY_COLOR);

		emptyLabel.setFont(FontManager.getRunescapeSmallFont());
		emptyLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		emptyLabel.setHorizontalAlignment(SwingConstants.CENTER);
		emptyLabel.setBorder(BorderFactory.createEmptyBorder(12, 0, 0, 0));

		add(search, BorderLayout.NORTH);
		add(results, BorderLayout.CENTER);
		add(emptyLabel, BorderLayout.SOUTH);
	}

	/**
	 * Rebuilds the result list. Item names and icons can only be read on the client thread,
	 * so the lookup hops there and the rows are added back on the Swing thread.
	 */
	void refresh()
	{
		final long generation = searchGeneration.incrementAndGet();

		String query = search.getText().trim().toLowerCase(Locale.ROOT);
		if (query.length() < 2)
		{
			results.removeAll();
			emptyLabel.setText("Type at least two letters");
			revalidate();
			repaint();
			return;
		}

		// Includes group storage already, so the per-owner breakdown below adds up to it.
		Map<Integer, Long> totals = groupState.getGroupTotals();

		clientThread.invoke(() ->
		{
			if (searchGeneration.get() != generation)
			{
				return;
			}

			List<Result> matches = new ArrayList<>();
			for (Map.Entry<Integer, Long> entry : totals.entrySet())
			{
				String name;
				try
				{
					name = itemManager.getItemComposition(entry.getKey()).getName();
				}
				catch (Exception e)
				{
					continue;
				}
				if (name == null || !name.toLowerCase(Locale.ROOT).contains(query))
				{
					continue;
				}
				matches.add(new Result(entry.getKey(), name, entry.getValue()));
			}

			matches.sort(Comparator.comparingLong((Result r) -> r.quantity).reversed());
			int total = matches.size();
			List<Result> capped = new ArrayList<>(matches.subList(0, Math.min(MAX_RESULTS, total)));

			// Rows are built on the Swing thread; item images are safe to request from
			// there because AsyncBufferedImage fills itself in once the game thread has it.
			SwingUtilities.invokeLater(() ->
			{
				if (searchGeneration.get() == generation)
				{
					show(capped, total);
				}
			});
		});
	}

	private JPanel buildRow(Result match)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		row.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			BorderFactory.createEmptyBorder(4, 4, 4, 4)));

		JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(36, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		// Quantity is part of ItemManager's 128-entry image cache key, so the plain sprite is
		// requested and the total is shown as text below instead of baked into the icon.
		AsyncBufferedImage image = itemManager.getImage(match.itemId);
		if (image != null)
		{
			image.addTo(icon);
		}

		JLabel name = new JLabel(match.name);
		name.setFont(FontManager.getRunescapeSmallFont());
		name.setForeground(ColorScheme.TEXT_COLOR);

		JLabel quantity = new JLabel(NUMBERS.format(match.quantity) + " total");
		quantity.setFont(FontManager.getRunescapeSmallFont());
		quantity.setForeground(ColorScheme.GRAND_EXCHANGE_PRICE);

		JPanel text = new JPanel();
		text.setLayout(new BoxLayout(text, BoxLayout.Y_AXIS));
		text.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		text.add(name);
		text.add(quantity);

		for (Map.Entry<String, Long> owner : ownersOf(match.itemId).entrySet())
		{
			GroupMember member = groupState.getMember(owner.getKey());

			JLabel who = ServerText.label(owner.getKey());
			who.setFont(FontManager.getRunescapeSmallFont());
			who.setForeground(member != null ? member.getColour() : ColorScheme.LIGHT_GRAY_COLOR);

			JLabel count = new JLabel(NUMBERS.format(owner.getValue()));
			count.setFont(FontManager.getRunescapeSmallFont());
			count.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			count.setHorizontalAlignment(SwingConstants.RIGHT);

			JPanel line = new JPanel(new GridLayout(1, 2));
			line.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			line.add(who);
			line.add(count);
			text.add(line);
		}

		row.add(icon, BorderLayout.WEST);
		row.add(text, BorderLayout.CENTER);
		return row;
	}

	private Map<String, Long> ownersOf(int itemId)
	{
		java.util.LinkedHashMap<String, Long> owners = new java.util.LinkedHashMap<>();
		for (GroupMember member : groupState.getMembers())
		{
			long quantity = 0;
			quantity += count(member, itemId);
			if (quantity > 0)
			{
				owners.put(member.getName(), quantity);
			}
		}

		GroupMember shared = groupState.getSharedBank();
		if (shared != null)
		{
			long quantity = 0;
			for (com.groupironmencompanion.data.ItemStack item : shared.getBank())
			{
				if (item.getId() == itemId)
				{
					quantity += item.getQuantity();
				}
			}
			if (quantity > 0)
			{
				owners.put("Group Storage", quantity);
			}
		}
		return owners;
	}

	private static long count(GroupMember member, int itemId)
	{
		long total = 0;
		total += countIn(member.getBank(), itemId);
		total += countIn(member.getInventory(), itemId);
		total += countIn(member.getEquipment(), itemId);
		total += countIn(member.getRunePouch(), itemId);
		total += countIn(member.getSeedVault(), itemId);
		total += countIn(member.getQuiver(), itemId);
		return total;
	}

	private static long countIn(List<com.groupironmencompanion.data.ItemStack> items, int itemId)
	{
		long total = 0;
		for (com.groupironmencompanion.data.ItemStack item : items)
		{
			if (item.getId() == itemId)
			{
				total += item.getQuantity();
			}
		}
		return total;
	}

	private void show(List<Result> matches, int total)
	{
		results.removeAll();
		for (Result match : matches)
		{
			results.add(buildRow(match));
		}

		if (matches.isEmpty())
		{
			emptyLabel.setText("Nothing in the group matches");
		}
		else if (total > matches.size())
		{
			emptyLabel.setText("Showing " + matches.size() + " of " + total + " matches");
		}
		else
		{
			emptyLabel.setText(" ");
		}

		revalidate();
		repaint();
	}

	private static final class Result
	{
		private final int itemId;
		private final String name;
		private final long quantity;

		Result(int itemId, String name, long quantity)
		{
			this.itemId = itemId;
			this.name = name;
			this.quantity = quantity;
		}
	}
}

package com.groupironmencompanion.ui;

import com.groupironmencompanion.activity.Activity;
import com.groupironmencompanion.data.GroupMember;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.time.Instant;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.ThinProgressBar;

/**
 * One group member's live vitals: hitpoints, prayer, run energy, world, how long ago their
 * client last reported, and optionally a best guess at what they are doing.
 */
class MemberCard extends JPanel
{
	private static final Color HP_COLOUR = new Color(199, 51, 51);
	private static final Color PRAYER_COLOUR = new Color(87, 160, 230);
	private static final Color RUN_COLOUR = new Color(224, 190, 62);
	private static final Color OFFLINE_COLOUR = new Color(120, 120, 120);

	private final JLabel nameLabel = ServerText.plain(new JLabel());
	private final JLabel statusLabel = ServerText.plain(new JLabel());
	private final JLabel activityLabel = ServerText.plain(new JLabel());

	private final ThinProgressBar hitpoints = new ThinProgressBar();
	private final ThinProgressBar prayer = new ThinProgressBar();
	private final ThinProgressBar run = new ThinProgressBar();

	private final JLabel hitpointsText = new JLabel();
	private final JLabel prayerText = new JLabel();
	private final JLabel runText = new JLabel();

	MemberCard()
	{
		setLayout(new BorderLayout(0, 2));
		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			BorderFactory.createEmptyBorder(6, 6, 6, 6)));

		nameLabel.setFont(FontManager.getRunescapeBoldFont());

		statusLabel.setFont(FontManager.getRunescapeSmallFont());
		statusLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		statusLabel.setHorizontalAlignment(SwingConstants.RIGHT);

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.add(nameLabel, BorderLayout.WEST);
		header.add(statusLabel, BorderLayout.EAST);

		JPanel bars = new JPanel();
		bars.setLayout(new BoxLayout(bars, BoxLayout.Y_AXIS));
		bars.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		bars.add(bar("HP", hitpoints, hitpointsText, HP_COLOUR));
		bars.add(bar("Pray", prayer, prayerText, PRAYER_COLOUR));
		bars.add(bar("Run", run, runText, RUN_COLOUR));

		activityLabel.setFont(FontManager.getRunescapeSmallFont());
		activityLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		activityLabel.setToolTipText("A best guess from the experience, position, items, quests and "
			+ "interactions their tracker shares. It can be wrong.");

		add(header, BorderLayout.NORTH);
		add(bars, BorderLayout.CENTER);
		add(activityLabel, BorderLayout.SOUTH);
	}

	private JPanel bar(String caption, ThinProgressBar progress, JLabel value, Color colour)
	{
		progress.setForeground(colour);
		progress.setMaximumValue(100);
		progress.setValue(0);
		progress.setPreferredSize(new Dimension(0, 5));

		JLabel captionLabel = new JLabel(caption);
		captionLabel.setFont(FontManager.getRunescapeSmallFont());
		captionLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		value.setFont(FontManager.getRunescapeSmallFont());
		value.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		value.setHorizontalAlignment(SwingConstants.RIGHT);

		JPanel labels = new JPanel(new GridLayout(1, 2));
		labels.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		labels.add(captionLabel);
		labels.add(value);

		JPanel wrapper = new JPanel(new BorderLayout());
		wrapper.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		wrapper.setBorder(BorderFactory.createEmptyBorder(2, 0, 0, 0));
		wrapper.add(labels, BorderLayout.NORTH);
		wrapper.add(progress, BorderLayout.SOUTH);
		return wrapper;
	}

	/**
	 * @param activity what they seem to be doing, or null to hide the line
	 * @param now the time to count an idle spell to
	 */
	void update(GroupMember member, boolean online, Activity activity, Instant now, boolean isYou)
	{
		nameLabel.setText(isYou ? member.getName() + " (you)" : member.getName());
		nameLabel.setForeground(online ? member.getColour() : OFFLINE_COLOUR);

		if (online && member.hasStats())
		{
			statusLabel.setText("w" + member.getWorld());
		}
		else
		{
			statusLabel.setText(member.getLastSeenText());
		}

		if (member.hasStats())
		{
			setBar(hitpoints, hitpointsText, member.getHitpoints(), member.getMaxHitpoints(), online, false);
			setBar(prayer, prayerText, member.getPrayer(), member.getMaxPrayer(), online, false);
			setBar(run, runText, member.getRunEnergyPercent(), 100, online, true);
		}
		else
		{
			setBar(hitpoints, hitpointsText, -1, -1, online, false);
			setBar(prayer, prayerText, -1, -1, online, false);
			setBar(run, runText, -1, -1, online, true);
		}

		if (activity != null)
		{
			activityLabel.setText(activity.describe(now, true));
			activityLabel.setForeground(online ? ColorScheme.LIGHT_GRAY_COLOR : OFFLINE_COLOUR);
			activityLabel.setVisible(true);
		}
		else
		{
			activityLabel.setVisible(false);
		}
	}

	private void setBar(ThinProgressBar bar, JLabel text, int current, int max, boolean online, boolean asPercent)
	{
		if (current < 0 || max <= 0)
		{
			bar.setValue(0);
			text.setText("-");
			return;
		}

		bar.setMaximumValue(max);
		bar.setValue(online ? current : 0);
		text.setText(asPercent ? current + "%" : current + "/" + max);
	}
}

package com.groupironmencompanion.ui;

import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupState;
import com.groupironmencompanion.data.Quests;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.ui.components.ThinProgressBar;

/**
 * Quest progress for the group: how many each member has finished, and a search that shows
 * where everyone stands on a particular quest.
 */
class QuestsView extends JPanel
{
	private static final int MAX_RESULTS = 25;

	private static final Color FINISHED = new Color(0x55, 0xC5, 0x5A);
	private static final Color IN_PROGRESS = new Color(0xE6, 0x96, 0x1E);
	private static final Color NOT_STARTED = new Color(0x9E, 0x50, 0x50);
	private static final Color UNKNOWN = new Color(0x77, 0x77, 0x77);

	private final GroupState groupState;

	private final JPanel summary = new JPanel();
	private final IconTextField search = new IconTextField();
	private final JPanel results = new JPanel();
	private final JLabel hint = new JLabel();

	QuestsView(GroupState groupState)
	{
		this.groupState = groupState;

		setLayout(new BorderLayout(0, 6));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		summary.setLayout(new BoxLayout(summary, BoxLayout.Y_AXIS));
		summary.setBackground(ColorScheme.DARK_GRAY_COLOR);

		search.setIcon(IconTextField.Icon.SEARCH);
		search.setPreferredSize(new Dimension(0, 26));
		search.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		search.setHoverBackgroundColor(ColorScheme.DARK_GRAY_HOVER_COLOR);
		search.addActionListener(e -> refreshResults());
		search.addKeyListener(new java.awt.event.KeyAdapter()
		{
			@Override
			public void keyReleased(java.awt.event.KeyEvent e)
			{
				refreshResults();
			}
		});

		results.setLayout(new BoxLayout(results, BoxLayout.Y_AXIS));
		results.setBackground(ColorScheme.DARK_GRAY_COLOR);

		hint.setFont(FontManager.getRunescapeSmallFont());
		hint.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		hint.setHorizontalAlignment(SwingConstants.CENTER);
		hint.setBorder(BorderFactory.createEmptyBorder(8, 0, 0, 0));

		JPanel lower = new JPanel(new BorderLayout(0, 4));
		lower.setBackground(ColorScheme.DARK_GRAY_COLOR);
		lower.add(search, BorderLayout.NORTH);
		lower.add(results, BorderLayout.CENTER);
		lower.add(hint, BorderLayout.SOUTH);

		add(summary, BorderLayout.NORTH);
		add(lower, BorderLayout.CENTER);
	}

	void refresh()
	{
		summary.removeAll();

		List<GroupMember> members = groupState.getMembers();
		if (members.isEmpty())
		{
			JLabel empty = new JLabel("No group data yet");
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setHorizontalAlignment(SwingConstants.CENTER);
			summary.add(empty);
		}
		else
		{
			for (GroupMember member : members)
			{
				summary.add(summaryRow(member));
			}
		}

		refreshResults();
		revalidate();
		repaint();
	}

	private JPanel summaryRow(GroupMember member)
	{
		Quests.Progress progress = Quests.progressOf(member);

		JPanel panel = new JPanel(new BorderLayout(0, 2));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			BorderFactory.createEmptyBorder(5, 6, 5, 6)));

		JLabel name = ServerText.label(groupState.isLocalPlayer(member) ? member.getName() + " (you)" : member.getName());
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(member.getColour());

		JLabel count = new JLabel(progress.isKnown()
			? progress.getFinished() + " / " + progress.getTotal()
			: "not reported");
		count.setFont(FontManager.getRunescapeSmallFont());
		count.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		count.setHorizontalAlignment(SwingConstants.RIGHT);

		JPanel header = new JPanel(new BorderLayout());
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.add(name, BorderLayout.WEST);
		header.add(count, BorderLayout.EAST);
		panel.add(header, BorderLayout.NORTH);

		if (progress.isKnown() && progress.getTotal() > 0)
		{
			ThinProgressBar bar = new ThinProgressBar();
			bar.setForeground(FINISHED);
			bar.setMaximumValue(progress.getTotal());
			bar.setValue(progress.getFinished());
			bar.setPreferredSize(new Dimension(0, 5));
			panel.add(bar, BorderLayout.CENTER);

			if (progress.getInProgress() > 0)
			{
				JLabel started = new JLabel(progress.getInProgress() + " in progress");
				started.setFont(FontManager.getRunescapeSmallFont());
				started.setForeground(IN_PROGRESS);
				panel.add(started, BorderLayout.SOUTH);
			}
		}

		return panel;
	}

	private void refreshResults()
	{
		results.removeAll();

		String query = search.getText().trim();
		if (query.length() < 2)
		{
			hint.setText("Search a quest to compare the group");
			revalidate();
			repaint();
			return;
		}

		List<Quest> matches = Quests.search(query);
		List<GroupMember> members = groupState.getMembers();

		int shown = 0;
		for (Quest quest : matches)
		{
			if (shown >= MAX_RESULTS)
			{
				break;
			}
			results.add(questRow(quest, members));
			shown++;
		}

		if (matches.isEmpty())
		{
			hint.setText("No quest matches");
		}
		else if (matches.size() > shown)
		{
			hint.setText("Showing " + shown + " of " + matches.size() + " quests");
		}
		else
		{
			hint.setText(" ");
		}

		revalidate();
		repaint();
	}

	private JPanel questRow(Quest quest, List<GroupMember> members)
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			BorderFactory.createEmptyBorder(5, 6, 5, 6)));

		JLabel title = new JLabel(quest.getName());
		title.setFont(FontManager.getRunescapeSmallFont());
		title.setForeground(ColorScheme.TEXT_COLOR);
		panel.add(title);

		for (GroupMember member : members)
		{
			QuestState state = Quests.stateOf(member, quest);

			JLabel who = ServerText.label(member.getName());
			who.setFont(FontManager.getRunescapeSmallFont());
			who.setForeground(member.getColour());

			JLabel status = new JLabel(describe(state));
			status.setFont(FontManager.getRunescapeSmallFont());
			status.setForeground(colourOf(state));
			status.setHorizontalAlignment(SwingConstants.RIGHT);

			JPanel line = new JPanel(new GridLayout(1, 2));
			line.setBackground(ColorScheme.DARKER_GRAY_COLOR);
			line.add(who);
			line.add(status);
			panel.add(line);
		}

		return panel;
	}

	private static String describe(QuestState state)
	{
		if (state == null)
		{
			return "unknown";
		}
		switch (state)
		{
			case FINISHED:
				return "done";
			case IN_PROGRESS:
				return "started";
			default:
				return "not started";
		}
	}

	private static Color colourOf(QuestState state)
	{
		if (state == null)
		{
			return UNKNOWN;
		}
		switch (state)
		{
			case FINISHED:
				return FINISHED;
			case IN_PROGRESS:
				return IN_PROGRESS;
			default:
				return NOT_STARTED;
		}
	}
}

package com.groupironmencompanion.ui;

import javax.swing.JComponent;
import javax.swing.JLabel;

/**
 * Labels for text that comes from the group's server: member names, NPC names, activity lines.
 * <p>
 * Swing renders label text starting with {@code <html>} as HTML, and that HTML can load images
 * from any URL. Member and NPC names are whatever was uploaded with the group's token, so they
 * get plain text only.
 */
final class ServerText
{
	private ServerText()
	{
	}

	static JLabel label(String text)
	{
		// The flag has to be on before the text goes in, or the HTML is already parsed.
		JLabel label = plain(new JLabel());
		label.setText(text);
		return label;
	}

	static <T extends JComponent> T plain(T component)
	{
		component.putClientProperty("html.disable", Boolean.TRUE);
		return component;
	}
}

package com.groupironmencompanion.ui;

import com.groupironmencompanion.data.GroupMember;
import com.groupironmencompanion.data.GroupSkill;
import com.groupironmencompanion.data.GroupState;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.text.NumberFormat;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.DefaultComboBoxModel;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import net.runelite.api.Experience;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Compares the group's skills: total level and experience by default, or one chosen skill
 * with each member's level, experience and experience to the next level.
 */
class SkillsView extends JPanel
{
	private static final String TOTAL = "Total";
	private static final NumberFormat NUMBERS = NumberFormat.getIntegerInstance(Locale.ENGLISH);

	private final GroupState groupState;

	private final JComboBox<String> skillPicker = new JComboBox<>();
	private final JPanel rows = new JPanel();

	SkillsView(GroupState groupState)
	{
		this.groupState = groupState;

		setLayout(new BorderLayout(0, 6));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		DefaultComboBoxModel<String> model = new DefaultComboBoxModel<>();
		model.addElement(TOTAL);
		for (GroupSkill skill : GroupSkill.VALUES)
		{
			model.addElement(skill.getDisplayName());
		}
		skillPicker.setModel(model);
		skillPicker.setPreferredSize(new Dimension(0, 24));
		skillPicker.setFocusable(false);
		skillPicker.setForeground(ColorScheme.TEXT_COLOR);
		skillPicker.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		skillPicker.addActionListener(e -> refresh());

		rows.setLayout(new BoxLayout(rows, BoxLayout.Y_AXIS));
		rows.setBackground(ColorScheme.DARK_GRAY_COLOR);

		add(skillPicker, BorderLayout.NORTH);
		add(rows, BorderLayout.CENTER);
	}

	void refresh()
	{
		rows.removeAll();

		String selected = (String) skillPicker.getSelectedItem();
		GroupSkill skill = null;
		if (selected != null && !TOTAL.equals(selected))
		{
			for (GroupSkill candidate : GroupSkill.VALUES)
			{
				if (candidate.getDisplayName().equals(selected))
				{
					skill = candidate;
					break;
				}
			}
		}

		// getMembers() is shared and immutable; this view reorders it, so copy first.
		List<GroupMember> members = new ArrayList<>(groupState.getMembers());
		if (skill == null)
		{
			members.sort(Comparator.comparingInt(GroupMember::getTotalLevel).reversed());
		}
		else
		{
			final GroupSkill sortBy = skill;
			members.sort(Comparator.comparingInt((GroupMember m) -> m.getXp(sortBy)).reversed());
		}

		for (GroupMember member : members)
		{
			rows.add(skill == null ? totalRow(member) : skillRow(member, skill));
		}

		if (members.isEmpty())
		{
			JLabel empty = new JLabel("No group data yet");
			empty.setFont(FontManager.getRunescapeSmallFont());
			empty.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
			empty.setHorizontalAlignment(SwingConstants.CENTER);
			rows.add(empty);
		}

		revalidate();
		repaint();
	}

	private JPanel totalRow(GroupMember member)
	{
		JPanel panel = row(member);
		int totalLevel = member.getTotalLevel();
		long totalXp = member.getTotalXp();

		panel.add(line("Total level", totalLevel < 0 ? "-" : NUMBERS.format(totalLevel)));
		panel.add(line("Total xp", totalXp < 0 ? "-" : NUMBERS.format(totalXp)));
		return panel;
	}

	private JPanel skillRow(GroupMember member, GroupSkill skill)
	{
		JPanel panel = row(member);

		int level = member.getLevel(skill);
		int xp = member.getXp(skill);
		int toNext = member.getXpToNextLevel(skill);

		if (level < 0)
		{
			panel.add(line("Level", "not reported yet"));
			return panel;
		}

		panel.add(line("Level", Integer.toString(level)));
		panel.add(line("Experience", NUMBERS.format(xp)));
		panel.add(line("To level " + (level + 1),
			level >= Experience.MAX_VIRT_LEVEL ? "maxed" : NUMBERS.format(toNext)));
		return panel;
	}

	private JPanel row(GroupMember member)
	{
		JPanel panel = new JPanel();
		panel.setLayout(new BoxLayout(panel, BoxLayout.Y_AXIS));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.setBorder(BorderFactory.createCompoundBorder(
			BorderFactory.createMatteBorder(0, 0, 1, 0, ColorScheme.DARK_GRAY_COLOR),
			BorderFactory.createEmptyBorder(5, 6, 5, 6)));

		JLabel name = ServerText.label(groupState.isLocalPlayer(member) ? member.getName() + " (you)" : member.getName());
		name.setFont(FontManager.getRunescapeBoldFont());
		name.setForeground(member.getColour());
		panel.add(name);

		return panel;
	}

	private JPanel line(String caption, String value)
	{
		JLabel captionLabel = new JLabel(caption);
		captionLabel.setFont(FontManager.getRunescapeSmallFont());
		captionLabel.setForeground(ColorScheme.LIGHT_GRAY_COLOR);

		JLabel valueLabel = new JLabel(value);
		valueLabel.setFont(FontManager.getRunescapeSmallFont());
		valueLabel.setForeground(ColorScheme.TEXT_COLOR);
		valueLabel.setHorizontalAlignment(SwingConstants.RIGHT);

		JPanel panel = new JPanel(new GridLayout(1, 2));
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		panel.add(captionLabel);
		panel.add(valueLabel);
		return panel;
	}
}

