package com.groupironmencompanion.upload;

import com.groupironmencompanion.GroupIronmenCompanionConfig;
import com.groupironmencompanion.TrackerDetector;
import com.groupironmencompanion.api.GroupApi;
import com.groupironmencompanion.data.GroupSkill;
import java.util.Arrays;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Player;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldType;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.game.ItemManager;

/**
 * The standalone data source, used only when the official Group Ironmen Tracker plugin is
 * not running. It gathers the same fields in the same wire format as the tracker, so a group
 * can mix and match the two plugins freely and the website keeps working either way.
 * <p>
 * Nothing here runs unless the user has entered their own group credentials and the tracker
 * is absent, and a single config switch turns it off entirely. Collection log progress is
 * deliberately not collected; the tracker remains the way to populate that.
 */
@Slf4j
@Singleton
public class GroupUploader
{
	/** Interface group of the group storage loading screen, used to detect a committed save. */
	private static final int GROUP_STORAGE_LOADER = 293;

	/**
	 * Least time between quest scans. A scan asks the game for the state of every quest, a
	 * script run each, so it is not repeated on every tick that vars change. The official
	 * tracker scans on the same interval.
	 */
	private static final long QUEST_SCAN_MILLIS = 60_000;

	/** How long to wait after a failed check or post before trying again. */
	private static final long BACKOFF_MILLIS = 10_000;

	private static final int INVENTORY_SIZE = 28;
	private static final int EQUIPMENT_SIZE = 14;

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private GroupApi api;

	@Inject
	private GroupIronmenCompanionConfig config;

	@Inject
	private TrackerDetector trackerDetector;

	/** Fields whose value has changed since the last successful post. */
	private final Map<String, Object> pending = new LinkedHashMap<>();

	/**
	 * The last value successfully sent for each field, used to suppress no-op posts.
	 * Written from the client thread by {@link #stage} and from the polling thread by
	 * {@link #restore}, so it has to be concurrent.
	 */
	private final Map<String, String> lastSent = new ConcurrentHashMap<>();

	private int[] sortedQuestIds;
	private boolean questsChanged = true;
	private long lastQuestScan;
	private int[] pendingSharedBank;
	// Written by reset on the client thread, read by flush on the polling thread.
	private volatile boolean membershipConfirmed;
	private volatile String membershipCheckedFor;
	private volatile long backoffUntil;

	@Getter
	private volatile boolean active;

	@Getter
	private volatile String status = "Idle";

	/** Client thread only: it clears the group storage snapshot that onGameTick commits. */
	public void reset()
	{
		synchronized (pending)
		{
			pending.clear();
		}
		lastSent.clear();
		pendingSharedBank = null;
		// Scan quests on the next tick, such as the first after a login, then at most once a minute.
		questsChanged = true;
		lastQuestScan = 0;
		membershipConfirmed = false;
		membershipCheckedFor = null;
		backoffUntil = 0;
		active = false;
		status = "Idle";
	}

	/**
	 * Whether this plugin should be the one uploading. False whenever the official tracker
	 * plugin is running, so the two never post competing snapshots.
	 */
	public boolean shouldUpload()
	{
		return config.uploadMode() == GroupIronmenCompanionConfig.UploadMode.AUTO
			&& !trackerDetector.isTrackerActive()
			&& api.hasCredentials();
	}

	// ------------------------------------------------------------------
	// Collection, all called on the client thread
	// ------------------------------------------------------------------

	public void onSkillsChanged()
	{
		if (!collectable())
		{
			return;
		}
		int[] xp = new int[GroupSkill.VALUES.length];
		for (GroupSkill groupSkill : GroupSkill.VALUES)
		{
			xp[groupSkill.ordinal()] = client.getSkillExperience(groupSkill.getSkill());
		}
		stage("skills", xp);
	}

	public void onVitalsChanged()
	{
		if (!collectable())
		{
			return;
		}
		stage("stats", new int[]{
			client.getBoostedSkillLevel(Skill.HITPOINTS),
			client.getRealSkillLevel(Skill.HITPOINTS),
			client.getBoostedSkillLevel(Skill.PRAYER),
			client.getRealSkillLevel(Skill.PRAYER),
			client.getEnergy(),
			100,
			client.getWorld()
		});
	}

	public void onPositionChanged()
	{
		if (!collectable())
		{
			return;
		}
		Player local = client.getLocalPlayer();
		WorldPoint point = realLocation(local);
		if (point == null)
		{
			return;
		}
		stage("coordinates", UploadPayloads.coordinates(point, isOnBoat(local)));
	}

	/**
	 * Stages skills, inventory and equipment as they are now. Used after a login or hop: the
	 * reset that follows a character change throws away whatever the login burst staged, and
	 * these fields would otherwise stay missing until they next change.
	 */
	public void snapshot()
	{
		onSkillsChanged();
		onItemContainerChanged(InventoryID.INV, client.getItemContainer(InventoryID.INV));
		onItemContainerChanged(InventoryID.WORN, client.getItemContainer(InventoryID.WORN));
	}

	public void onItemContainerChanged(int containerId, @Nullable ItemContainer container)
	{
		if (!collectable() || container == null)
		{
			return;
		}

		if (containerId == InventoryID.BANK)
		{
			stage("bank", flatten(container, -1));
		}
		else if (containerId == InventoryID.SEED_VAULT)
		{
			stage("seed_vault", flatten(container, -1));
		}
		else if (containerId == InventoryID.INV)
		{
			stage("inventory", flatten(container, INVENTORY_SIZE));
		}
		else if (containerId == InventoryID.WORN)
		{
			stage("equipment", flatten(container, EQUIPMENT_SIZE));
		}
		else if (containerId == InventoryID.INV_GROUP_TEMP)
		{
			// The shared bank is edited locally and only written to the server when the
			// player confirms; hold the snapshot until the save is observed.
			pendingSharedBank = flatten(container, -1);
		}
	}

	/**
	 * Called each tick. Commits a buffered shared bank snapshot once the group storage
	 * interface reports that it is saving, matching the official tracker's behaviour.
	 */
	public void onGameTick()
	{
		if (!collectable())
		{
			return;
		}

		if (pendingSharedBank != null)
		{
			net.runelite.api.widgets.Widget loader = client.getWidget(GROUP_STORAGE_LOADER, 1);
			if (loader != null && "saving...".equalsIgnoreCase(loader.getText()))
			{
				stage("shared_bank", pendingSharedBank);
				pendingSharedBank = null;
			}
		}

		stageRunePouch();
		stageInteracting();
		stageQuests();
	}

	/** Notes that quest progress may have changed. The scan itself runs from {@link #onGameTick}. */
	public void onQuestsChanged()
	{
		questsChanged = true;
	}

	private void stageQuests()
	{
		long now = System.currentTimeMillis();
		if (!questsChanged || (lastQuestScan != 0 && now - lastQuestScan < QUEST_SCAN_MILLIS))
		{
			return;
		}
		questsChanged = false;
		lastQuestScan = now;

		if (sortedQuestIds == null)
		{
			sortedQuestIds = Arrays.stream(Quest.values())
				.map(Quest::getId)
				.sorted()
				.mapToInt(Integer::intValue)
				.toArray();
		}

		Map<Integer, QuestState> states = new HashMap<>();
		for (Quest quest : Quest.values())
		{
			states.put(quest.getId(), quest.getState(client));
		}

		int[] result = new int[sortedQuestIds.length];
		for (int i = 0; i < sortedQuestIds.length; i++)
		{
			QuestState state = states.get(sortedQuestIds[i]);
			result[i] = state == null ? 0 : state.ordinal();
		}
		stage("quests", result);
	}

	public void onDiaryChanged()
	{
		if (!collectable())
		{
			return;
		}
		int[] values = new int[DiaryVars.VARPS.length + DiaryVars.VARBITS.length];
		for (int i = 0; i < DiaryVars.VARPS.length; i++)
		{
			values[i] = client.getVarpValue(DiaryVars.VARPS[i]);
		}
		for (int i = 0; i < DiaryVars.VARBITS.length; i++)
		{
			values[i + DiaryVars.VARPS.length] = client.getVarbitValue(DiaryVars.VARBITS[i]);
		}
		stage("diary_vars", values);
	}

	private void stageRunePouch()
	{
		EnumComposition runes = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runes == null)
		{
			return;
		}
		int[] types = {
			VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2,
			VarbitID.RUNE_POUCH_TYPE_3, VarbitID.RUNE_POUCH_TYPE_4
		};
		int[] quantities = {
			VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2,
			VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4
		};

		int[] flat = new int[types.length * 2];
		for (int i = 0; i < types.length; i++)
		{
			int runeType = client.getVarbitValue(types[i]);
			flat[i * 2] = runes.getIntValue(runeType);
			flat[i * 2 + 1] = client.getVarbitValue(quantities[i]);
		}
		stage("rune_pouch", flat);
	}

	private void stageInteracting()
	{
		Player local = client.getLocalPlayer();
		Actor target = local == null ? null : local.getInteracting();
		if (target == null || target.getName() == null)
		{
			return;
		}

		WorldPoint point = realLocation(target);
		UploadPayloads.Coordinates location = point == null
			? new UploadPayloads.Coordinates(0, 0, 0)
			: new UploadPayloads.Coordinates(point.getX(), point.getY(), point.getPlane());

		// Interactions are re-sent every tick while they last so viewers can tell a live
		// fight from a stale one, so this bypasses the change filter.
		synchronized (pending)
		{
			pending.put("interacting", new UploadPayloads.Interacting(
				target.getName(), target.getHealthScale(), target.getHealthRatio(), location));
		}
	}

	// ------------------------------------------------------------------
	// Sending, called off the client thread
	// ------------------------------------------------------------------

	/**
	 * Drops what is staged and what was last sent, and nothing else. Safe from the polling
	 * thread: the rest of {@link #reset} is client thread state, such as a group storage
	 * save in progress, which must not be cleared from under it every poll.
	 */
	private void discardStaged()
	{
		synchronized (pending)
		{
			pending.clear();
		}
		lastSent.clear();
		membershipConfirmed = false;
		active = false;
	}

	/** Posts everything staged since the last call. Must not run on the client thread. */
	public void flush(String playerName)
	{
		if (!shouldUpload())
		{
			// Nothing new is staged while the tracker uploads, but what was staged before it
			// took over is stale, and the tracker may since have posted values that lastSent
			// would wrongly suppress. Start clean whenever this plugin takes over again.
			discardStaged();
			return;
		}
		if (playerName == null)
		{
			active = false;
			return;
		}

		// Timed rather than counted in flushes, which happen once per refresh interval, so
		// the wait no longer stretches from seconds to minutes as that interval grows.
		if (System.currentTimeMillis() < backoffUntil)
		{
			return;
		}

		if (!membershipConfirmed || !playerName.equals(membershipCheckedFor))
		{
			Boolean member;
			try
			{
				member = api.isPlayerInGroup(playerName);
			}
			catch (GroupApi.NotAuthorisedException e)
			{
				status = "The server rejected the group token";
				active = false;
				backOff();
				return;
			}
			if (member == null)
			{
				status = "Could not reach the server, retrying shortly";
				active = false;
				backOff();
				return;
			}
			if (!member)
			{
				status = "This character is not a member of the configured group";
				active = false;
				backOff();
				return;
			}
			membershipConfirmed = true;
			membershipCheckedFor = playerName;
		}

		Map<String, Object> payload;
		synchronized (pending)
		{
			if (pending.isEmpty())
			{
				active = true;
				return;
			}
			payload = new LinkedHashMap<>(pending);
			pending.clear();
		}
		payload.put("name", playerName);

		try
		{
			if (api.updateGroupMember(payload))
			{
				active = true;
				status = "Sharing your data (the official tracker plugin is not running)";
			}
			else
			{
				// Put the fields back so nothing is lost, without clobbering newer values.
				restore(payload);
				backOff();
			}
		}
		catch (GroupApi.NotAuthorisedException e)
		{
			membershipConfirmed = false;
			status = "The server rejected the group token";
			active = false;
			backOff();
		}
	}

	private void backOff()
	{
		backoffUntil = System.currentTimeMillis() + BACKOFF_MILLIS;
	}

	private void restore(Map<String, Object> payload)
	{
		payload.remove("name");
		synchronized (pending)
		{
			for (Map.Entry<String, Object> entry : payload.entrySet())
			{
				pending.putIfAbsent(entry.getKey(), entry.getValue());
			}
		}
		for (String key : payload.keySet())
		{
			lastSent.remove(key);
		}
	}

	// ------------------------------------------------------------------
	// Helpers
	// ------------------------------------------------------------------

	/** True while the actor stands on a boat, which has a world view of its own. */
	private static boolean isOnBoat(Actor actor)
	{
		WorldView view = actor.getWorldView();
		return view != null && !view.isTopLevel();
	}

	/**
	 * Where an actor is in the real world.
	 * <p>
	 * A boat is its own world view, built from a template somewhere else in the world, so
	 * converting a position on deck gives a tile nowhere near the sea. While aboard, the
	 * boat's own position in the top-level world is the real one. This is the same
	 * conversion the official tracker plugin makes.
	 */
	@Nullable
	private WorldPoint realLocation(Actor actor)
	{
		if (!isOnBoat(actor))
		{
			return WorldPoint.fromLocalInstance(client, actor.getLocalLocation());
		}
		WorldEntity boat = client.getTopLevelWorldView().worldEntities().byIndex(actor.getWorldView().getId());
		return boat == null ? null : WorldPoint.fromLocalInstance(client, boat.getLocalLocation());
	}

	private boolean collectable()
	{
		if (!shouldUpload() || client.getGameState() != GameState.LOGGED_IN)
		{
			return false;
		}
		Player local = client.getLocalPlayer();
		if (local == null || local.getName() == null)
		{
			return false;
		}
		return !isBadWorld();
	}

	/** Beta and tournament worlds carry throwaway data that would corrupt the group's view. */
	private boolean isBadWorld()
	{
		for (WorldType type : client.getWorldType())
		{
			if (type == WorldType.SEASONAL
				|| type == WorldType.DEADMAN
				|| type == WorldType.TOURNAMENT_WORLD
				|| type == WorldType.PVP_ARENA
				|| type == WorldType.BETA_WORLD
				|| type == WorldType.QUEST_SPEEDRUNNING)
			{
				return true;
			}
		}
		return false;
	}

	private void stage(String field, int[] value)
	{
		String fingerprint = Arrays.toString(value);
		if (fingerprint.equals(lastSent.get(field)))
		{
			return;
		}
		lastSent.put(field, fingerprint);
		synchronized (pending)
		{
			pending.put(field, value);
		}
	}

	/**
	 * Flattens a container into the server's [id, quantity, ...] encoding. When
	 * {@code fixedSize} is positive every slot is emitted in order, including empty ones,
	 * which is what the site needs to draw an inventory or equipment layout faithfully.
	 */
	private int[] flatten(ItemContainer container, int fixedSize)
	{
		if (fixedSize > 0)
		{
			int[] flat = new int[fixedSize * 2];
			for (int slot = 0; slot < fixedSize; slot++)
			{
				Item item = container.getItem(slot);
				if (isReal(item))
				{
					flat[slot * 2] = itemManager.canonicalize(item.getId());
					flat[slot * 2 + 1] = item.getQuantity();
				}
			}
			return flat;
		}

		Item[] contents = container.getItems();
		int count = 0;
		for (Item item : contents)
		{
			if (isReal(item))
			{
				count++;
			}
		}

		int[] flat = new int[count * 2];
		int index = 0;
		for (Item item : contents)
		{
			if (isReal(item))
			{
				flat[index++] = itemManager.canonicalize(item.getId());
				flat[index++] = item.getQuantity();
			}
		}
		return flat;
	}

	/** Placeholders are bank UI artefacts, not owned items, so they are never reported. */
	private boolean isReal(@Nullable Item item)
	{
		if (item == null || item.getId() < 0 || item.getQuantity() <= 0)
		{
			return false;
		}
		return itemManager.getItemComposition(item.getId()).getPlaceholderTemplateId() == -1;
	}
}

package com.groupironmencompanion.upload;

import net.runelite.api.coords.WorldPoint;

/**
 * Wire shapes for the fields the fallback uploader posts to
 * {@code /api/group/{group}/update-group-member}.
 * <p>
 * The server validates these with {@code deny_unknown_fields}, so these classes must carry
 * exactly the fields the server expects and nothing more.
 */
public final class UploadPayloads
{
	private UploadPayloads()
	{
	}

	/**
	 * The member's own position, sent as a flat {@code [x, y, plane, onBoat]}. The fourth
	 * value is the official tracker's Sailing flag, 1 while aboard a boat.
	 */
	static int[] coordinates(WorldPoint point, boolean onBoat)
	{
		return new int[]{point.getX(), point.getY(), point.getPlane(), onBoat ? 1 : 0};
	}

	public static class Coordinates
	{
		public int x;
		public int y;
		public int plane;

		public Coordinates(int x, int y, int plane)
		{
			this.x = x;
			this.y = y;
			this.plane = plane;
		}
	}

	public static class Interacting
	{
		public String name;
		public int scale;
		public int ratio;
		public Coordinates location;

		public Interacting(String name, int scale, int ratio, Coordinates location)
		{
			this.name = name;
			this.scale = scale;
			this.ratio = ratio;
			this.location = location;
		}
	}
}

package com.groupironmencompanion;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

/**
 * Enforces the promises the README makes about this plugin, so they cannot quietly regress.
 * <p>
 * The plugin's whole case for being publishable is that it is mechanically verifiable: it
 * adds no menu entries, never touches a game widget's state or geometry, uses no reflection,
 * and talks to exactly one configurable host. Each of those is a grep, so each is a test.
 */
public class ComplianceTest
{
	private static final Path SOURCE_ROOT = new File("src/main/java").toPath();

	/** A bare {@code client.} field access, not a package name and not {@code clientThread}. */
	private static final java.util.regex.Pattern BARE_CLIENT_ACCESS =
		java.util.regex.Pattern.compile("(?<![.\\w])client\\s*\\.");

	private static List<Path> sources() throws IOException
	{
		try (Stream<Path> paths = Files.walk(SOURCE_ROOT))
		{
			return paths.filter(p -> p.toString().endsWith(".java")).collect(Collectors.toList());
		}
	}

	/**
	 * Fails if any source file contains a banned token. Occurrences inside a {@code //} or
	 * {@code *} comment line are ignored so the rules can be discussed in documentation.
	 */
	private void assertAbsent(String reason, String... tokens) throws IOException
	{
		List<String> hits = new ArrayList<>();

		for (Path path : sources())
		{
			List<String> lines = Files.readAllLines(path, StandardCharsets.UTF_8);
			for (int i = 0; i < lines.size(); i++)
			{
				String line = lines.get(i);
				String trimmed = line.trim();
				if (trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*"))
				{
					continue;
				}
				for (String token : tokens)
				{
					if (line.contains(token))
					{
						hits.add(SOURCE_ROOT.relativize(path) + ":" + (i + 1) + "  " + trimmed);
					}
				}
			}
		}

		if (!hits.isEmpty())
		{
			fail(reason + "\n  " + String.join("\n  ", hits));
		}
	}

	@Test
	public void sourceTreeIsPresent() throws IOException
	{
		assertTrue("compliance tests must run from the project directory", Files.isDirectory(SOURCE_ROOT));
		assertTrue(sources().size() > 20);
	}

	@Test
	public void addsNoMenuEntries() throws IOException
	{
		// Jagex prohibit "any addition of new menu entries which cause actions to be sent to
		// the server". The plugin sidesteps the question entirely by creating none at all. The
		// one place it touches the menu, while the mouse is over the group bank window, only
		// removes the scene's options so nothing behind the window can be acted on.
		assertAbsent("This plugin must never create or invoke a menu entry.",
			"createMenuEntry", "addMenuEntry", "invokeMenuAction", "menuAction(", "setMenuOptions",
			"setOption(", "setTarget(", "setType(", "onClick(");
	}

	/**
	 * setMenuEntries is the only menu write allowed, and it can only remove entries since
	 * creating one is banned above. It must only happen over our own window though, or it
	 * would blank the game's menu everywhere. So there's exactly one call and it's gated.
	 */
	@Test
	public void theOnlyMenuWriteIsGatedOnTheWindow() throws IOException
	{
		List<String> sites = new ArrayList<>();
		for (Path path : sources())
		{
			List<String> lines = Files.readAllLines(path, StandardCharsets.UTF_8);
			for (int i = 0; i < lines.size(); i++)
			{
				if (lines.get(i).contains("setMenuEntries"))
				{
					String trimmed = lines.get(i).trim();
					if (trimmed.startsWith("//") || trimmed.startsWith("*"))
					{
						continue;
					}
					sites.add(SOURCE_ROOT.relativize(path) + ":" + (i + 1));

					// The guard must be visible in the same method, and the method is short.
					String window = String.join("\n",
						lines.subList(Math.max(0, i - 40), i));
					assertTrue("the menu write at " + SOURCE_ROOT.relativize(path) + ":" + (i + 1)
							+ " must be reached only while the cursor is over the plugin's window",
						window.contains("covers("));
					assertTrue("the menu write at " + SOURCE_ROOT.relativize(path) + ":" + (i + 1)
							+ " must leave an already-open menu alone",
						window.contains("isMenuOpen()"));
				}
			}
		}

		assertEquals("exactly one place may write the menu, so there is one place to audit",
			1, sites.size());
	}

	@Test
	public void neverModifiesAGameWidget() throws IOException
	{
		// Jagex prohibit unhiding interface components and moving or resizing click zones.
		// Widgets are read for their bounds only; nothing about them is ever written.
		assertAbsent("This plugin must never modify, hide, unhide, resize or reparent a game widget.",
			"setHidden", "createChild", "setOriginalX", "setOriginalY", "setOriginalWidth",
			"setOriginalHeight", "deleteAllChildren", "setOnOpListener", "setItemId",
			"setTextColor", "setSpriteId");
	}

	@Test
	public void neverWritesClientState() throws IOException
	{
		// Sprite overrides are how interface reskins work. The group bank reads them to match
		// a reskinned bank, and must never add, replace or remove one itself.
		assertAbsent("This plugin is read-only with respect to the game client.",
			"setVarbit", "setVarp", "runScript", "client.set", "getWidgetSpriteOverrides",
			"overrides.put", "overrides.remove", "overrides.clear", "getSpriteOverrides().put",
			"getSpriteOverrides().remove", "getSpriteOverrides().clear");
	}

	@Test
	public void drawsNothingOnTheMinimap() throws IOException
	{
		// Member positions on the minimap would make this a radar.
		assertAbsent("Group member data must never be drawn on the minimap.",
			"localToMinimap", "getMinimapLocation", "worldToMinimap");
	}

	/** Only scene presence draws in the scene, and it all lives in scene/, so there's one place to audit. */
	@Test
	public void sceneDrawingIsConfinedToTheScenePackage() throws IOException
	{
		String[] sceneTokens = {
			"LocalPoint", "Perspective.", "RuneLiteObject", "ABOVE_SCENE", "getCanvasTilePoly"
		};

		List<String> hits = new ArrayList<>();
		for (Path path : sources())
		{
			String name = path.toString().replace('\\', '/');
			if (name.contains("/scene/"))
			{
				continue;
			}

			List<String> lines = Files.readAllLines(path, StandardCharsets.UTF_8);
			for (int i = 0; i < lines.size(); i++)
			{
				String trimmed = lines.get(i).trim();
				if (trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*")
					|| trimmed.startsWith("import "))
				{
					continue;
				}
				for (String token : sceneTokens)
				{
					if (lines.get(i).contains(token))
					{
						hits.add(SOURCE_ROOT.relativize(path) + ":" + (i + 1) + "  " + trimmed);
					}
				}
			}
		}

		if (!hits.isEmpty())
		{
			fail("Only the scene package may draw in the game scene.\n  "
				+ String.join("\n  ", hits));
		}
	}

	/** The Wilderness and PvP cutout has no setting to turn it off, and this keeps it that way. */
	@Test
	public void scenePresenceIsHardwiredOffInPvp() throws IOException
	{
		Path gate = SOURCE_ROOT.resolve("com/groupironmencompanion/scene/ScenePresenceGate.java");
		assertTrue("the scene presence gate must exist", Files.isRegularFile(gate));

		String source = new String(Files.readAllBytes(gate), StandardCharsets.UTF_8);
		for (String required : new String[]{
			"WorldType.PVP", "WorldType.BOUNTY", "WorldType.HIGH_RISK", "WorldType.DEADMAN",
			"WorldType.LAST_MAN_STANDING", "WorldType.PVP_ARENA", "VarbitID.INSIDE_WILDERNESS"})
		{
			assertTrue("the gate must refuse to draw for " + required, source.contains(required));
		}

		Path config = SOURCE_ROOT.resolve("com/groupironmencompanion/GroupIronmenCompanionConfig.java");
		String configSource = new String(Files.readAllBytes(config), StandardCharsets.UTF_8)
			.toLowerCase(java.util.Locale.ROOT);
		for (String forbidden : new String[]{"wilderness", "pvp"})
		{
			if (configSource.contains("keyname = \"" + forbidden))
			{
				fail("There must be no setting that relaxes the PvP cutout: found a key named "
					+ forbidden);
			}
		}
	}

	@Test
	public void usesNoReflectionOrDynamicCode() throws IOException
	{
		// A plugin hub rule: reviewers must be able to read every line the plugin executes.
		assertAbsent("The plugin hub forbids reflection, native calls and runtime code loading.",
			"java.lang.reflect", "Class.forName", "setAccessible", "TypeToken", "MethodHandle",
			"ClassLoader", "defineClass", "Runtime.getRuntime", "ProcessBuilder", "System.load");
	}

	@Test
	public void touchesNoFilesystem() throws IOException
	{
		// The only resource read is bundled in the jar, via getResourceAsStream.
		assertAbsent("The plugin must not read or write the filesystem.",
			"new File(", "FileWriter", "FileOutputStream", "FileInputStream", "Paths.get", "Files.");
	}

	/**
	 * The Swing views and the mouse/keyboard handler all run on AWT threads, where calling
	 * into {@link net.runelite.api.Client} is illegal. Getting this wrong is silent: the call
	 * throws somewhere the exception is swallowed, and the feature simply does nothing. That
	 * is exactly what happened to the group bank hotkey and its Group tab, which called
	 * {@code client.getWidget} inline and so never got as far as opening the window.
	 * <p>
	 * These classes must reach the client only through {@code clientThread.invoke}.
	 */
	@Test
	public void awtFacingClassesNeverTouchTheClientDirectly() throws IOException
	{
		List<String> hits = new ArrayList<>();

		for (Path path : sources())
		{
			String name = path.toString().replace('\\', '/');
			boolean awtFacing = name.contains("/ui/") || name.endsWith("Input.java");
			if (!awtFacing)
			{
				continue;
			}

			List<String> lines = Files.readAllLines(path, StandardCharsets.UTF_8);
			for (int i = 0; i < lines.size(); i++)
			{
				String line = lines.get(i);
				String trimmed = line.trim();
				if (trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*")
					|| trimmed.startsWith("import "))
				{
					continue;
				}
				// A bare "client." field access. The lookbehind keeps package names such as
				// net.runelite.client.ui out of it, and "clientThread." has no dot after
				// "client" so it never matches.
				if (BARE_CLIENT_ACCESS.matcher(line).find())
				{
					hits.add(SOURCE_ROOT.relativize(path) + ":" + (i + 1) + "  " + trimmed);
				}
			}
		}

		if (!hits.isEmpty())
		{
			fail("AWT-facing classes must reach the client via clientThread.invoke, not directly.\n  "
				+ String.join("\n  ", hits));
		}
	}

	@Test
	public void talksToExactlyOneConfigurableHost() throws IOException
	{
		List<String> literals = new ArrayList<>();
		for (Path path : sources())
		{
			for (String line : Files.readAllLines(path, StandardCharsets.UTF_8))
			{
				String trimmed = line.trim();
				if (trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*"))
				{
					continue;
				}
				if (line.contains("http://") || line.contains("https://"))
				{
					literals.add(SOURCE_ROOT.relativize(path) + "  " + trimmed);
				}
			}
		}

		if (literals.size() != 1 || !literals.get(0).contains("https://groupiron.men"))
		{
			fail("The only URL in the plugin should be the default groupiron.men base URL, "
				+ "which the user can override. Found:\n  " + String.join("\n  ", literals));
		}
	}
}

