		int[] withSailing = Arrays.copyOf(gained(skills(SKILLS - 1), GroupSkill.WOODCUTTING, 25), SKILLS);
		withSailing[GroupSkill.SAILING.ordinal()] = 2_000_000;
		after(3, withSkills(withSailing));
