import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

/** Covers the delta merge and the shared member list handed to the render paths. */
public class GroupStateTest
{
	private static final int BIG_BONES = 532;

	private static MemberDto member(String name, int[] skills)
	{
		MemberDto dto = new MemberDto();
		dto.name = name;
		dto.skills = skills;
		return dto;
	}

	@Test
	public void sortsMembersAndExcludesTheSharedPseudoMember()
	{
		GroupState state = new GroupState();
		state.applyUpdate(new MemberDto[]{
			member("Zed", null), member("@SHARED", null), member("alice", null)});

		List<GroupMember> members = state.getMembers();
		assertEquals(2, members.size());
		assertEquals("alice", members.get(0).getName());
		assertEquals("Zed", members.get(1).getName());
		assertNotNull(state.getSharedBank());
	}

	private static MemberDto withBank(String name, int[] bank)
	{
		MemberDto dto = new MemberDto();
		dto.name = name;
		dto.bank = bank;
		return dto;
	}

	@Test
	public void groupStorageIsCountedOnceInTheGroupTotals()
	{
		// Group storage arrives as its own member, so a caller that added getSharedBank() on
		// top of the totals counted every shared stack twice.
		GroupState state = new GroupState();
		state.applyUpdate(new MemberDto[]{
			withBank("alice", new int[]{BIG_BONES, 2700}),
			withBank("@SHARED", new int[]{BIG_BONES, 1400})});

		assertEquals(Long.valueOf(4100), state.getGroupTotals().get(BIG_BONES));
	}

	@Test
	public void handsOutTheSameListUntilMembershipChanges()
	{
		// Four overlays call this every frame, so it must not rebuild per call.
		GroupState state = new GroupState();
		state.applyUpdate(new MemberDto[]{member("alice", null)});

		assertSame(state.getMembers(), state.getMembers());
	}

	@Test
	public void theSharedMemberListCannotBeMutatedByCallers()
	{
		GroupState state = new GroupState();
		state.applyUpdate(new MemberDto[]{member("alice", null)});

		try
		{
			state.getMembers().clear();
			org.junit.Assert.fail("the shared list must be immutable");
		}
		catch (UnsupportedOperationException expected)
		{
			// A caller reordering this in place would corrupt every other view.
		}
	}

	@Test
	public void aFieldMissingFromAnUpdateLeavesTheOldValueAlone()
	{
		// The server sends deltas: an unchanged field comes back null and must not clear.
		GroupState state = new GroupState();
		state.applyUpdate(new MemberDto[]{member("alice", new int[]{100, 200})});
		state.applyUpdate(new MemberDto[]{member("alice", null)});

		GroupMember alice = state.getMember("alice");
		assertNotNull(alice);
		assertEquals(100, alice.getXp(GroupSkill.AGILITY));
	}

	@Test
	public void matchesNamesAcrossTheNonBreakingSpaceTheClientUses()
	{
		assertTrue(GroupState.namesMatch("Rat von Hat", "Rat\u00a0von\u00a0Hat"));
		assertTrue(GroupState.namesMatch("skreech king", "Skreech King"));
	}

	private static MemberDto updatedAt(String name, String lastUpdated)
	{
		MemberDto dto = member(name, null);
		dto.last_updated = lastUpdated;
		return dto;
	}

	@Test
	public void aResponseFromBeforeAResetIsDropped()
	{
		// A poll still in flight when the credentials change must not bring the old group
		// back, nor move the cursor so that the new group's first fetch skips its history.
		GroupState state = new GroupState();
		int before = state.getGeneration();
		state.reset();

		assertFalse(state.applyUpdate(
			new MemberDto[]{updatedAt("alice", "2026-10-13T12:00:00Z")}, before));
		assertTrue(state.isEmpty());
		assertEquals("1970-01-01T00:00:00Z", state.getFromTime());
	}

	@Test
	public void aResponseFromTheCurrentGenerationIsMerged()
	{
		GroupState state = new GroupState();
		state.reset();

		assertTrue(state.applyUpdate(new MemberDto[]{member("alice", null)}, state.getGeneration()));
		assertNotNull(state.getMember("alice"));
	}

	@Test
	public void theNewestMemberRepeatedByTheInclusiveCursorIsNotAChange()
	{
		GroupState state = new GroupState();
		MemberDto first = updatedAt("Alice", "2026-10-13T11:24:54.063221Z");
		first.skills = new int[]{1, 2, 3};
		assertTrue(state.applyUpdate(new MemberDto[]{first}));

		// from_time is inclusive, so the next poll hands back the same fields again.
		MemberDto again = updatedAt("Alice", "2026-10-13T11:24:54.063221Z");
		again.skills = new int[]{1, 2, 3};
		assertFalse(state.applyUpdate(new MemberDto[]{again}));

		MemberDto newer = updatedAt("Alice", "2026-10-13T11:25:00Z");
		newer.skills = new int[]{1, 2, 4};
		assertTrue(state.applyUpdate(new MemberDto[]{newer}));
	}

	@Test
	public void theCursorNeverMovesBackwards()
	{
		GroupState state = new GroupState();
		state.applyUpdate(new MemberDto[]{updatedAt("alice", "2026-10-13T12:00:05Z")});
		assertEquals("2026-10-13T12:00:05Z", state.getFromTime());

		// An older timestamp, or none at all, leaves the cursor where it is.
		state.applyUpdate(new MemberDto[]{updatedAt("alice", "2026-10-13T12:00:01Z")});
		assertEquals("2026-10-13T12:00:05Z", state.getFromTime());
		state.applyUpdate(new MemberDto[]{member("alice", null)});
		assertEquals("2026-10-13T12:00:05Z", state.getFromTime());

		state.applyUpdate(new MemberDto[]{updatedAt("alice", "2026-10-13T12:00:09Z")});
		assertEquals("2026-10-13T12:00:09Z", state.getFromTime());
	}

	private static GroupMember.Interaction interactionSecondsAgo(GroupState state, long seconds)
	{
		MemberDto dto = member("alice", null);
		dto.interacting = new MemberDto.InteractingDto();
		dto.interacting.name = "Goblin";
		dto.interacting.last_updated = Instant.now().minusSeconds(seconds).toString();
		state.applyUpdate(new MemberDto[]{dto});
		return state.getMember("alice").getInteraction();
	}

	@Test
	public void interactionsStayCurrentForLongerAtSlowRefreshRates()
	{
		// At a 30 second refresh an interaction is often 20 seconds old when it arrives.
		GroupState state = new GroupState();
		assertTrue(interactionSecondsAgo(state, 20).isStale());

		state.setPollSeconds(30);
		assertFalse(interactionSecondsAgo(state, 20).isStale());
		assertTrue(interactionSecondsAgo(state, 40).isStale());
	}

	@Test
	public void dropsMembersTheServerNoLongerLists()
	{
		GroupState state = new GroupState();
		state.applyUpdate(new MemberDto[]{member("alice", null), member("bob", null)});
		assertEquals(2, state.getMembers().size());

		state.applyUpdate(new MemberDto[]{member("alice", null)});
		assertEquals(1, state.getMembers().size());
	}

	@Test
	public void everyResponseFeedsTheActivityTrackerAndAResetClearsIt()
	{
		ActivityTracker activity = new ActivityTracker(null, point -> null);
		GroupState state = new GroupState(activity);

		MemberDto first = member("alice", new int[]{100, 200});
		first.last_updated = Instant.now().toString();
		state.applyUpdate(new MemberDto[]{first, member("@SHARED", null)});

		MemberDto second = member("alice", new int[]{150, 200});
		second.last_updated = Instant.now().toString();
		state.applyUpdate(new MemberDto[]{second, member("@SHARED", null)});

		Activity alice = activity.get("alice");
		assertNotNull(alice);
		assertEquals(Activity.Kind.SKILLING, alice.getKind());
		assertEquals("Agility", alice.describe(Instant.now(), false));
		assertNull("group storage is not a person", activity.get("@SHARED"));

		state.reset();
		assertNull(activity.get("alice"));
	}
}

package com.groupironmencompanion.map;

import com.google.gson.Gson;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Guards the generated map-areas.json resource. Regenerate it with tools/mapdump after a
 * game update; if a dungeon moves or the cache format shifts, these break rather than the
 * markers quietly pointing somewhere wrong.
 */
public class MapAreasTest
{
	private final MapAreas areas = MapAreas.get(new Gson());

	private static WorldPoint at(int x, int y)
	{
		return new WorldPoint(x, y, 0);
	}

	private void assertEntrance(String label, WorldPoint inside, int expectedX, int expectedY, int tolerance)
	{
		MapAreas.Located located = areas.locate(inside);
		assertNotNull(label + ": should be recognised as off-surface", located);

		WorldPoint entrance = located.getEntrance();
		assertNotNull(label + ": should resolve to a surface entrance", entrance);

		int dx = entrance.getX() - expectedX;
		int dy = entrance.getY() - expectedY;
		double distance = Math.sqrt(dx * dx + dy * dy);
		assertTrue(
			label + ": entrance " + entrance.getX() + "," + entrance.getY()
				+ " is " + Math.round(distance) + " tiles from the expected "
				+ expectedX + "," + expectedY,
			distance <= tolerance);
	}

	@Test
	public void resolvesStandardUndergroundDungeons()
	{
		assertEntrance("Taverley Dungeon", at(2884, 9813), 2884, 3397, 5);
		assertEntrance("Edgeville Dungeon", at(3096, 9867), 3097, 3468, 5);
		assertEntrance("Varrock Sewers", at(3237, 9858), 3237, 3458, 5);
		assertEntrance("Lumbridge Swamp Caves", at(3169, 9572), 3169, 3172, 5);
		assertEntrance("Asgarnian Ice Dungeon", at(3007, 9550), 3008, 3150, 5);
		assertEntrance("Brimhaven Dungeon", at(2713, 9564), 2744, 3154, 5);
		assertEntrance("Kalphite Lair", at(3483, 9510), 3227, 3108, 5);
	}

	@Test
	public void resolvesDetachedAreasThatAreNotInTheUndergroundBand()
	{
		// These sit at their own coordinates rather than surface y + 6400, so they only
		// resolve through the cache's intermap links.
		assertEntrance("God Wars Dungeon", at(2882, 5310), 2918, 3746, 5);
		assertEntrance("Zanaris", at(2452, 4473), 3203, 3169, 5);
		assertEntrance("Stronghold of Security", at(1859, 5243), 3081, 3420, 5);
		assertEntrance("Ancient Cavern", at(1763, 5361), 2531, 3446, 5);
		assertEntrance("Ourania Altar", at(3040, 5600), 2452, 3231, 5);
		assertEntrance("Ruins of Camdozaal", at(2952, 5766), 2999, 3493, 5);
	}

	@Test
	public void resolvesAreasWhoseOnlyLinkLeadsIntoAnotherDungeon()
	{
		// Mor Ul Rek links into Karamja Underground, whose own exit is the volcano.
		assertEntrance("Mor Ul Rek", at(2480, 5175), 2856, 3168, 8);
		// Dorgesh-Kaan is reached through the Lumbridge Swamp Caves.
		assertEntrance("Dorgesh-Kaan", at(2720, 5344), 3209, 3218, 30);
	}

	@Test
	public void pinsADetachedAreaAtThePlaceYouTravelToItFrom()
	{
		// Projecting the Rift used to land in the sea east of Uzer. You get there from the
		// Wizards' Tower, whose ladder the cache links to the basement portal.
		MapAreas.Located located = areas.locate(at(3615, 9469));
		assertNotNull(located);
		assertNotNull("a detached area with a known travel point should be pinned at it",
			located.getEntrance());
		assertEquals(3104, located.getEntrance().getX());
		assertEquals(3162, located.getEntrance().getY());
		assertEquals("the label must name the area, not the doorway",
			"Guardians of the Rift", located.describe());
	}

	@Test
	public void coversTheWholeArenaAndNotJustItsTransportTile()
	{
		// Keying on just the transport's square missed most of the arena.
		int[][] insideTheArena = {
			{3615, 9469},   // the transport itself
			{3615, 9475},   // a few tiles north, into the next square
			{3600, 9500},
			{3630, 9440},
			{3570, 9480},   // the western square
			{3660, 9500},   // the eastern square
		};

		for (int[] p : insideTheArena)
		{
			MapAreas.Located located = areas.locate(at(p[0], p[1]));
			assertNotNull(located);
			assertEquals("(" + p[0] + "," + p[1] + ") should be named",
				"Guardians of the Rift", located.describe());
			assertNotNull("(" + p[0] + "," + p[1] + ") should be pinned",
				located.getEntrance());
			assertEquals("(" + p[0] + "," + p[1] + ") must pin to the Wizards' Tower, never "
				+ "to the projection out of the underground band",
				3104, located.getEntrance().getX());
			assertEquals(3162, located.getEntrance().getY());
		}
	}

	@Test
	public void theDetachedBoxDoesNotSwallowItsMappedNeighbours()
	{
		// The box is generous, so the real areas bordering it must still win.
		MapAreas.Located mosLeHarmless = areas.locate(at(3745, 9385));
		assertNotNull(mosLeHarmless);
		assertEquals("Mos Le'Harmless Cave", mosLeHarmless.getAreaName());

		MapAreas.Located desert = areas.locate(at(3490, 9480));
		assertNotNull(desert);
		assertEquals("Kharidian Desert Underground", desert.getAreaName());
	}

	@Test
	public void fallsBackToProjectionWhenTheCacheHasNoLink()
	{
		// The Barrows tunnels have no intermap link, but like every area in the underground
		// band they sit exactly 6400 tiles below the surface they belong to.
		MapAreas.Located located = areas.locate(at(3565, 9695));
		assertNotNull(located);
		assertNotNull(located.getEntrance());
		assertEquals(3565, located.getEntrance().getX());
		assertEquals(3295, located.getEntrance().getY());
	}

	@Test
	public void snapsAnUnmappedDungeonToARealEntrance()
	{
		// Varlamore's Hunter Guild caverns must resolve to the guild's own entrance, and stay
		// on it as the member walks about rather than sliding across the overworld with them.
		MapAreas.Located inside = areas.locate(at(1560, 9460));
		assertNotNull(inside);
		assertNotNull(inside.getEntrance());
		assertEquals("Hunter Guild Caverns", inside.getEntranceName());

		MapAreas.Located twentyNorth = areas.locate(at(1560, 9480));
		assertNotNull(twentyNorth.getEntrance());
		assertEquals("Hunter Guild Caverns", twentyNorth.getEntranceName());

		// The walk crosses the edge of Varlamore Underground, and the two sides place the
		// marker a tile apart. Same entrance either way, which is what matters.
		assertTrue("the entrance must not move with the member",
			inside.getEntrance().distanceTo2D(twentyNorth.getEntrance()) <= 2);
	}

	@Test
	public void doesNotSnapToAConfidentlyWrongEntrance()
	{
		// The Barrows tunnels project to within 85 tiles of the Shade Catacombs entrance,
		// which is a different dungeon. Better to fall back to the bare projection than to
		// point confidently at the wrong door.
		MapAreas.Located located = areas.locate(at(3565, 9695));
		assertNotNull(located);
		assertNotNull(located.getEntrance());
		assertNull("must not borrow a neighbouring dungeon's name", located.getEntranceName());
	}

	@Test
	public void namesTheAreaEvenWhenItIsNotADungeon()
	{
		MapAreas.Located located = areas.locate(at(2884, 9813));
		assertNotNull(located);
		assertEquals("Taverley Underground", located.getAreaName());
		assertEquals("Taverley Dungeon", located.describe());
	}

	@Test
	public void overworldPositionsAreNotTreatedAsUnderground()
	{
		// Somewhere in Varrock, and a first-floor building: both are drawn on the world map
		// where they stand and must not gain an entrance marker.
		assertNull(areas.locate(at(3222, 3218)));
		assertNull(areas.locate(new WorldPoint(3222, 3218, 1)));
		assertNull(areas.locate(at(1637, 3673)));
	}
}

package com.groupironmencompanion.map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.PluginMessage;
import org.junit.Test;

public class WorldMapPlusBridgeTest
{
	/** An event bus only calls public methods of public classes. */
	public static final class Listener
	{
		private final List<PluginMessage> into;

		Listener(List<PluginMessage> into)
		{
			this.into = into;
		}

		@Subscribe
		public void onPluginMessage(PluginMessage message)
		{
			into.add(message);
		}
	}

	@Test
	public void focusAsksWorldMapPlusToCentreOnThePlace()
	{
		List<PluginMessage> sent = new ArrayList<>();
		EventBus bus = new EventBus();
		bus.register(new Listener(sent));
		WorldPoint where = new WorldPoint(3040, 9820, 0);

		new WorldMapPlusBridge(bus).focus(where, "Alice");

		assertEquals(1, sent.size());
		assertEquals("worldmapplus", sent.get(0).getNamespace());
		assertEquals("focus", sent.get(0).getName());
		assertSame(where, sent.get(0).getData().get("point"));
		assertEquals("Alice", sent.get(0).getData().get("name"));
		assertTrue(((Number) sent.get(0).getData().get("zoom")).doubleValue() > 0);
	}

	@Test
	public void noPlaceSendsNothing()
	{
		List<PluginMessage> sent = new ArrayList<>();
		EventBus bus = new EventBus();
		bus.register(new Listener(sent));
		new WorldMapPlusBridge(bus).focus(null, "Alice");
		assertTrue(sent.isEmpty());
	}
}

package com.groupironmencompanion.map;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/** Taking coverage answers from another plugin, which may be late, duplicated or malformed. */
public class WorldMapPlusCoverageTest
{
	// Captures posts so a reply can echo the id the bridge actually sent.
	private static final class Capture extends EventBus
	{
		private final List<PluginMessage> posted = new ArrayList<>();

		@Override
		public void post(Object event)
		{
			if (event instanceof PluginMessage)
			{
				posted.add((PluginMessage) event);
			}
		}

		PluginMessage last()
		{
			return posted.get(posted.size() - 1);
		}
	}

	private static final WorldPoint RIFT = new WorldPoint(3615, 9469, 0);
	private static final WorldPoint LUMBRIDGE = new WorldPoint(3222, 3218, 0);

	private Capture bus;
	private WorldMapPlusBridge bridge;

	@Before
	public void setUp()
	{
		bus = new Capture();
		bridge = new WorldMapPlusBridge(bus);
	}

	private String askAbout(WorldPoint... points)
	{
		bridge.requestCoverage(Arrays.asList(points));
		PluginMessage sent = bus.last();
		assertEquals("worldmapplus", sent.getNamespace());
		assertEquals("covers", sent.getName());
		return (String) sent.getData().get("id");
	}

	private void reply(String id, List<Boolean> covered, List<Boolean> exact, List<String> names)
	{
		Map<String, Object> data = new HashMap<>();
		data.put("id", id);
		data.put("covered", covered);
		data.put("exact", exact);
		data.put("mapNames", names);
		bridge.onPluginMessage(new PluginMessage("worldmapplus", "covers_reply", data));
	}

	// The default is "not covered"

	@Test
	public void nothingIsCoveredBeforeAnybodyAnswers()
	{
		// Same as World Map Plus not being installed.
		askAbout(RIFT);
		assertFalse(bridge.isExactlyCovered(RIFT));
	}

	@Test
	public void aNullPointIsNotCovered()
	{
		assertFalse(bridge.isExactlyCovered(null));
	}

	// Taking an answer

	@Test
	public void recordsAnExactAnswerAgainstTheTileItWasAbout()
	{
		String id = askAbout(RIFT);
		reply(id, Collections.singletonList(true), Collections.singletonList(true),
			Collections.singletonList("Guardians of the Rift"));

		assertTrue(bridge.isExactlyCovered(RIFT));
	}

	@Test
	public void coveredButNotExactDoesNotCount()
	{
		// "Covered" can mean their nearest map 192 tiles away. We only step aside for exact.
		String id = askAbout(RIFT);
		reply(id, Collections.singletonList(true), Collections.singletonList(false),
			Collections.singletonList("Morytania Underground"));

		assertFalse(bridge.isExactlyCovered(RIFT));
	}

	@Test
	public void answersAreMatchedToPointsByPosition()
	{
		String id = askAbout(RIFT, LUMBRIDGE);
		reply(id, Arrays.asList(true, true), Arrays.asList(true, false),
			Arrays.asList("Guardians of the Rift", "Gielinor Surface"));

		assertTrue(bridge.isExactlyCovered(RIFT));
		assertFalse(bridge.isExactlyCovered(LUMBRIDGE));
	}

	// Answers we must not act on

	@Test
	public void ignoresAnAnswerToAnIdWeNeverSent()
	{
		reply("gim-not-ours", Collections.singletonList(true), Collections.singletonList(true),
			Collections.singletonList("Somewhere"));

		assertFalse(bridge.isExactlyCovered(RIFT));
	}

	@Test
	public void anIdIsAnsweredOnlyOnce()
	{
		// Their queue outlives our timeout, so late duplicates happen.
		String id = askAbout(RIFT);
		reply(id, Collections.singletonList(true), Collections.singletonList(true),
			Collections.singletonList("Guardians of the Rift"));
		assertTrue(bridge.isExactlyCovered(RIFT));

		reply(id, Collections.singletonList(false), Collections.singletonList(false),
			Collections.singletonList(""));
		assertTrue("a second answer to a spent id must not overwrite the first",
			bridge.isExactlyCovered(RIFT));
	}

	@Test
	public void ignoresMessagesFromOtherNamespacesAndNames()
	{
		String id = askAbout(RIFT);

		Map<String, Object> data = new HashMap<>();
		data.put("id", id);
		data.put("covered", Collections.singletonList(true));
		data.put("exact", Collections.singletonList(true));

		bridge.onPluginMessage(new PluginMessage("shortestpath", "covers_reply", data));
		bridge.onPluginMessage(new PluginMessage("worldmapplus", "focus_result", data));
		bridge.onPluginMessage(new PluginMessage("worldmapplus", "covers", data));

		assertFalse(bridge.isExactlyCovered(RIFT));
	}

	// Malformed payloads

	@Test
	public void survivesAnAnswerMissingItsLists()
	{
		String id = askAbout(RIFT);

		Map<String, Object> data = new HashMap<>();
		data.put("id", id);
		bridge.onPluginMessage(new PluginMessage("worldmapplus", "covers_reply", data));

		assertFalse(bridge.isExactlyCovered(RIFT));
	}

	@Test
	public void survivesAnAnswerShorterThanTheQuestion()
	{
		// The tile with no answer stays unknown rather than borrowing its neighbour's.
		String id = askAbout(RIFT, LUMBRIDGE);
		reply(id, Collections.singletonList(true), Collections.singletonList(true),
			Collections.singletonList("Guardians of the Rift"));

		assertTrue(bridge.isExactlyCovered(RIFT));
		assertFalse(bridge.isExactlyCovered(LUMBRIDGE));
	}

	@Test
	public void survivesWrongTypesInTheLists()
	{
		String id = askAbout(RIFT);

		Map<String, Object> data = new HashMap<>();
		data.put("id", id);
		data.put("covered", Collections.singletonList("yes"));
		data.put("exact", Collections.singletonList(42));
		data.put("mapNames", "not a list");
		bridge.onPluginMessage(new PluginMessage("worldmapplus", "covers_reply", data));

		assertFalse(bridge.isExactlyCovered(RIFT));
	}

	// Asking

	@Test
	public void sendsAnIdTheirRulesAccept()
	{
		// They ignore ids over 64 characters or with anything but letters, digits and _ - . :
		String id = askAbout(RIFT);
		assertTrue(id.length() <= 64);
		assertFalse(id.isEmpty());
		for (char c : id.toCharArray())
		{
			boolean plain = (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9')
				|| c == '_' || c == '-' || c == '.' || c == ':';
			assertTrue("id character '" + c + "' would be rejected", plain);
		}
	}

	@Test
	public void asksForEveryFocusToBeExact()
	{
		// Otherwise their view drifts to black space off the nearest map.
		bridge.focus(RIFT, "Someone");
		assertEquals("focus", bus.last().getName());
		assertEquals(Boolean.TRUE, bus.last().getData().get("exact"));
	}

	@Test
	public void doesNotRepeatAQuestionAlreadyAnswered()
	{
		String id = askAbout(RIFT);
		int before = bus.posted.size();
		reply(id, Collections.singletonList(true), Collections.singletonList(true),
			Collections.singletonList("Guardians of the Rift"));

		bridge.requestCoverage(Collections.singletonList(RIFT));
		assertEquals("a tile with an answer should not be asked about again",
			before, bus.posted.size());
	}

	@Test
	public void asksAtMostSixteenTilesAtOnce()
	{
		// Their cap; more gets the whole question refused.
		List<WorldPoint> many = new ArrayList<>();
		for (int i = 0; i < 40; i++)
		{
			many.add(new WorldPoint(3000 + i, 3000, 0));
		}
		bridge.requestCoverage(many);

		List<?> sent = (List<?>) bus.last().getData().get("points");
		assertTrue("sent " + sent.size() + " tiles", sent.size() <= 16);
	}

	@Test
	public void resetForgetsEverything()
	{
		String id = askAbout(RIFT);
		reply(id, Collections.singletonList(true), Collections.singletonList(true),
			Collections.singletonList("Guardians of the Rift"));
		assertTrue(bridge.isExactlyCovered(RIFT));

		bridge.reset();
		assertFalse(bridge.isExactlyCovered(RIFT));
	}
}

package com.groupironmencompanion.place;

import com.google.gson.Gson;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

/**
 * Guards the bundled place names and the way a position is put into words. If the resource
 * goes missing or its format shifts, these break rather than every activity quietly losing
 * its "at Catherby".
 */
public class PlaceNamesTest
{
	private final PlaceNames names = new PlaceNames();
	private final Whereabouts whereabouts = new Whereabouts(names, new Gson());

	@Test
	public void namesATownOnTheSurface()
	{
		assertEquals("Catherby", names.nameFor(new WorldPoint(2813, 3440, 0)));
	}

	@Test
	public void namesADungeonByItsRegionRatherThanItsMonsters()
	{
		// The map labels alone would call this "Black demons" or similar.
		assertEquals("Taverley Dungeon", names.nameFor(new WorldPoint(2884, 9798, 0)));
	}

	@Test
	public void saysUpstairsAboveTheGroundFloor()
	{
		Place place = whereabouts.of(new WorldPoint(2965, 3380, 1));
		assertNotNull(place);
		assertEquals("Falador, upstairs", place.toString());
		assertEquals("at Falador, upstairs", place.phrase("at"));
	}

	@Test
	public void namesInstanceTemplatesThatTheMapLabelsGetWrong()
	{
		// The house's room palette is nowhere near anything a map label would name, and a raid
		// room is labelled with its boss.
		assertEquals("Their house", String.valueOf(whereabouts.of(new WorldPoint(1888, 7072, 0))));
		assertEquals("Theatre of Blood", String.valueOf(whereabouts.of(new WorldPoint(3168, 4320, 0))));
		assertEquals("Nightmare Zone", String.valueOf(whereabouts.of(new WorldPoint(2272, 4704, 0))));
	}

	@Test
	public void somewhereUnnamedIsNearTheClosestLabel()
	{
		Place place = whereabouts.of(new WorldPoint(2300, 2700, 0));
		assertNotNull(place);
		assertEquals(Place.Relation.NEAR, place.getRelation());
		assertEquals("near " + place.getName(), place.phrase("at"));
	}

	@Test
	public void aPlaceNearOrBeneathIgnoresTheActivitysPreposition()
	{
		assertEquals("beneath Falador", new Place("Falador", Place.Relation.BENEATH, false).phrase("at"));
		assertEquals("in Catherby", Place.at("Catherby").phrase("in"));
	}

	@Test
	public void noPositionHasNoPlace()
	{
		assertNull(whereabouts.of(null));
	}
}

package com.groupironmencompanion.scene;

import com.groupironmencompanion.activity.Activities;
import com.groupironmencompanion.data.GroupSkill;
import com.groupironmencompanion.scene.GhostAnimations.Movement;
import net.runelite.api.gameval.AnimationID;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class GhostAnimationsTest
{
	// Movement

	@Test
	public void movementSpeeds()
	{
		assertEquals(Movement.STILL, GhostAnimations.movementFor(0, 1));
		assertEquals(Movement.WALKING, GhostAnimations.movementFor(1, 1));
		assertEquals(Movement.RUNNING, GhostAnimations.movementFor(2, 1));
	}

	@Test
	public void aDiagonalStepIsAWalk()
	{
		assertEquals(Movement.WALKING, GhostAnimations.movementFor(Math.sqrt(2), 1));
	}

	@Test
	public void speedIsAveragedOverTheGap()
	{
		assertEquals(Movement.WALKING, GhostAnimations.movementFor(4, 4));
	}

	@Test
	public void poses()
	{
		assertEquals(AnimationID.HUMAN_RUNNING, GhostAnimations.poseFor(Movement.RUNNING));
		assertEquals(AnimationID.HUMAN_WALK_F, GhostAnimations.poseFor(Movement.WALKING));
		assertEquals(AnimationID.HUMAN_READY, GhostAnimations.poseFor(Movement.STILL));
	}

	// Actions follow the same activity the status text shows

	@Test
	public void fightingSwingsTheWeaponTheyHold()
	{
		assertEquals(AnimationID.HUMAN_SWORD_SLASH,
			GhostAnimations.actionFor(Activities.fighting("Goblin", GroupSkill.STRENGTH), WeaponClass.MELEE_SLASH, false));
		assertEquals(AnimationID.HUMAN_CROSSBOW,
			GhostAnimations.actionFor(Activities.fighting("Goblin", GroupSkill.RANGED), WeaponClass.CROSSBOW, false));
	}

	@Test
	public void combatXpBeatsAWeaponNameWeDidNotRecognise()
	{
		// A mage with a staff whose name doesn't contain "staff" still casts.
		assertEquals(AnimationID.HUMAN_CASTING,
			GhostAnimations.actionFor(Activities.fighting("Goblin", GroupSkill.MAGIC), WeaponClass.UNARMED, false));
		assertEquals(AnimationID.HUMAN_BOW,
			GhostAnimations.actionFor(Activities.fightingByExperience(GroupSkill.RANGED), WeaponClass.UNARMED, false));
	}

	@Test
	public void skillingPlaysThatSkill()
	{
		assertEquals(AnimationID.HUMAN_WOODCUTTING_RUNE_AXE,
			GhostAnimations.actionFor(Activities.skilling(GroupSkill.WOODCUTTING), WeaponClass.UNARMED, false));
		assertEquals(AnimationID.PICKING_LOW,
			GhostAnimations.actionFor(Activities.skilling(GroupSkill.FARMING), WeaponClass.UNARMED, false));
		assertEquals(AnimationID.HUMAN_FISH_ONSPOT,
			GhostAnimations.actionFor(Activities.fishing("Fishing spot"), WeaponClass.UNARMED, false));
	}

	@Test
	public void magicOnItsOwnCastsButIsNotAFight()
	{
		// Alching: the status says "Magic", so no opponent, but the figure still casts.
		assertEquals(AnimationID.HUMAN_CASTING,
			GhostAnimations.actionFor(Activities.skilling(GroupSkill.MAGIC), WeaponClass.MELEE_SLASH, false));
		assertFalse(GhostAnimations.isFighting(Activities.skilling(GroupSkill.MAGIC)));
	}

	@Test
	public void talkingToSomeoneIsNotAnAttack()
	{
		// This used to swing at shopkeepers.
		assertEquals(-1, GhostAnimations.actionFor(Activities.talking("Hans"), WeaponClass.MELEE_SLASH, false));
		assertFalse(GhostAnimations.isFighting(Activities.talking("Hans")));
	}

	@Test
	public void nothingToShowForIdleOrUnknown()
	{
		assertEquals(-1, GhostAnimations.actionFor(Activities.idle(), WeaponClass.MELEE_SLASH, false));
		assertEquals(-1, GhostAnimations.actionFor(null, WeaponClass.MELEE_SLASH, false));
	}

	@Test
	public void nobodySwingsOnTheMoveButTheFightGoesOn()
	{
		assertEquals(-1, GhostAnimations.actionFor(Activities.fighting("Goblin", GroupSkill.ATTACK), WeaponClass.MELEE_STAB, true));
		assertTrue(GhostAnimations.isFighting(Activities.fighting("Goblin", GroupSkill.ATTACK)));
	}

	@Test
	public void actionsRepeatOnAWeaponSpeedNotEveryTick()
	{
		assertEquals(4, GhostAnimations.ACTION_INTERVAL_TICKS);
	}

	// Weapon names

	@Test
	public void classifiesCommonWeapons()
	{
		assertEquals(WeaponClass.MELEE_SLASH, WeaponClass.classify("Dragon scimitar"));
		assertEquals(WeaponClass.MELEE_STAB, WeaponClass.classify("Dragon dagger"));
		assertEquals(WeaponClass.MELEE_CRUSH, WeaponClass.classify("Granite maul"));
		assertEquals(WeaponClass.BOW, WeaponClass.classify("Magic shortbow"));
		assertEquals(WeaponClass.THROWN, WeaponClass.classify("Rune knife"));
	}

	@Test
	public void moreSpecificNamesWin()
	{
		assertEquals(WeaponClass.CROSSBOW, WeaponClass.classify("Dragon crossbow"));
		assertEquals(WeaponClass.STAFF, WeaponClass.classify("Staff of the dead"));
		assertEquals(WeaponClass.STAFF, WeaponClass.classify("Trident of the swamp"));
	}

	@Test
	public void partisansAreStabWeapons()
	{
		// Used to land under STAFF and cast spells.
		assertEquals(WeaponClass.MELEE_STAB, WeaponClass.classify("Keris partisan"));
		assertEquals(WeaponClass.MELEE_STAB, WeaponClass.classify("Keris partisan of the sun"));
	}

	@Test
	public void unknownOrEmptyIsUnarmed()
	{
		assertEquals(WeaponClass.UNARMED, WeaponClass.classify(null));
		assertEquals(WeaponClass.UNARMED, WeaponClass.classify(""));
		assertEquals(WeaponClass.UNARMED, WeaponClass.classify("Bucket"));
	}
}

package com.groupironmencompanion.scene;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/** Runs against the real bundled table, so it also catches a bad regeneration. */
public class GhostAppearanceTest
{
	// A platebody has sleeves and a chainbody doesn't, which is what the sleeve rule hangs on.
	private static final int RUNE_PLATEBODY = 1127;
	private static final int RUNE_CHAINBODY = 1113;
	private static final int RUNE_FULL_HELM = 1163;
	private static final int RUNE_PLATELEGS = 1079;
	private static final int ABYSSAL_WHIP = 4151;

	// Equipment slot indices.
	private static final int SLOT_HEAD = 0;
	private static final int SLOT_WEAPON = 3;
	private static final int SLOT_BODY = 4;
	private static final int SLOT_LEGS = 7;
	private static final int SLOT_RING = 12;

	private static GearTable table()
	{
		GearTable table = GearTable.load();
		assertNotNull("the bundled worn-model table must load", table);
		return table;
	}

	private static int[] wearing(int slot, int itemId)
	{
		int[] equipment = new int[14];
		equipment[slot] = itemId;
		return equipment;
	}

	@Test
	public void theBundledTableIsPresentAndPopulated()
	{
		GearTable table = table();
		assertTrue("the table should cover thousands of items", table.itemCount() > 5000);

		for (int part = 0; part <= 6; part++)
		{
			assertTrue("body part " + part + " needs a default model", table.bodyModel(part) > 0);
		}
	}

	/**
	 * A table built from an old cache looks fine but draws members as floating heads (it's
	 * happened). The only way to tell is to check for something only a recent cache has.
	 */
	@Test
	public void theTableWasBuiltFromARecentCache()
	{
		GearTable table = table();

		int[] sunlightCrossbow = table.wornModels(28869);
		assertNotNull("Hunters' sunlight crossbow is missing: the cache used to build the "
			+ "worn-model table predates Varlamore. Regenerate with tools/geardump against "
			+ "~/.runelite/jagexcache, not ~/jagexcache.", sunlightCrossbow);
		assertTrue(sunlightCrossbow[0] > 0);

		assertNotNull("Mixed hide top is missing from the worn-model table", table.wornModels(29280));
	}

	@Test
	public void anUnarmedMemberIsTheirOwnBody()
	{
		GearTable gear = table();
		int[] slots = GhostAppearance.resolve(new int[14], gear);

		assertEquals(gear.bodyModel(2), slots[GhostAppearance.TORSO]);
		assertEquals(gear.bodyModel(3), slots[GhostAppearance.ARMS]);
		assertEquals(gear.bodyModel(5), slots[GhostAppearance.LEGS]);
		assertEquals(gear.bodyModel(0), slots[GhostAppearance.HAIR]);

		assertEquals(-1, slots[GhostAppearance.WEAPON]);
		assertEquals(-1, slots[GhostAppearance.CAPE]);
		assertEquals(-1, slots[GhostAppearance.SHIELD]);
	}

	// Sleeves

	@Test
	public void aPlatebodyBringsItsOwnSleeves()
	{
		GearTable gear = table();
		int[] slots = GhostAppearance.resolve(wearing(SLOT_BODY, RUNE_PLATEBODY), gear);

		int[] models = gear.wornModels(RUNE_PLATEBODY);
		assertNotNull("the table must know a rune platebody", models);

		assertEquals("torso is the item", models[0], slots[GhostAppearance.TORSO]);
		assertEquals("arms are the item's sleeves", models[1], slots[GhostAppearance.ARMS]);
		assertTrue("a platebody has a second mesh", models[1] > 0);
	}

	@Test
	public void aChainbodyLeavesTheWearersArmsShowing()
	{
		GearTable gear = table();
		int[] slots = GhostAppearance.resolve(wearing(SLOT_BODY, RUNE_CHAINBODY), gear);

		int[] models = gear.wornModels(RUNE_CHAINBODY);
		assertNotNull("the table must know a rune chainbody", models);
		assertEquals("a chainbody has no second mesh", -1, models[1]);

		assertEquals("torso is the item", models[0], slots[GhostAppearance.TORSO]);
		assertEquals("arms fall back to the body", gear.bodyModel(3), slots[GhostAppearance.ARMS]);
	}

	// Headgear

	@Test
	public void headgearHidesHairAndBeard()
	{
		GearTable gear = table();
		int[] slots = GhostAppearance.resolve(wearing(SLOT_HEAD, RUNE_FULL_HELM), gear);

		int[] models = gear.wornModels(RUNE_FULL_HELM);
		assertNotNull(models);

		assertEquals("head is the helm", models[0], slots[GhostAppearance.HEAD]);
		assertEquals("hair is hidden under it", -1, slots[GhostAppearance.HAIR]);
		assertEquals("so is the beard", -1, slots[GhostAppearance.JAW]);
	}

	// Slots that cover nothing

	@Test
	public void legwearReplacesLegsAndNothingElse()
	{
		GearTable gear = table();
		int[] slots = GhostAppearance.resolve(wearing(SLOT_LEGS, RUNE_PLATELEGS), gear);

		assertEquals(gear.wornModels(RUNE_PLATELEGS)[0], slots[GhostAppearance.LEGS]);
		assertEquals("feet are untouched", gear.bodyModel(6), slots[GhostAppearance.BOOTS]);
	}

	@Test
	public void aWeaponIsHeldAndCoversNothing()
	{
		GearTable gear = table();
		int[] slots = GhostAppearance.resolve(wearing(SLOT_WEAPON, ABYSSAL_WHIP), gear);

		assertEquals(gear.wornModels(ABYSSAL_WHIP)[0], slots[GhostAppearance.WEAPON]);
		assertEquals(gear.bodyModel(3), slots[GhostAppearance.ARMS]);
		assertEquals(gear.bodyModel(2), slots[GhostAppearance.TORSO]);
	}

	@Test
	public void ringsAndAmmunitionAreNeverDrawn()
	{
		GearTable gear = table();
		int[] bare = GhostAppearance.resolve(new int[14], gear);
		int[] ringed = GhostAppearance.resolve(wearing(SLOT_RING, 1635), gear);

		org.junit.Assert.assertArrayEquals(bare, ringed);
	}

	// Robustness

	@Test
	public void anItemTheTableDoesNotKnowLeavesTheBodyShowing()
	{
		// Gear newer than the table.
		GearTable gear = table();
		int[] slots = GhostAppearance.resolve(wearing(SLOT_BODY, 99_999_999), gear);

		assertEquals(gear.bodyModel(2), slots[GhostAppearance.TORSO]);
	}

	@Test
	public void aShortOrAbsentEquipmentArrayIsHandled()
	{
		// No equipment reported yet, or a short container.
		GearTable gear = table();

		assertEquals(GhostAppearance.SLOT_COUNT,
			GhostAppearance.resolve(null, gear).length);
		assertEquals(GhostAppearance.SLOT_COUNT,
			GhostAppearance.resolve(new int[]{0, 0}, gear).length);
	}

	@Test
	public void everySlotHoldsEitherAMeshOrNothing()
	{
		GearTable gear = table();
		int[] equipment = new int[14];
		equipment[SLOT_HEAD] = RUNE_FULL_HELM;
		equipment[SLOT_BODY] = RUNE_PLATEBODY;
		equipment[SLOT_LEGS] = RUNE_PLATELEGS;
		equipment[SLOT_WEAPON] = ABYSSAL_WHIP;

		for (int model : GhostAppearance.resolve(equipment, gear))
		{
			assertTrue("a slot is either a real model id or -1", model == -1 || model > 0);
		}
	}
}

package com.groupironmencompanion.scene;

import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class GroupScenePresenceTest
{
	// The plane comes straight from the group's server and the client indexes arrays by it.

	@Test
	public void acceptsTheFourRealPlanes()
	{
		for (int plane = 0; plane <= 3; plane++)
		{
			assertTrue(GroupScenePresence.isRealPlane(plane));
		}
	}

	@Test
	public void refusesAnythingElse()
	{
		assertFalse(GroupScenePresence.isRealPlane(4));
		assertFalse(GroupScenePresence.isRealPlane(99_999));
		assertFalse(GroupScenePresence.isRealPlane(Integer.MAX_VALUE));
		assertFalse(GroupScenePresence.isRealPlane(-1));
		assertFalse(GroupScenePresence.isRealPlane(Integer.MIN_VALUE));
	}

	// Members on our own world are drawn by the game, not by us.

	@Test
	public void ourWorldIsTheGamesToDraw()
	{
		assertTrue(GroupScenePresence.isOurWorld(302, 302));
		assertFalse(GroupScenePresence.isOurWorld(301, 302));
	}

	@Test
	public void anUnknownWorldIsNotOurs()
	{
		// -1 before their stats arrive. The caller then checks the scene for them instead.
		assertFalse(GroupScenePresence.isOurWorld(-1, 302));
		assertFalse(GroupScenePresence.isOurWorld(0, 0));
	}
}

package com.groupironmencompanion.scene;

import com.groupironmencompanion.scene.GhostAnimations.Movement;
