import net.runelite.cache.fs.Store;

/**
 * Dumps what the game needs to draw a player wearing a given set of items.
 * <p>
 * The plugin knows which items a group member has equipped, but a running client will not say
 * what those items look like worn: {@code ItemComposition} exposes only the flat inventory
 * icon, and a {@code PlayerComposition} cannot be built for somebody who is not on your world.
 * Both facts are in the cache, which is what this reads.
 * <p>
 * Two tables come out, and the composition rules deliberately do not: this is extraction only,
 * so the reasoning about which mesh covers which body part lives in the plugin, where it can
 * be unit tested.
 * <p>
 * <b>Items.</b> Up to three worn meshes per item. The first is the item in its own equipment
 * slot. The second, when present, is the piece that replaces a body part underneath: a rune
 * platebody is {@code 306, 164}, the torso and its sleeves, while a rune chainbody is
 * {@code 301, -1} and so leaves the wearer's own arms showing. That distinction is the whole
 * of the occlusion problem, and it comes free in the data.
 * <p>
 * Note that {@code wearPos1..3} look like they should answer this and do not: the fields exist
 * on {@code ItemDefinition} but no OSRS item populates them, so they are ignored here.
 * <p>
 * <b>Body kits.</b> One identity kit per male body part, which shows wherever no item covers
 * it. Kits are grouped by {@code bodyPartId}, which runs 0-6 for male parts and 7-13 for
 * female; the plugin maps those onto appearance slots. A member's own kit - their hair, build
 * and skin - is published nowhere, so an arbitrary default body is unavoidable. Drawn as a
 * translucent silhouette that is no loss, and a group that all share one build is arguably
 * what you want anyway.
 * <p>
 * Colours are deliberately not dumped: everything is recoloured to a single ghost blue at
 * runtime, so an item's own palette would be overwritten the moment it was read.
 */
public class GearDump
{
	/**
	 * Format version, written first so a plugin reading a table it does not understand can say
	 * so rather than misparse it.
	 */
	private static final int FORMAT_VERSION = 1;

	/** Male identity kit body parts: hair, jaw, torso, arms, hands, legs, feet. */
	private static final int MALE_BODY_PARTS = 7;

	public static void main(String[] args) throws Exception
	{
		if (args.length < 2)
		{
			System.err.println("usage: geardump <cache dir> <out file>");
			System.exit(2);
		}

		File cacheDir = new File(args[0]);
		File out = new File(args[1]);

		try (Store store = new Store(cacheDir))
		{
			store.load();

			Map<Integer, int[]> items = loadWornItems(store);
			int[] body = loadDefaultBody(store);

			verifyModelsExist(store, items, body);

			write(out, items, body);

			if (args.length > 2)
			{
				report(store, items, args[2]);
			}

			System.out.println("worn items: " + items.size());
			System.out.print("default male body kit models:");
			for (int part = 0; part < MALE_BODY_PARTS; part++)
			{
				System.out.print(" " + part + "=" + body[part]);
			}
			System.out.println();
			System.out.println("wrote " + out + " (" + out.length() + " bytes)");
		}
	}

	/**
	 * Checks every model id actually exists in the cache's model index.
	 * <p>
	 * A referenced-but-absent model is the failure that shows up in game as a figure missing
	 * a limb, and it is silent at runtime: the client simply returns nothing for the id. It is
	 * far cheaper to catch here, where every id can be checked at once.
	 */
	private static void verifyModelsExist(Store store, Map<Integer, int[]> items, int[] body)
	{
		Index models = store.getIndex(IndexType.MODELS);

		int missingBody = 0;
		for (int part = 0; part < body.length; part++)
		{
			if (body[part] > 0 && models.getArchive(body[part]) == null)
			{
				System.out.println("  WARNING body part " + part + " model " + body[part]
					+ " is not in the model index");
				missingBody++;
			}
		}

		int missingItems = 0;
		for (Map.Entry<Integer, int[]> entry : items.entrySet())
		{
			for (int i = 0; i < 3; i++)
			{
				int model = entry.getValue()[i];
				if (model > 0 && models.getArchive(model) == null)
				{
					missingItems++;
				}
			}
		}

		System.out.println("model index check: " + missingBody + " body models and "
			+ missingItems + " item models missing");
	}

	/** Prints what the table holds for every item whose name matches, for diagnosing gaps. */
	private static void report(Store store, Map<Integer, int[]> items, String needle)
		throws IOException
	{
		ItemManager manager = new ItemManager(store);
		manager.load();
		Index models = store.getIndex(IndexType.MODELS);

		String lower = needle.toLowerCase();
		System.out.println("items matching '" + needle + "':");
		for (ItemDefinition item : manager.getItems())
		{
			if (item == null || item.name == null || !item.name.toLowerCase().contains(lower))
			{
				continue;
			}
			int[] worn = items.get(item.getId());
			StringBuilder line = new StringBuilder();
			line.append("  ").append(item.getId()).append(" '").append(item.name).append("'");
			if (worn == null)
			{
				line.append("  NOT IN TABLE (maleModel0=").append(item.maleModel0)
					.append(" noted=").append(item.notedTemplate)
					.append(" placeholder=").append(item.placeholderTemplateId).append(")");
			}
			else
			{
				line.append("  models=").append(worn[0]).append(",").append(worn[1])
					.append(",").append(worn[2]);
				for (int i = 0; i < 3; i++)
				{
					if (worn[i] > 0 && models.getArchive(worn[i]) == null)
					{
						line.append("  MODEL ").append(worn[i]).append(" MISSING");
					}
				}
			}
			System.out.println(line);
		}
	}

	/**
	 * Every item that has a worn model, as {@code {model0, model1, model2, offset}}.
	 * <p>
	 * Items live one archive per 256 ids rather than as files of a single archive, so the
	 * library's own manager does the walking.
	 */
	private static Map<Integer, int[]> loadWornItems(Store store) throws IOException
	{
		ItemManager manager = new ItemManager(store);
		manager.load();

		Map<Integer, int[]> items = new TreeMap<>();
		int templates = 0;

		for (ItemDefinition item : manager.getItems())
		{
			if (item == null)
			{
				continue;
			}

			// An item with no primary worn mesh is not something you can see on a player:
			// runes, food, coins and the like.
			if (item.maleModel0 <= 0)
			{
				continue;
			}

			// Noted and placeholder copies inherit the real item's models and would double the
			// table while never being worn by anyone.
			if (item.notedTemplate != -1 || item.placeholderTemplateId != -1)
			{
				templates++;
				continue;
			}

			items.put(item.getId(), new int[]{
				item.maleModel0, item.maleModel1, item.maleModel2, item.maleOffset
			});
		}

		System.out.println("skipped " + templates + " noted or placeholder copies");
		return items;
	}

	/**
	 * One model per male body part, taken as the first kit found for each.
	 * <p>
	 * Which one hardly matters: it is the shape under the armour, drawn in flat blue.
	 */
	private static int[] loadDefaultBody(Store store) throws IOException
	{
		Index configs = store.getIndex(IndexType.CONFIGS);
		Storage storage = store.getStorage();

		Archive archive = configs.getArchive(ConfigType.IDENTKIT.getId());
		ArchiveFiles files = archive.getFiles(storage.loadArchive(archive));

		KitLoader loader = new KitLoader();
		Map<Integer, Integer> firstPerPart = new LinkedHashMap<>();

		for (FSFile file : files.getFiles())
		{
			KitDefinition kit = loader.load(file.getFileId(), file.getContents());
			if (kit == null || kit.models == null || kit.models.length == 0)
			{
				continue;
			}
			if (kit.bodyPartId < 0 || kit.bodyPartId >= MALE_BODY_PARTS)
			{
				// Female parts are 7-13 and go unused: the figure is one silhouette for the
				// whole group, because nothing tells us a member's build.
				continue;
			}
			firstPerPart.putIfAbsent(kit.bodyPartId, kit.models[0]);
		}

		int[] body = new int[MALE_BODY_PARTS];
		for (int part = 0; part < MALE_BODY_PARTS; part++)
		{
			body[part] = firstPerPart.getOrDefault(part, -1);
		}
		return body;
	}

	/**
	 * Writes the table.
	 * <pre>
	 * int    format version
	 * int    body part count
	 * int[]  default model per male body part, -1 for none
	 * int    item count
	 * per item, ascending by id:
	 *   int    item id
	 *   int    worn model 1, 2, 3   (-1 for none)
	 *   short  vertical offset
	 * </pre>
	 */
	private static void write(File out, Map<Integer, int[]> items, int[] body) throws IOException
	{
		File parent = out.getParentFile();
		if (parent != null)
		{
			parent.mkdirs();
		}

		try (DataOutputStream stream = new DataOutputStream(new FileOutputStream(out)))
		{
			stream.writeInt(FORMAT_VERSION);
			stream.writeInt(MALE_BODY_PARTS);
			for (int model : body)
			{
				stream.writeInt(model);
			}

			stream.writeInt(items.size());
			for (Map.Entry<Integer, int[]> entry : items.entrySet())
			{
				int[] worn = entry.getValue();
				stream.writeInt(entry.getKey());
				stream.writeInt(worn[0]);
				stream.writeInt(worn[1]);
				stream.writeInt(worn[2]);
				stream.writeShort(worn[3]);
			}
		}
	}
}

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import java.io.File;
import java.io.FileWriter;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.runelite.cache.IndexType;
import net.runelite.cache.WorldMapManager;
import net.runelite.cache.definitions.MapSquareDefinition;
import net.runelite.cache.definitions.WorldMapCompositeDefinition;
import net.runelite.cache.definitions.WorldMapDefinition;
import net.runelite.cache.definitions.ZoneDefinition;
import net.runelite.cache.definitions.loaders.WorldMapCompositeLoader;
import net.runelite.cache.definitions.loaders.WorldMapLoader;
import net.runelite.cache.fs.Archive;
import net.runelite.cache.fs.ArchiveFiles;
import net.runelite.cache.fs.FSFile;
import net.runelite.cache.fs.Index;
import net.runelite.cache.fs.Storage;
import net.runelite.cache.fs.Store;
import net.runelite.cache.region.Position;

/**
 * Dumps, for every world map the game defines, the real world squares it covers and the
 * intermap links the map view offers. Squares come from the composite map data, where each
 * entry says which source square of the world is shown at which display square.
 */
public class AreaDump
{
	public static class Area
	{
		int fileId;
		String name;
		boolean isSurface;
		/** Real world squares (x*64,y*64 tile blocks) this map draws, as "sx,sz" strings. */
		List<int[]> squares = new ArrayList<>();
	}

	public static class Link
	{
		int fromX;
		int fromY;
		int fromZ;
		int toX;
		int toY;
		int toZ;
	}

	public static class Dump
	{
		List<Area> areas = new ArrayList<>();
		List<Link> links = new ArrayList<>();
	}

	public static void main(String[] args) throws Exception
	{
		File cacheDir = new File(args[0]);
		File out = new File(args[1]);

		Gson gson = new GsonBuilder().setPrettyPrinting().create();
		Dump dump = new Dump();

		try (Store store = new Store(cacheDir))
		{
			store.load();
			Storage storage = store.getStorage();
			Index index = store.getIndex(IndexType.WORLDMAP);

			// Map names, keyed by file id.
			Map<Integer, WorldMapDefinition> details = new LinkedHashMap<>();
			Archive detailsArchive = index.isNamed()
				? index.findArchiveByName("details")
				: index.getArchive(WorldMapManager.DETAILS_ID);
			ArchiveFiles detailFiles = detailsArchive.getFiles(storage.loadArchive(detailsArchive));
			for (FSFile file : detailFiles.getFiles())
			{
				WorldMapDefinition def = new WorldMapLoader().load(file.getContents(), file.getFileId());
				details.put(file.getFileId(), def);
			}

			// Composite data carries the actual square coverage, one file per map.
			Archive compositeArchive = index.isNamed()
				? index.findArchiveByName("compositemap")
				: index.getArchive(WorldMapManager.COMPOSITEMAP_ID);
			WorldMapCompositeLoader loader = new WorldMapCompositeLoader();
			loader.configureForRevision(index.getRevision());

			ArchiveFiles compositeFiles = compositeArchive.getFiles(storage.loadArchive(compositeArchive));
			for (FSFile file : compositeFiles.getFiles())
			{
				WorldMapCompositeDefinition composite = loader.load(file.getContents());

				Area area = new Area();
				area.fileId = file.getFileId();
				WorldMapDefinition def = details.get(file.getFileId());
				area.name = def == null ? ("map " + file.getFileId()) : def.name;
				area.isSurface = def != null && def.isSurface;

				for (MapSquareDefinition square : composite.getMapSquareDefinitions())
				{
					area.squares.add(new int[]{
						square.sourceSquareX, square.sourceSquareZ, square.minLevel, square.levels
					});
				}
				// Zones are 8x8 sub-blocks; record the square they belong to, which is
				// enough resolution for "which map is this point on".
				for (ZoneDefinition zone : composite.getZoneDefinitions())
				{
					area.squares.add(new int[]{
						zone.sourceSquareX, zone.sourceSquareZ, zone.minLevel, zone.levels
					});
				}

				dump.areas.add(area);
			}

			WorldMapManager manager = new WorldMapManager(store);
			manager.load();
			for (Map.Entry<Position, Position> entry : manager.getIntermapLinks().entrySet())
			{
				Link link = new Link();
				link.fromX = entry.getKey().getX();
				link.fromY = entry.getKey().getY();
				link.fromZ = entry.getKey().getZ();
				link.toX = entry.getValue().getX();
				link.toY = entry.getValue().getY();
				link.toZ = entry.getValue().getZ();
				dump.links.add(link);
			}
		}

		try (FileWriter writer = new FileWriter(out))
		{
			gson.toJson(dump, writer);
		}
		System.out.println("Dumped " + dump.areas.size() + " areas and " + dump.links.size() + " links to " + out);
	}
}

import net.runelite.cache.definitions.LocationsDefinition;
import net.runelite.cache.definitions.MapDefinition;
import net.runelite.cache.region.RegionLoader;
import net.runelite.cache.fs.Store;
import java.io.File;

/** Probe: can object placements (the locations archive) be read without XTEA keys? */
public class LocProbe
{
	public static void main(String[] args) throws Exception
	{
		try (Store store = new Store(new File(args[0])))
		{
			store.load();
			RegionLoader loader = new RegionLoader(store, region -> null);

			int[] regions = {14483, 14484, 12850, 12853, 13622};
			String[] labels = {"GOTR (56,147)", "GOTR north (56,148)", "Lumbridge", "Varrock", "Wizards Tower area"};

			for (int i = 0; i < regions.length; i++)
			{
				int id = regions[i];
				String terrain = "?";
				String locs = "?";
				try
				{
					MapDefinition m = loader.loadMapDef(id);
					terrain = m == null ? "null" : "OK";
				}
				catch (Exception e)
				{
					terrain = "FAIL " + e.getClass().getSimpleName();
				}
				try
				{
					LocationsDefinition l = loader.loadLocDef(id);
					locs = l == null ? "null"
						: "OK (" + (l.getLocations() == null ? -1 : l.getLocations().size()) + " objects)";
				}
				catch (Exception e)
				{
					locs = "FAIL " + e.getClass().getSimpleName();
				}
				System.out.printf("  %-22s region %-6d terrain=%-18s locations=%s%n",
					labels[i], id, terrain, locs);
			}
		}
	}
}

import net.runelite.cache.definitions.MapDefinition;
import net.runelite.cache.region.RegionLoader;
import net.runelite.cache.fs.Store;
import java.io.File;
import java.util.HashSet;
import java.util.Set;

/**
 * Prints which map regions have terrain data in a given square range.
 * <p>
 * For reading a detached area's real extent off the cache instead of inferring it from one
 * observed position. Guardians of the Rift was first handled from a single reported coordinate
 * and the box was a square too small, so members standing elsewhere in the arena were still
 * misplaced. This is how to size the next one properly: find the square the known point falls
 * in, then see how far the contiguous terrain actually runs.
 * <p>
 * No XTEA keys are needed. Neither terrain nor, as locProbe shows, the object placements are
 * encrypted in this cache, so the null key provider below is not a limitation.
 */
public class RegionProbe
{
	public static void main(String[] args) throws Exception
	{
		File cacheDir = new File(args[0]);
		int x0 = Integer.parseInt(args[1]);
		int x1 = Integer.parseInt(args[2]);
		int y0 = Integer.parseInt(args[3]);
		int y1 = Integer.parseInt(args[4]);

		try (Store store = new Store(cacheDir))
		{
			store.load();
			RegionLoader loader = new RegionLoader(store, region -> null);

			Set<Integer> present = new HashSet<>();
			for (int x = x0; x <= x1; x++)
			{
				for (int y = y0; y <= y1; y++)
				{
					int regionId = (x << 8) | y;
					try
					{
						MapDefinition def = loader.loadMapDef(regionId);
						if (def != null)
						{
							present.add(regionId);
						}
					}
					catch (Exception ignored)
					{
						// No terrain for this region.
					}
				}
			}

			System.out.print("      ");
			for (int x = x0; x <= x1; x++)
			{
				System.out.printf("%4d", x);
			}
			System.out.println("   <- region X");

			for (int y = y1; y >= y0; y--)
			{
				System.out.printf("y%4d ", y);
				for (int x = x0; x <= x1; x++)
				{
					System.out.print(present.contains((x << 8) | y) ? "   #" : "   .");
				}
				System.out.println();
			}
			System.out.println();
			System.out.println("# = terrain exists, . = nothing. " + present.size() + " regions found.");
		}
	}
}
